export interface DailyStats {
  calories: number;
  caloriesGoal: number;
  water: number;
  waterGoal: number;
  steps: number;
  stepsGoal: number;
  exercise: number;
  exerciseGoal: number;
}

export interface FoodLogEntry {
  id: string;
  name: string;
  calories: number;
  timestamp: Date;
}

export interface WorkoutEntry {
  id: string;
  title: string;
  duration: number;
  timestamp: Date;
}

export type Tab = 'dashboard' | 'journal' | 'progress' | 'profile';
export type JournalTab = 'food' | 'exercise' | 'water' | 'stats';

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const suggestWorkout = async (remainingMinutes: number) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `The user needs to complete ${remainingMinutes} more minutes of exercise today. Suggest a quick, effective workout challenge they can do right now. Keep it concise and encouraging.`,
    config: {
      temperature: 0.7,
    },
  });
  return response.text;
};

export const suggestMeal = async (remainingCalories: number) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `The user has ${remainingCalories} calories remaining today. Suggest a healthy meal or snack that fits this budget. Include approximate calorie count.`,
    config: {
      temperature: 0.7,
    },
  });
  return response.text;
};

export const scanFoodImage = async (base64Data: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Data,
          },
        },
        {
          text: "Identify the food in this image and estimate its calorie content. Return ONLY a JSON object with 'name' and 'calories' (integer) properties. Example: {'name': 'Apple', 'calories': 95}",
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          calories: { type: Type.INTEGER },
        },
        required: ["name", "calories"],
      },
    },
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Failed to parse AI food scan response", e);
    return null;
  }
};

import React from 'react';

interface Props {
  value: number;
  max: number;
  size?: number;
  strokeWidth?: number;
  color?: string;
}

const CircularProgress: React.FC<Props> = ({ 
  value, 
  max, 
  size = 120, 
  strokeWidth = 10, 
  color = '#3b82f6' 
}) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = radius * 2 * Math.PI;
  const offset = circumference - (value / max) * circumference;

  return (
    <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="transform -rotate-90">
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke="#e2e8f0"
          strokeWidth={strokeWidth}
          fill="transparent"
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke={color}
          strokeWidth={strokeWidth}
          fill="transparent"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          className="transition-all duration-500 ease-in-out"
        />
      </svg>
      <div className="absolute text-center">
        <span className="text-xl font-bold text-gray-800">{value}/{max}</span>
      </div>
    </div>
  );
};

export default CircularProgress;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart2, 
  User, 
  Camera, 
  Plus, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer,
  Sparkles,
  Search,
  CheckCircle2,
  Clock
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [stats, setStats] = useState<DailyStats>({
    calories: 400,
    caloriesGoal: 1800,
    water: 3,
    waterGoal: 8,
    steps: 4250,
    stepsGoal: 10000,
    exercise: 15,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);

  const handleAddWater = () => {
    setStats(prev => ({ ...prev, water: Math.min(prev.water + 1, prev.waterGoal * 2) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        handleAddFood(result.name, result.calories);
        alert(`AI scanned: ${result.name} (${result.calories} cal)`);
      } else {
        alert("Sorry, couldn't identify the food. Please try again.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard stats={stats} />;
      case 'journal':
        return (
          <Journal 
            stats={stats} 
            foodLog={foodLog} 
            exerciseLog={exerciseLog}
            onAddWater={handleAddWater}
            onAddFood={handleAddFood}
            onAddExercise={handleAddExercise}
          />
        );
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return <Profile />;
      default:
        return <Dashboard stats={stats} />;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen bg-slate-50 flex flex-col relative pb-20 overflow-hidden shadow-xl">
      {/* Header */}
      <header className="p-6 flex justify-between items-center bg-transparent z-10">
        <div>
          <h2 className="text-sm font-medium text-gray-500">Good morning,</h2>
          <h1 className="text-2xl font-bold text-gray-900">Alex</h1>
        </div>
        <div className="flex gap-2">
          <button className="p-2 bg-white rounded-xl shadow-sm border border-gray-100">
            <Search className="w-5 h-5 text-gray-600" />
          </button>
          <button className="p-2 bg-white rounded-xl shadow-sm border border-gray-100">
            <User className="w-5 h-5 text-gray-600" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 px-6">
        {renderContent()}
      </main>

      {/* Floating Action Button (Camera) */}
      <div className="fixed bottom-24 right-6 z-20">
        <label className="cursor-pointer">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            onChange={handleImageUpload}
            disabled={isScanning}
          />
          <div className={`p-4 gradient-bg rounded-2xl shadow-lg text-white transition-transform active:scale-95 ${isScanning ? 'animate-pulse opacity-70' : ''}`}>
            {isScanning ? < Sparkles className="w-6 h-6 animate-spin" /> : <Camera className="w-6 h-6" />}
          </div>
        </label>
      </div>

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white border-t border-gray-100 px-6 py-3 flex justify-between items-center z-20">
        <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} label="Dashboard" onClick={() => setActiveTab('dashboard')} />
        <NavButton active={activeTab === 'journal'} icon={<Calendar />} label="Journal" onClick={() => setActiveTab('journal')} />
        <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Progress" onClick={() => setActiveTab('progress')} />
        <NavButton active={activeTab === 'profile'} icon={<User />} label="Profile" onClick={() => setActiveTab('profile')} />
      </nav>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

const NavButton: React.FC<NavButtonProps> = ({ active, icon, label, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 transition-colors ${active ? 'text-blue-600' : 'text-gray-400'}`}
  >
    <div className={`p-1 ${active ? 'bg-blue-50 rounded-lg' : ''}`}>
      {React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}
    </div>
    <span className="text-[10px] font-medium uppercase tracking-wider">{label}</span>
  </button>
);

export default App;

