interface StatProgressProps {
  icon: React.ReactNode;
  label: string;
  value: number;
  goal: number;
  color: string;
  unit: string;
}

const StatProgress: React.FC<StatProgressProps> = ({ icon, label, value, goal, color, unit }) => {
  const percent = Math.min(100, (value / goal) * 100);
  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center text-sm">
