import { GoogleGenAI, Type } from "@google/genai";

// Always use the process.env.API_KEY directly for initialization as per guidelines.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const suggestWorkout = async (remainingMinutes: number) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `The user needs to complete ${remainingMinutes} more minutes of exercise today. Suggest a quick, effective workout challenge they can do right now. Keep it concise and encouraging.`,
    config: {
      temperature: 0.7,
    },
  });
  return response.text;
};

export const suggestMeal = async (remainingCalories: number) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `The user has ${remainingCalories} calories remaining today. Suggest a healthy meal or snack that fits this budget. Include approximate calorie count.`,
    config: {
      temperature: 0.7,
    },
  });
  return response.text;
};

export const scanFoodImage = async (base64Data: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Data,
          },
        },
        {
          text: "Identify the food in this image and estimate its calorie content. Return ONLY a JSON object with 'name' and 'calories' (integer) properties. Example: {'name': 'Apple', 'calories': 95}",
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          calories: { type: Type.INTEGER },
        },
        required: ["name", "calories"],
      },
    },
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Failed to parse AI food scan response", e);
    return null;
  }
};

