import { GoogleGenAI, Type } from "@google/genai";

// Always use the process.env.API_KEY directly for initialization as per guidelines.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const suggestWorkout = async (remainingMinutes: number) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `The user needs to complete ${remainingMinutes} more minutes of exercise today. Suggest a specific, effective workout activity. Start with a catchy headline, then provide 2-3 brief bullet points on the benefit and a 'Pro-tip' for form. Keep it motivating.`,
    config: {
      temperature: 0.8, // Slightly higher temperature for variety on "Refresh"
    },
  });
  return response.text;
};

export const suggestMeal = async (remainingCalories: number) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `The user has ${remainingCalories} calories remaining today. Suggest a healthy meal or snack that fits this budget. Include approximate calorie count and one key benefit.`,
    config: {
      temperature: 0.7,
    },
  });
  return response.text;
};

export const scanFoodImage = async (base64Data: string) => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Data,
          },
        },
        {
          text: "Identify the food in this image and estimate its calorie content. Return ONLY a JSON object with 'name' and 'calories' (integer) properties. Example: {'name': 'Apple', 'calories': 95}",
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          calories: { type: Type.INTEGER },
        },
        required: ["name", "calories"],
      },
    },
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Failed to parse AI food scan response", e);
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { Sparkles, Utensils, Droplets, Footprints, Timer, ArrowRight, Bell, ChevronDown, ChevronUp, RefreshCw } from 'lucide-react';
import { DailyStats } from '../types';
import { suggestWorkout } from '../services/geminiService';

interface Props {
  stats: DailyStats;
}

const Dashboard: React.FC<Props> = ({ stats }) => {
  const [aiTip, setAiTip] = useState<string>("Loading personalized suggestion...");
  const [isExpanded, setIsExpanded] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const fetchTip = async () => {
    setIsRefreshing(true);
    try {
      const remaining = stats.exerciseGoal - stats.exercise;
      if (remaining > 0) {
        const tip = await suggestWorkout(remaining);
        setAiTip(tip || "Stay active today! Every step counts.");
      } else {
        setAiTip("You've hit your exercise goal! Amazing work. Keep hydrating and recover well. Maybe try some light stretching or meditation to wrap up the day.");
      }
    } catch (error) {
      console.error("Error fetching AI tip:", error);
      setAiTip("Couldn't reach your AI coach. Try again in a moment!");
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchTip();
  }, [stats.exercise]);

  return (
    <div className="space-y-6">
      {/* AI Suggestion Card */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-indigo-50 relative overflow-hidden transition-all duration-300">
        <div className="flex items-start gap-4 mb-3">
          <div className={`p-2 bg-indigo-50 rounded-xl text-indigo-600 ${isRefreshing ? 'animate-spin' : ''}`}>
            <Sparkles className="w-5 h-5" />
          </div>
          <div className="flex-1">
            <div className="flex justify-between items-center mb-1">
              <h3 className="text-sm font-semibold text-indigo-900">AI Coach Says</h3>
              <button 
                onClick={fetchTip}
                disabled={isRefreshing}
                className="p-1 text-indigo-400 hover:text-indigo-600 transition-colors disabled:opacity-50"
                title="Refresh suggestion"
              >
                <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
              </button>
            </div>

            <div className={`text-sm text-gray-600 leading-relaxed italic transition-all duration-300 ${!isExpanded ? 'line-clamp-3' : ''}`}>
              {aiTip.split('\n').map((line, i) => (
                <p key={i} className={line.startsWith('-') || line.startsWith('*') ? 'ml-2' : 'mb-1'}>
                  {line}
                </p>
              ))}
            </div>

            <div className="flex items-center gap-4 mt-3">
              <button 
                onClick={() => setIsExpanded(!isExpanded)}
                className="text-indigo-600 text-xs font-bold flex items-center gap-1 hover:underline"
              >
                {isExpanded ? (
                  <>Show Less <ChevronUp className="w-3 h-3" /></>
                ) : (
                  <>Show More <ChevronDown className="w-3 h-3" /></>
                )}
              </button>
            </div>
          </div>
        </div>

        {isRefreshing && (
          <div className="absolute inset-0 bg-white/40 backdrop-blur-[1px] flex items-center justify-center">
             <div className="flex items-center gap-2 text-indigo-600 font-medium text-xs">
               <RefreshCw className="w-3 h-3 animate-spin" /> Thinking...
             </div>
          </div>
        )}
      </div>

      {/* Daily Summary */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-gray-50">
        <div className="flex items-center gap-2 mb-6">
          <CalendarIcon className="w-5 h-5 text-indigo-600" />
          <h2 className="text-lg font-bold text-gray-900">Daily Summary</h2>
        </div>

        <div className="space-y-6">
          <StatProgress 
            icon={<Utensils className="w-4 h-4" />} 
            label="Calories" 
            value={stats.calories} 
            goal={stats.caloriesGoal} 
            color="bg-orange-500" 
            unit="" 
          />
          <StatProgress 
            icon={<Droplets className="w-4 h-4" />} 
            label="Water" 
            value={stats.water} 
            goal={stats.waterGoal} 
            color="bg-blue-500" 
            unit="glasses" 
          />
          <StatProgress 
            icon={<Footprints className="w-4 h-4" />} 
            label="Steps" 
            value={stats.steps} 
            goal={stats.stepsGoal} 
            color="bg-green-500" 
            unit="" 
          />
          <StatProgress 
            icon={<Timer className="w-4 h-4" />} 
            label="Exercise" 
            value={stats.exercise} 
            goal={stats.exerciseGoal} 
            color="bg-purple-500" 
            unit="min" 
          />
        </div>
      </div>

      {/* Secondary Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white rounded-3xl p-6 shadow-sm border border-emerald-50 text-center">
          <div className="w-12 h-12 bg-emerald-50 rounded-full flex items-center justify-center mx-auto mb-3">
            <Footprints className="w-6 h-6 text-emerald-500" />
          </div>
          <p className="text-2xl font-bold text-emerald-600">
            {Math.round((stats.steps / stats.stepsGoal) * 100)}%
          </p>
          <p className="text-xs text-gray-500 font-medium">Steps Goal</p>
        </div>
        <div className="bg-white rounded-3xl p-6 shadow-sm border border-amber-50 text-center">
          <div className="w-12 h-12 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-3">
            <Bell className="w-6 h-6 text-amber-500" />
          </div>
          <p className="text-2xl font-bold text-amber-600">12</p>
          <p className="text-xs text-gray-500 font-medium">Days streak</p>
        </div>
      </div>
    </div>
  );
};

const CalendarIcon = ({ className }: { className?: string }) => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
    <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
