import { ChefHat, Plus, X, Sparkles, Clock, Utensils, ChevronDown, ChevronUp, CheckCircle2 } from 'lucide-react';
import { getRecipeRecommendations } from '../services/geminiService';
import { Recipe } from '../types';

const Recipes: React.FC = () => {
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const addIngredient = () => {
    if (inputValue.trim() && !ingredients.includes(inputValue.trim())) {
      setIngredients([...ingredients, inputValue.trim()]);
      setInputValue('');
    }
  };

  const removeIngredient = (ingredient: string) => {
    setIngredients(ingredients.filter(i => i !== ingredient));
  };

  const findRecipes = async () => {
    if (ingredients.length === 0) return;
    setIsLoading(true);
    const results = await getRecipeRecommendations(ingredients);
    setRecipes(results);
    setIsLoading(false);
  };

  return (
    <div className="space-y-6 pb-10 animate-in fade-in duration-500">
      <div className="mb-2">
        <h1 className="text-2xl font-bold text-gray-900">AI Kitchen</h1>
        <p className="text-sm text-gray-500">Tell us what's in your pantry</p>
      </div>

      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-50">
        <label className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3 block">Available Ingredients</label>

        <div className="flex flex-wrap gap-2 mb-4">
          {ingredients.map(ing => (
            <span key={ing} className="bg-indigo-50 text-indigo-600 px-3 py-1.5 rounded-xl text-sm font-bold flex items-center gap-2 group">
              {ing}
              <button onClick={() => removeIngredient(ing)} className="p-0.5 hover:bg-indigo-100 rounded-md transition-colors">
                <X className="w-3 h-3" />
              </button>
            </span>
          ))}
          {ingredients.length === 0 && (
            <p className="text-sm text-gray-400 italic">No ingredients added yet...</p>
          )}
        </div>

        <div className="flex gap-2">
          <input 
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && addIngredient()}
            placeholder="e.g. Chicken breast"
            className="flex-1 bg-slate-50 border border-gray-100 rounded-2xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
          />
          <button 
            onClick={addIngredient}
            className="p-3 bg-white border border-gray-100 rounded-2xl text-indigo-600 hover:bg-indigo-50 transition-colors"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>

        <button 
          onClick={findRecipes}
          disabled={ingredients.length === 0 || isLoading}
          className="w-full mt-4 py-4 gradient-bg text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 disabled:opacity-50 disabled:shadow-none transition-all flex items-center justify-center gap-2 active:scale-[0.98]"
        >
          {isLoading ? (
            <>
              <Sparkles className="w-5 h-5 animate-spin" />
              Generating Recipes...
            </>
          ) : (
            <>
              <ChefHat className="w-5 h-5" />
              Find Recipes
            </>
          )}
        </button>
      </div>

      {/* Recipe Results */}
      <div className="space-y-4">
        {recipes.map(recipe => (
          <div key={recipe.id} className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-50 transition-all">
            <div className="p-6">
              <div className="flex justify-between items-start mb-2">
                <h3 className="text-lg font-black text-gray-900 leading-tight flex-1 mr-4">{recipe.title}</h3>
                <div className="bg-indigo-50 px-3 py-1 rounded-full flex items-center gap-1">
                  <span className="text-xs font-black text-indigo-600">{recipe.calories} cal</span>
                </div>
              </div>
              <p className="text-xs text-gray-500 mb-4">{recipe.description}</p>

              <div className="flex items-center gap-4 mb-4">
                <div className="flex items-center gap-1.5 text-xs font-bold text-gray-400">
                  <Clock className="w-3 h-3" /> {recipe.prepTime}
                </div>
                <div className="flex items-center gap-1.5 text-xs font-bold text-gray-400">
                  <Utensils className="w-3 h-3" /> {recipe.ingredientsUsed?.length || 0} items used
                </div>
              </div>

              <button 
                onClick={() => setExpandedId(expandedId === recipe.id ? null : recipe.id)}
                className="w-full py-2 bg-slate-50 rounded-xl text-xs font-bold text-gray-500 flex items-center justify-center gap-1 hover:bg-slate-100 transition-colors"
              >
                {expandedId === recipe.id ? (
                  <>Hide Instructions <ChevronUp className="w-3 h-3" /></>
                ) : (
                  <>Show How to Make <ChevronDown className="w-3 h-3" /></>
                )}
              </button>
            </div>

            {expandedId === recipe.id && (
              <div className="px-6 pb-6 pt-2 border-t border-slate-50 animate-in slide-in-from-top-2 duration-300">
                <div className="mb-6">
                  <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-3">Steps</h4>
                  <div className="space-y-4">
                    {recipe.instructions.map((step, idx) => (
                      <div key={idx} className="flex gap-4">
                        <div className="w-6 h-6 bg-indigo-50 rounded-full flex items-center justify-center text-[10px] font-black text-indigo-600 flex-shrink-0">
                          {idx + 1}
                        </div>
                        <p className="text-sm text-gray-600 leading-relaxed">{step}</p>
                      </div>
                    ))}
                  </div>
                </div>

                {recipe.missingIngredients && recipe.missingIngredients.length > 0 && (
                  <div>
                    <h4 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-2">Extra items needed</h4>
                    <div className="flex flex-wrap gap-2">
                      {recipe.missingIngredients.map(mi => (
                        <span key={mi} className="text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-1 rounded-lg">
                          + {mi}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}

        {!isLoading && recipes.length === 0 && ingredients.length > 0 && (
          <div className="py-12 flex flex-col items-center text-center px-8">
            <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
              <ChefHat className="w-8 h-8 text-slate-300" />
            </div>
            <h4 className="text-gray-900 font-bold mb-1">Click 'Find Recipes'</h4>
            <p className="text-xs text-gray-500">I'll create custom healthy recipes based on your ingredients!</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Recipes;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart2, 
  User, 
  Camera, 
  Plus, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer,
  Sparkles,
  Search,
  CheckCircle2,
  Clock,
  X,
  Zap,
  ChefHat
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import Recipes from './pages/Recipes';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [stats, setStats] = useState<DailyStats>({
    calories: 400,
    caloriesGoal: 1800,
    water: 3,
    waterGoal: 8,
    steps: 4250,
    stepsGoal: 10000,
    exercise: 15,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  const handleAddWater = () => {
    setStats(prev => ({ ...prev, water: Math.min(prev.water + 1, prev.waterGoal * 2) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      } else {
        alert("Sorry, couldn't identify the food. Please try again.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const confirmPendingFood = () => {
    if (pendingFood) {
      handleAddFood(pendingFood.name, pendingFood.calories);
      setPendingFood(null);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard stats={stats} />;
      case 'journal':
        return (
          <Journal 
            stats={stats} 
            foodLog={foodLog} 
            exerciseLog={exerciseLog}
            onAddWater={handleAddWater}
            onAddFood={handleAddFood}
            onAddExercise={handleAddExercise}
          />
        );
      case 'recipes':
        return <Recipes />;
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return <Profile />;
      default:
        return <Dashboard stats={stats} />;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen bg-slate-50 flex flex-col relative pb-20 overflow-hidden shadow-xl">
      {/* Header */}
      <header className="p-6 flex justify-between items-center bg-transparent z-10">
        <div>
          <h2 className="text-sm font-medium text-gray-500">Good morning,</h2>
          <h1 className="text-2xl font-bold text-gray-900">Alex</h1>
        </div>
        <div className="flex gap-2">
          <button className="p-2 bg-white rounded-xl shadow-sm border border-gray-100">
            <Search className="w-5 h-5 text-gray-600" />
          </button>
          <button className="p-2 bg-white rounded-xl shadow-sm border border-gray-100">
            <User className="w-5 h-5 text-gray-600" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 px-6">
        {renderContent()}
      </main>

      {/* Floating Action Button (Camera) */}
      <div className="fixed bottom-24 right-6 z-20">
        <label className="cursor-pointer">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            onChange={handleImageUpload}
            disabled={isScanning}
          />
          <div className={`p-4 gradient-bg rounded-2xl shadow-lg text-white transition-all transform active:scale-95 hover:scale-105 ${isScanning ? 'opacity-50' : ''}`}>
            {isScanning ? <Clock className="w-6 h-6 animate-spin" /> : <Camera className="w-6 h-6" />}
          </div>
        </label>
      </div>

      {/* AI Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/80 backdrop-blur-sm z-[100] flex flex-col items-center justify-center animate-in fade-in duration-300">
          <div className="relative">
            <div className="w-24 h-24 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <Sparkles className="w-10 h-10 text-indigo-600 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
          </div>
          <h3 className="mt-6 text-lg font-bold text-gray-900">AI Analysis in Progress</h3>
          <p className="text-sm text-gray-500 max-w-[200px] text-center mt-2">Identifying your meal and estimating nutritional facts...</p>
        </div>
      )}

      {/* AI Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[110] flex items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
          <div className="bg-white w-full rounded-[32px] p-8 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 gradient-bg"></div>
            <button 
              onClick={() => setPendingFood(null)}
              className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors"
            >
              <X className="w-5 h-5 text-gray-400" />
            </button>

            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-4 transform -rotate-3">
                <Utensils className="w-10 h-10 text-indigo-600" />
              </div>

              <div className="flex items-center gap-2 mb-1">
                <Zap className="w-4 h-4 text-amber-500 fill-amber-500" />
                <span className="text-[10px] font-bold text-amber-600 uppercase tracking-widest">AI Detection Successful</span>
              </div>

              <h3 className="text-2xl font-black text-gray-900 mb-2">{pendingFood.name}</h3>

              <div className="bg-indigo-50 rounded-2xl px-6 py-3 mb-8">
                <span className="text-3xl font-black text-indigo-600">{pendingFood.calories}</span>
                <span className="ml-1 text-sm font-bold text-indigo-400 uppercase">kcal</span>
              </div>

              <div className="grid grid-cols-2 gap-3 w-full">
                <button 
                  onClick={() => setPendingFood(null)}
                  className="py-4 rounded-2xl border border-gray-100 text-gray-500 font-bold hover:bg-gray-50 transition-colors"
                >
                  Discard
                </button>
                <button 
                  onClick={confirmPendingFood}
                  className="py-4 rounded-2xl gradient-bg text-white font-bold shadow-lg shadow-indigo-100 hover:opacity-90 transition-opacity flex items-center justify-center gap-2"
                >
                  <Plus className="w-5 h-5" /> Add to Log
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white border-t border-gray-100 px-4 py-3 flex justify-between items-center z-20">
        <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} label="Dash" onClick={() => setActiveTab('dashboard')} />
        <NavButton active={activeTab === 'journal'} icon={<Calendar />} label="Journal" onClick={() => setActiveTab('journal')} />
        <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} label="Kitchen" onClick={() => setActiveTab('recipes')} />
        <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Stats" onClick={() => setActiveTab('progress')} />
        <NavButton active={activeTab === 'profile'} icon={<User />} label="Me" onClick={() => setActiveTab('profile')} />
      </nav>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

const NavButton: React.FC<NavButtonProps> = ({ active, icon, label, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col items-center gap-1 transition-colors ${active ? 'text-blue-600' : 'text-gray-400'}`}
  >
    <div className={`p-1 ${active ? 'bg-blue-50 rounded-lg' : ''}`}>
      {React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}
    </div>
    <span className="text-[10px] font-medium uppercase tracking-wider">{label}</span>
  </button>
);

export default App;

