export type Tab = 'dashboard' | 'journal' | 'recipes' | 'progress' | 'profile';
export type JournalTab = 'food' | 'exercise' | 'water' | 'stats';

import React, { useState } from 'react';
import { 
  Target, 
  Scale, 
  User, 
  Zap, 
  ChevronRight, 
  ArrowLeft, 
  CheckCircle2, 
  Activity,
  Dumbbell,
  Heart,
  Flame
} from 'lucide-react';
import { UserProfile } from '../types';

interface Props {
  onComplete: (profile: UserProfile) => void;
}

const Onboarding: React.FC<Props> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [profile, setProfile] = useState<UserProfile>({
    name: 'Alex',
    goal: 'maintain',
    weight: 70,
    height: 175,
    age: 25,
    activityLevel: 'moderate'
  });

  const nextStep = () => setStep(s => s + 1);
  const prevStep = () => setStep(s => s - 1);

  const steps = [
    { title: "What's your goal?", subtitle: "We'll tailor the experience for you" },
    { title: "About you", subtitle: "Help us calculate your daily needs" },
    { title: "Activity level", subtitle: "How active are you on a weekly basis?" }
  ];

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-500">
            <GoalCard 
              selected={profile.goal === 'loss'} 
              onClick={() => setProfile({ ...profile, goal: 'loss' })}
              icon={<Flame className="w-6 h-6" />}
              title="Weight Loss"
              description="Burn fat and get leaner"
              color="text-orange-500"
              bg="bg-orange-50"
            />
            <GoalCard 
              selected={profile.goal === 'gain'} 
              onClick={() => setProfile({ ...profile, goal: 'gain' })}
              icon={<Dumbbell className="w-6 h-6" />}
              title="Muscle Gain"
              description="Build strength and mass"
              color="text-indigo-500"
              bg="bg-indigo-50"
            />
            <GoalCard 
              selected={profile.goal === 'maintain'} 
              onClick={() => setProfile({ ...profile, goal: 'maintain' })}
              icon={<Target className="w-6 h-6" />}
              title="Maintain Weight"
              description="Stay fit and healthy"
              color="text-emerald-500"
              bg="bg-emerald-50"
            />
            <GoalCard 
              selected={profile.goal === 'healthy'} 
              onClick={() => setProfile({ ...profile, goal: 'healthy' })}
              icon={<Heart className="w-6 h-6" />}
              title="Stay Healthy"
              description="Improve overall wellness"
              color="text-pink-500"
              bg="bg-pink-50"
            />
          </div>
        );
      case 1:
        return (
          <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white p-6 rounded-[32px] shadow-sm border border-gray-100 space-y-6">
              <InputGroup 
                label="Weight (kg)" 
                value={profile.weight} 
                onChange={(v) => setProfile({ ...profile, weight: Number(v) })}
                icon={<Scale className="w-5 h-5" />}
              />
              <InputGroup 
                label="Height (cm)" 
                value={profile.height} 
                onChange={(v) => setProfile({ ...profile, height: Number(v) })}
                icon={<Activity className="w-5 h-5" />}
              />
              <InputGroup 
                label="Age" 
                value={profile.age} 
                onChange={(v) => setProfile({ ...profile, age: Number(v) })}
                icon={<User className="w-5 h-5" />}
              />
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-500">
            <ActivityOption 
              selected={profile.activityLevel === 'sedentary'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'sedentary' })}
              title="Sedentary"
              description="Little to no exercise"
            />
            <ActivityOption 
              selected={profile.activityLevel === 'moderate'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'moderate' })}
              title="Moderate"
              description="Exercise 3-4 times a week"
            />
            <ActivityOption 
              selected={profile.activityLevel === 'active'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'active' })}
              title="Highly Active"
              description="Daily intense exercise"
            />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col p-6 animate-in fade-in duration-700">
      {/* Progress Bar */}
      <div className="flex gap-2 mb-10 pt-4">
        {steps.map((_, i) => (
          <div 
            key={i} 
            className={`h-1.5 flex-1 rounded-full transition-all duration-500 ${i <= step ? 'bg-indigo-600' : 'bg-gray-200'}`} 
          />
        ))}
      </div>

      <div className="flex-1">
        <h1 className="text-3xl font-black text-gray-900 mb-2">{steps[step].title}</h1>
        <p className="text-gray-500 mb-8 font-medium">{steps[step].subtitle}</p>

        {renderStep()}
      </div>

      <div className="flex gap-4 mt-8">
        {step > 0 && (
          <button 
            onClick={prevStep}
            className="p-5 bg-white border border-gray-100 rounded-3xl text-gray-400 hover:text-gray-600 transition-all"
          >
            <ArrowLeft className="w-6 h-6" />
          </button>
        )}
        <button 
          onClick={step === steps.length - 1 ? () => onComplete(profile) : nextStep}
          className="flex-1 py-5 gradient-bg text-white font-bold rounded-[32px] shadow-xl shadow-indigo-100 flex items-center justify-center gap-2 active:scale-95 transition-all"
        >
          {step === steps.length - 1 ? 'Finish Setup' : 'Continue'}
          <ChevronRight className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
};

const GoalCard = ({ selected, onClick, icon, title, description, color, bg }: any) => (
  <button 
    onClick={onClick}
    className={`w-full p-6 rounded-[32px] flex items-center gap-4 border-2 transition-all ${selected ? 'border-indigo-600 bg-white shadow-xl scale-[1.02]' : 'border-transparent bg-white shadow-sm'}`}
  >
    <div className={`w-14 h-14 ${bg} ${color} rounded-2xl flex items-center justify-center`}>
      {icon}
    </div>
    <div className="text-left flex-1">
      <h3 className="font-black text-gray-900">{title}</h3>
      <p className="text-xs text-gray-500 font-medium">{description}</p>
    </div>
    {selected && <CheckCircle2 className="w-6 h-6 text-indigo-600" />}
  </button>
);

const ActivityOption = ({ selected, onClick, title, description }: any) => (
  <button 
    onClick={onClick}
    className={`w-full p-6 rounded-[32px] flex items-center justify-between border-2 transition-all ${selected ? 'border-indigo-600 bg-white shadow-xl scale-[1.02]' : 'border-transparent bg-white shadow-sm'}`}
