              onClick={() => setProfile({ ...profile, goal: 'loss' })}
              icon={<Flame className="w-6 h-6" />}
              title="Weight Loss"
              description="Burn fat and get leaner"
              color="text-orange-500"
              bg="bg-orange-50"
            />
            <GoalCard 
              selected={profile.goal === 'gain'} 
              onClick={() => setProfile({ ...profile, goal: 'gain' })}
              icon={<Dumbbell className="w-6 h-6" />}
              title="Muscle Gain"
              description="Build strength and mass"
              color="text-indigo-500"
              bg="bg-indigo-50"
            />
            <GoalCard 
              selected={profile.goal === 'maintain'} 
              onClick={() => setProfile({ ...profile, goal: 'maintain' })}
              icon={<Target className="w-6 h-6" />}
              title="Maintain Weight"
              description="Stay fit and healthy"
              color="text-emerald-500"
              bg="bg-emerald-50"
            />
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white p-6 rounded-[32px] shadow-sm border border-gray-100 space-y-6">
              <InputGroup 
                label="Weight (kg)" 
                value={profile.weight} 
                onChange={(v) => setProfile({ ...profile, weight: Number(v) })}
                icon={<Scale className="w-5 h-5" />}
              />
              <InputGroup 
                label="Height (cm)" 
                value={profile.height} 
                onChange={(v) => setProfile({ ...profile, height: Number(v) })}
                icon={<Activity className="w-5 h-5" />}
              />
              <InputGroup 
                label="Age" 
                value={profile.age} 
                onChange={(v) => setProfile({ ...profile, age: Number(v) })}
                icon={<User className="w-5 h-5" />}
              />
            </div>
          </div>
        );
      case 3:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-500">
            <ActivityOption 
              selected={profile.activityLevel === 'sedentary'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'sedentary' })}
              title="Sedentary"
              description="Little to no exercise"
            />
            <ActivityOption 
              selected={profile.activityLevel === 'moderate'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'moderate' })}
              title="Moderate"
              description="Exercise 3-4 times a week"
            />
            <ActivityOption 
              selected={profile.activityLevel === 'active'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'active' })}
              title="Highly Active"
              description="Daily intense exercise"
            />
          </div>
        );
      case 4:
        return (
          <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
