          ) : (
            <>
              <ChefHat className="w-5 h-5" />
              Find {profile?.goal || ''} Recipes
            </>
          )}
        </button>
      </div>

      {/* Recipe Results */}
      <div className="space-y-4">
        {recipes.map(recipe => (
          <div key={recipe.id} className="bg-white rounded-3xl overflow-hidden shadow-sm border border-gray-50 transition-all">
            <div className="p-6">
              <div className="flex justify-between items-start mb-2">
