                <div className="bg-indigo-50 px-3 py-1 rounded-full flex items-center gap-1">
                  <span className="text-xs font-black text-indigo-600">{recipe.calories} cal</span>
                </div>
              </div>
              <p className="text-xs text-gray-500 mb-4">{recipe.description}</p>

