                onClick={() => setExpandedId(expandedId === recipe.id ? null : recipe.id)}
                className="w-full py-2 bg-slate-50 rounded-xl text-xs font-bold text-gray-500 flex items-center justify-center gap-1 hover:bg-slate-100 transition-colors"
