                )}
              </div>
            )}
          </div>
        ))}

        {!isLoading && recipes.length === 0 && ingredients.length > 0 && (
          <div className="py-12 flex flex-col items-center text-center px-8">
            <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
              <ChefHat className="w-8 h-8 text-slate-300" />
            </div>
            <h4 className="text-gray-900 font-bold mb-1">Click 'Find Recipes'</h4>
            <p className="text-xs text-gray-500">I'll create custom recipes tailored to your goal!</p>
          </div>
        )}
      </div>
    </div>
  );
};

