import { GoogleGenAI, Type } from "@google/genai";
import { UserProfile, GoalSheet } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates a structured personalized health roadmap (Goal Sheet).
 */
export const generateGoalPlan = async (profile: UserProfile): Promise<GoalSheet | null> => {
  const prompt = `
    Generate a personalized health roadmap for ${profile.name}.
    Biometrics: ${profile.weight}kg, ${profile.height}cm, ${profile.age} years old.
    Goal: ${profile.goal}.
    Activity: ${profile.activityLevel}.

    Create a JSON response with:
    1. A catchy title for the plan.
    2. A 2-sentence summary of the focus.
    3. Exactly 3 milestones (title and short description).
    4. A daily piece of advice.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          summary: { type: Type.STRING },
          milestones: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                title: { type: Type.STRING },
                description: { type: Type.STRING },
              },
              required: ["id", "title", "description"],
            },
          },
          dailyAdvice: { type: Type.STRING },
        },
        required: ["title", "summary", "milestones", "dailyAdvice"],
      },
    },
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Failed to parse goal plan", e);
    return null;
  }
};

/**
 * Suggests a personalized workout based on user goals and biometrics.
 */
export const suggestWorkout = async (remainingMinutes: number, profile: UserProfile | null) => {
  const profileContext = profile 
    ? `User Profile: Goal is ${profile.goal}, Age ${profile.age}, Current Weight ${profile.weight}kg, Activity Level: ${profile.activityLevel}.`
    : "User Profile: Goal is general health.";

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${profileContext} The user needs to complete ${remainingMinutes} more minutes of exercise today. 
    Suggest a specific, effective workout activity tailored to their goal. 
    Start with a catchy headline, then provide 2-3 brief bullet points on the benefit and a 'Pro-tip' for form.`,
    config: {
      temperature: 0.8,
    },
  });
  return response.text;
};

/**
 * Recommends recipes based on available ingredients and user dietary goals.
 */
export const getRecipeRecommendations = async (ingredients: string[], profile: UserProfile | null) => {
  const profileContext = profile 
    ? `User Profile: Goal is ${profile.goal}, Current Weight ${profile.weight}kg, Height ${profile.height}cm. 
       Adjust recommendations: 'loss' = low calorie/high volume, 'gain' = high protein/calorie dense, 'maintain'/'healthy' = balanced.`
    : "User Profile: Healthy balanced diet.";

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `${profileContext} The user has these ingredients: ${ingredients.join(', ')}. 
    Suggest 3 healthy recipe ideas that use these ingredients.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            calories: { type: Type.INTEGER },
            prepTime: { type: Type.STRING },
            ingredientsUsed: { type: Type.ARRAY, items: { type: Type.STRING } },
            missingIngredients: { type: Type.ARRAY, items: { type: Type.STRING } },
            instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["id", "title", "description", "calories", "prepTime", "instructions"],
        },
      },
    },
  });

  try {
    return JSON.parse(response.text || '[]');
  } catch (e) {
    console.error("Failed to parse recipe recommendations", e);
    return [];
  }
};

/**
 * Standard food scanner.
 */
export const scanFoodImage = async (base64Data: string) => {
  const response = await ai.models.generateContent({
