      <input 
        type="number" 
        value={value} 
        onChange={(e) => onChange(e.target.value)}
        className="w-full bg-slate-50 border border-transparent focus:border-indigo-600 focus:bg-white rounded-2xl py-4 pl-12 pr-4 font-bold text-gray-900 outline-none transition-all"
      />
