import React, { useState, useEffect } from 'react';
import { 
  Target, 
  Scale, 
  User, 
  ChevronRight, 
  ArrowLeft, 
  CheckCircle2, 
  Activity,
  Dumbbell,
  Heart,
  Flame,
  LogIn,
  Sparkles,
  Award,
  TrendingUp,
  Mail
} from 'lucide-react';
import { UserProfile, GoalSheet } from '../types';
import { generateGoalPlan } from '../services/geminiService';

interface Props {
  onComplete: (profile: UserProfile) => void;
  onSkipAll: () => void;
}

const Onboarding: React.FC<Props> = ({ onComplete, onSkipAll }) => {
  const [step, setStep] = useState(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [goalPlan, setGoalPlan] = useState<GoalSheet | null>(null);
  const [showEmailForm, setShowEmailForm] = useState(false);
  const [email, setEmail] = useState('');

  // Local state for UI inputs to handle unit conversions easily
  const [unitSystem, setUnitSystem] = useState<'metric' | 'imperial'>('metric');
  const [displayWeight, setDisplayWeight] = useState('70');
  const [displayHeightCm, setDisplayHeightCm] = useState('175');
  const [heightFt, setHeightFt] = useState('5');
  const [heightIn, setHeightIn] = useState('9');

  const [profile, setProfile] = useState<UserProfile>({
    name: '',
    goal: 'maintain',
    weight: 70,
    height: 175,
    age: 25,
    activityLevel: 'moderate',
    isGuest: true,
    unitSystem: 'metric'
  });

  // Conversion helpers
  const lbsToKg = (lbs: number) => lbs * 0.453592;
  const kgToLbs = (kg: number) => kg / 0.453592;
  const ftInToCm = (ft: number, inc: number) => (ft * 30.48) + (inc * 2.54);
  const cmToFtIn = (cm: number) => {
    const totalInches = cm / 2.54;
    const ft = Math.floor(totalInches / 12);
    const inc = Math.round(totalInches % 12);
    return { ft, inc };
  };

  // Sync internal profile when unit system or display values change
  useEffect(() => {
    let finalWeight = profile.weight;
    let finalHeight = profile.height;

    if (unitSystem === 'metric') {
      finalWeight = parseFloat(displayWeight) || 0;
      finalHeight = parseFloat(displayHeightCm) || 0;
    } else {
      finalWeight = lbsToKg(parseFloat(displayWeight) || 0);
      finalHeight = ftInToCm(parseFloat(heightFt) || 0, parseFloat(heightIn) || 0);
    }

    setProfile(prev => ({
      ...prev,
      weight: finalWeight,
      height: finalHeight,
      unitSystem
    }));
  }, [displayWeight, displayHeightCm, heightFt, heightIn, unitSystem]);

  const handleUnitToggle = (newSystem: 'metric' | 'imperial') => {
    if (newSystem === unitSystem) return;

    if (newSystem === 'imperial') {
      // Metric to Imperial
      setDisplayWeight(Math.round(kgToLbs(parseFloat(displayWeight))).toString());
      const { ft, inc } = cmToFtIn(parseFloat(displayHeightCm));
      setHeightFt(ft.toString());
      setHeightIn(inc.toString());
    } else {
      // Imperial to Metric
      setDisplayWeight(Math.round(lbsToKg(parseFloat(displayWeight))).toString());
      const cm = ftInToCm(parseFloat(heightFt), parseFloat(heightIn));
      setDisplayHeightCm(Math.round(cm).toString());
    }
    setUnitSystem(newSystem);
  };

  const nextStep = () => setStep(s => s + 1);
  const prevStep = () => setStep(s => s - 1);

  const steps = [
    { title: "What's your name?", subtitle: "Personalized coaching starts here", canSkip: false },
    { title: "What's your goal?", subtitle: "We'll tailor the experience for you", canSkip: true },
    { title: "About you", subtitle: "Help us calculate your daily needs", canSkip: true },
    { title: "Activity level", subtitle: "How active are you on a weekly basis?", canSkip: true },
    { title: "Secure your account", subtitle: "Save progress across all your devices", canSkip: true }
  ];

  const handleFinish = async (provider: 'email' | 'google' | 'facebook' | 'apple' | 'guest') => {
    setIsGenerating(true);
    const finalProfile: UserProfile = {
      ...profile,
      name: profile.name || 'Friend',
      isGuest: provider === 'guest',
      authProvider: provider !== 'guest' ? provider : undefined,
      email: provider === 'email' ? email : undefined
    };

    const plan = await generateGoalPlan(finalProfile);
    setGoalPlan(plan);
    setIsGenerating(false);
    setStep(steps.length);
  };

  const finalizeOnboarding = () => {
    onComplete({ ...profile, goalSheet: goalPlan || undefined });
  };

  if (isGenerating) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-500">
        <div className="relative mb-8">
          <div className="w-24 h-24 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          <Sparkles className="w-10 h-10 text-indigo-600 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
        </div>
        <h2 className="text-2xl font-black text-gray-900 mb-2">Creating Your Roadmap</h2>
        <p className="text-gray-500 max-w-xs leading-relaxed">
          Our AI is calculating milestones based on your goals and biometrics...
        </p>
      </div>
    );
  }

  if (step === steps.length && goalPlan) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
        <div className="flex-1 overflow-y-auto pt-4 pb-8 no-scrollbar">
          <div className="flex flex-col items-center text-center mb-8">
            <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-white mb-4 shadow-xl shadow-indigo-200">
              <Award className="w-10 h-10" />
            </div>
            <h1 className="text-3xl font-black text-gray-900 mb-1">Your Blueprint</h1>
            <p className="text-indigo-600 font-bold text-sm uppercase tracking-widest">{goalPlan.title}</p>
          </div>

          <div className="bg-white rounded-[32px] p-8 shadow-sm border border-gray-100 mb-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50/50 rounded-full -mr-16 -mt-16" />
            <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">The Focus</h3>
            <p className="text-gray-700 font-medium leading-relaxed">{goalPlan.summary}</p>
          </div>

          <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 ml-2">Milestones</h3>
          <div className="space-y-4 mb-8">
            {goalPlan.milestones.map((m, idx) => (
              <div key={m.id} className="bg-white p-5 rounded-3xl flex gap-4 shadow-sm border border-gray-50">
                <div className="w-10 h-10 bg-slate-50 rounded-2xl flex items-center justify-center text-indigo-600 font-black text-xs shrink-0">
                  0{idx + 1}
                </div>
                <div>
                  <h4 className="font-bold text-gray-900">{m.title}</h4>
                  <p className="text-xs text-gray-500 mt-1">{m.description}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-xl shadow-indigo-100">
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp className="w-4 h-4 text-indigo-200" />
              <span className="text-[10px] font-black uppercase tracking-widest text-indigo-200">Expert Tip</span>
            </div>
            <p className="text-sm font-medium leading-relaxed italic">"{goalPlan.dailyAdvice}"</p>
          </div>
        </div>

        <button 
          onClick={finalizeOnboarding}
          className="w-full py-5 gradient-bg text-white font-bold rounded-[32px] shadow-2xl shadow-indigo-200 flex items-center justify-center gap-2 active:scale-95 transition-all mt-4"
        >
          Start My Journey
          <ChevronRight className="w-5 h-5" />
        </button>
      </div>
    );
  }

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
             <div className="bg-white p-8 rounded-[32px] shadow-sm border border-gray-100">
                <div className="space-y-4">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Your Name</label>
                  <input 
                    type="text" 
                    autoFocus
                    value={profile.name} 
                    placeholder="Enter your name"
                    onChange={(e) => setProfile({ ...profile, name: e.target.value })}
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-2xl py-4 px-6 font-bold text-gray-900 outline-none transition-all"
                  />
                </div>
             </div>
          </div>
        );
      case 1:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-500">
            <GoalCard 
              selected={profile.goal === 'loss'} 
              onClick={() => setProfile({ ...profile, goal: 'loss' })}
              icon={<Flame className="w-6 h-6" />}
              title="Weight Loss"
              description="Burn fat and get leaner"
              color="text-orange-500"
              bg="bg-orange-50"
            />
            <GoalCard 
              selected={profile.goal === 'gain'} 
              onClick={() => setProfile({ ...profile, goal: 'gain' })}
              icon={<Dumbbell className="w-6 h-6" />}
              title="Muscle Gain"
              description="Build strength and mass"
              color="text-indigo-500"
              bg="bg-indigo-50"
            />
            <GoalCard 
              selected={profile.goal === 'maintain'} 
              onClick={() => setProfile({ ...profile, goal: 'maintain' })}
              icon={<Target className="w-6 h-6" />}
              title="Maintain Weight"
              description="Stay fit and healthy"
              color="text-emerald-500"
              bg="bg-emerald-50"
            />
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white p-6 rounded-[32px] shadow-sm border border-gray-100 space-y-6">
              {/* Unit Toggle */}
              <div className="flex bg-slate-50 p-1 rounded-2xl border border-gray-100">
                <button 
                  onClick={() => handleUnitToggle('metric')}
                  className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${unitSystem === 'metric' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-400'}`}
                >
                  Metric
                </button>
                <button 
                  onClick={() => handleUnitToggle('imperial')}
                  className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${unitSystem === 'imperial' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-400'}`}
                >
                  Imperial
                </button>
              </div>

              <InputGroup 
                label={`Weight (${unitSystem === 'metric' ? 'kg' : 'lbs'})`} 
                value={displayWeight} 
                onChange={(v: string) => setDisplayWeight(v)}
                icon={<Scale className="w-5 h-5" />}
              />

              {unitSystem === 'metric' ? (
                <InputGroup 
                  label="Height (cm)" 
                  value={displayHeightCm} 
                  onChange={(v: string) => setDisplayHeightCm(v)}
                  icon={<Activity className="w-5 h-5" />}
                />
              ) : (
                <div className="space-y-2">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Height (ft / in)</label>
                  <div className="flex gap-4">
                    <div className="relative flex-1">
                      <input 
                        type="number" 
                        value={heightFt} 
                        onChange={(e) => setHeightFt(e.target.value)}
                        className="w-full bg-slate-50 border border-transparent focus:border-indigo-600 focus:bg-white rounded-2xl py-4 px-4 font-bold text-gray-900 outline-none transition-all"
                        placeholder="ft"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-gray-300 uppercase">ft</span>
                    </div>
                    <div className="relative flex-1">
                      <input 
                        type="number" 
                        value={heightIn} 
                        onChange={(e) => setHeightIn(e.target.value)}
                        className="w-full bg-slate-50 border border-transparent focus:border-indigo-600 focus:bg-white rounded-2xl py-4 px-4 font-bold text-gray-900 outline-none transition-all"
                        placeholder="in"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-gray-300 uppercase">in</span>
                    </div>
                  </div>
                </div>
              )}

              <InputGroup 
                label="Age" 
                value={profile.age.toString()} 
                onChange={(v: string) => setProfile({ ...profile, age: parseInt(v) || 0 })}
                icon={<User className="w-5 h-5" />}
