import React, { useState, useEffect } from 'react';
import { 
  Target, 
  Scale, 
  User, 
  ChevronRight, 
  ArrowLeft, 
  CheckCircle2, 
  Activity,
  Dumbbell,
  Heart,
  Flame,
  LogIn,
  Sparkles,
  Award,
  TrendingUp,
  Mail
} from 'lucide-react';
import { UserProfile, GoalSheet } from '../types';
import { generateGoalPlan } from '../services/geminiService';

interface Props {
  onComplete: (profile: UserProfile) => void;
  onSkipAll: () => void;
}

const Onboarding: React.FC<Props> = ({ onComplete, onSkipAll }) => {
  const [step, setStep] = useState(0);
  const [isGenerating, setIsGenerating] = useState(false);
  const [goalPlan, setGoalPlan] = useState<GoalSheet | null>(null);
  const [showEmailForm, setShowEmailForm] = useState(false);
  const [email, setEmail] = useState('');

  // Local state for UI inputs to handle unit conversions easily
  const [unitSystem, setUnitSystem] = useState<'metric' | 'imperial'>('metric');
  const [displayWeight, setDisplayWeight] = useState('70');
  const [displayHeightCm, setDisplayHeightCm] = useState('175');
  const [heightFt, setHeightFt] = useState('5');
  const [heightIn, setHeightIn] = useState('9');

  const [profile, setProfile] = useState<UserProfile>({
    name: '',
    goal: 'maintain',
    weight: 70,
    height: 175,
    age: 25,
    activityLevel: 'moderate',
    isGuest: true,
    unitSystem: 'metric'
  });

  // Conversion helpers
  const lbsToKg = (lbs: number) => lbs * 0.453592;
  const kgToLbs = (kg: number) => kg / 0.453592;
  const ftInToCm = (ft: number, inc: number) => (ft * 30.48) + (inc * 2.54);
  const cmToFtIn = (cm: number) => {
    const totalInches = cm / 2.54;
    const ft = Math.floor(totalInches / 12);
    const inc = Math.round(totalInches % 12);
    return { ft, inc };
  };

  // Sync internal profile when unit system or display values change
  useEffect(() => {
    let finalWeight = profile.weight;
    let finalHeight = profile.height;

    if (unitSystem === 'metric') {
      finalWeight = parseFloat(displayWeight) || 0;
      finalHeight = parseFloat(displayHeightCm) || 0;
    } else {
      finalWeight = lbsToKg(parseFloat(displayWeight) || 0);
      finalHeight = ftInToCm(parseFloat(heightFt) || 0, parseFloat(heightIn) || 0);
    }

    setProfile(prev => ({
      ...prev,
      weight: finalWeight,
      height: finalHeight,
      unitSystem
    }));
  }, [displayWeight, displayHeightCm, heightFt, heightIn, unitSystem]);

  const handleUnitToggle = (newSystem: 'metric' | 'imperial') => {
    if (newSystem === unitSystem) return;

    if (newSystem === 'imperial') {
      // Metric to Imperial
      setDisplayWeight(Math.round(kgToLbs(parseFloat(displayWeight))).toString());
      const { ft, inc } = cmToFtIn(parseFloat(displayHeightCm));
      setHeightFt(ft.toString());
      setHeightIn(inc.toString());
    } else {
      // Imperial to Metric
      setDisplayWeight(Math.round(lbsToKg(parseFloat(displayWeight))).toString());
      const cm = ftInToCm(parseFloat(heightFt), parseFloat(heightIn));
      setDisplayHeightCm(Math.round(cm).toString());
    }
    setUnitSystem(newSystem);
  };

  const nextStep = () => setStep(s => s + 1);
  const prevStep = () => setStep(s => s - 1);

  const steps = [
    { title: "What's your name?", subtitle: "Personalized coaching starts here", canSkip: false },
    { title: "What's your goal?", subtitle: "We'll tailor the experience for you", canSkip: true },
    { title: "About you", subtitle: "Help us calculate your daily needs", canSkip: true },
    { title: "Activity level", subtitle: "How active are you on a weekly basis?", canSkip: true },
    { title: "Secure your account", subtitle: "Save progress across all your devices", canSkip: true }
  ];

  const handleFinish = async (provider: 'email' | 'google' | 'facebook' | 'apple' | 'guest') => {
    setIsGenerating(true);
    const finalProfile: UserProfile = {
      ...profile,
      name: profile.name || 'Friend',
      isGuest: provider === 'guest',
      authProvider: provider !== 'guest' ? provider : undefined,
      email: provider === 'email' ? email : undefined
    };

    const plan = await generateGoalPlan(finalProfile);
    setGoalPlan(plan);
    setIsGenerating(false);
    setStep(steps.length);
  };

  const finalizeOnboarding = () => {
    onComplete({ ...profile, goalSheet: goalPlan || undefined });
  };

  if (isGenerating) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-500">
        <div className="relative mb-8">
          <div className="w-24 h-24 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          <Sparkles className="w-10 h-10 text-indigo-600 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
        </div>
        <h2 className="text-2xl font-black text-gray-900 mb-2">Creating Your Roadmap</h2>
        <p className="text-gray-500 max-w-xs leading-relaxed">
          Our AI is calculating milestones based on your goals and biometrics...
        </p>
      </div>
    );
  }

  if (step === steps.length && goalPlan) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
        <div className="flex-1 overflow-y-auto pt-4 pb-8 no-scrollbar">
          <div className="flex flex-col items-center text-center mb-8">
            <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center text-white mb-4 shadow-xl shadow-indigo-200">
              <Award className="w-10 h-10" />
            </div>
            <h1 className="text-3xl font-black text-gray-900 mb-1">Your Blueprint</h1>
