              <div className="space-y-3">
                <AuthButton 
                  icon={<div className="w-6 h-6 flex items-center justify-center font-black text-white bg-black rounded-full">G</div>}
                  label="Sign up with Google"
                  onClick={() => handleFinish('google')}
                />
                <AuthButton 
                  icon={<div className="w-6 h-6 flex items-center justify-center font-black text-white bg-black rounded-full text-xs"></div>}
                  label="Sign up with Apple"
                  onClick={() => handleFinish('apple')}
                />
                <AuthButton 
                  icon={<div className="w-6 h-6 flex items-center justify-center font-black text-white bg-blue-600 rounded-full">f</div>}
                  label="Sign up with Facebook"
                  onClick={() => handleFinish('facebook')}
                />
                <AuthButton 
                  icon={<Mail className="w-5 h-5 text-gray-400" />}
                  label="Sign up with Email"
                  onClick={() => setShowEmailForm(true)}
                />

                <div className="flex items-center gap-4 py-4">
                  <div className="h-px flex-1 bg-gray-200" />
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Or</span>
                  <div className="h-px flex-1 bg-gray-200" />
                </div>

                <button 
                  onClick={() => handleFinish('guest')}
                  className="w-full py-5 bg-white text-gray-500 font-bold rounded-[32px] border border-gray-100 hover:bg-gray-50 transition-colors shadow-sm"
                >
                  Continue as Guest
                </button>
              </div>
            )}
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col p-6 animate-in fade-in duration-700">
      <div className="flex justify-between items-center mb-8 pt-4">
        <div className="flex gap-2 flex-1">
          {steps.map((_, i) => (
            <div 
              key={i} 
              className={`h-1.5 flex-1 rounded-full transition-all duration-500 ${i <= step ? 'bg-indigo-600' : 'bg-gray-200'}`} 
            />
          ))}
        </div>
        <button 
          onClick={onSkipAll}
          className="ml-4 text-xs font-black text-gray-400 hover:text-indigo-600 uppercase tracking-widest transition-colors"
        >
          Skip All
        </button>
      </div>

      <div className="flex-1">
        <h1 className="text-3xl font-black text-gray-900 mb-2">{steps[step].title}</h1>
        <p className="text-gray-500 mb-8 font-medium">{steps[step].subtitle}</p>

        {renderStep()}
      </div>

      <div className="flex gap-4 mt-8">
        {step > 0 && step < steps.length && (
          <button 
            onClick={prevStep}
            className="p-5 bg-white border border-gray-100 rounded-3xl text-gray-400 hover:text-gray-600 transition-all"
          >
            <ArrowLeft className="w-6 h-6" />
          </button>
        )}

        {step < steps.length - 1 && (
          <button 
            disabled={step === 0 && !profile.name.trim()}
            onClick={nextStep}
            className="flex-1 py-5 gradient-bg text-white font-bold rounded-[32px] shadow-xl shadow-indigo-100 flex items-center justify-center gap-2 active:scale-95 transition-all disabled:opacity-50"
          >
            Continue
            <ChevronRight className="w-5 h-5" />
          </button>
        )}
      </div>
    </div>
  );
};

