};

interface StatGoalProps {
  icon: React.ReactNode;
  label: string;
  value: number;
  goal: number;
  color: string;
  unit: string;
  description: string;
  onClick?: () => void;
}

const StatGoal: React.FC<StatGoalProps> = ({ icon, label, value, goal, color, unit, description, onClick }) => {
  const percent = goal > 0 ? Math.min(100, (value / goal) * 100) : 0;
  const isComplete = value >= goal;

  return (
    <button 
      onClick={onClick}
      className="w-full text-left group space-y-3 p-4 rounded-3xl hover:bg-slate-50 transition-all active:scale-[0.98]"
    >
      <div className="flex justify-between items-end">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${isComplete ? 'bg-indigo-600 text-white' : color + ' text-white'} shadow-sm transition-transform group-hover:scale-110`}>
            {isComplete ? <CheckCircle2 className="w-5 h-5" /> : icon}
          </div>
          <div>
            <h4 className="text-sm font-black text-gray-900">{label}</h4>
            <p className="text-[10px] font-medium text-gray-400">{description}</p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-xs font-black text-gray-900">
            {value.toLocaleString()} <span className="text-gray-400 font-bold">/ {goal.toLocaleString()} {unit}</span>
          </p>
          {isComplete ? (
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest">Goal Achieved</p>
          ) : (
            <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">
              {Math.max(0, goal - value).toLocaleString()} {unit} to go
            </p>
          )}
        </div>
      </div>
      <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
        <div 
          className={`h-full ${isComplete ? 'bg-indigo-600' : color} transition-all duration-1000 ease-out shadow-sm`} 
          style={{ width: `${percent}%` }}
        />
      </div>
    </button>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart2, 
  User, 
  Camera, 
  Plus, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer,
  Sparkles,
  Search,
  CheckCircle2,
  Clock,
  X,
  Zap,
  ChefHat,
  Bell,
  ArrowLeft
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import Recipes from './pages/Recipes';
import Onboarding from './pages/Onboarding';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry, UserProfile } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [isOnboarded, setIsOnboarded] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [stats, setStats] = useState<DailyStats>({
    calories: 0,
    caloriesGoal: 2000,
    water: 0,
    waterGoal: 8,
    steps: 0,
    stepsGoal: 10000,
    exercise: 0,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  const handleOnboardingComplete = (profile: UserProfile) => {
    let baseCals = 1800;
    if (profile.goal === 'loss') baseCals = 1600;
    if (profile.goal === 'gain') baseCals = 2400;
    if (profile.goal === 'maintain') baseCals = 2000;
    const activityMult = profile.activityLevel === 'active' ? 1.4 : profile.activityLevel === 'moderate' ? 1.2 : 1.0;
    const finalCals = Math.round(baseCals * activityMult);
    setUserProfile(profile);
    setStats(prev => ({ ...prev, caloriesGoal: finalCals }));
    setIsOnboarded(true);
  };

  const handleSkipAll = () => {
    const guestProfile: UserProfile = {
      name: 'Sophia',
      goal: 'maintain',
      weight: 70,
      height: 175,
      age: 25,
      activityLevel: 'moderate',
      isGuest: true,
      unitSystem: 'metric'
    };
    setUserProfile(guestProfile);
    setIsOnboarded(true);
  };

  const handleAuthChange = (authData: { provider: any, email?: string }) => {
    if (userProfile) {
      setUserProfile({ ...userProfile, isGuest: false, authProvider: authData.provider, email: authData.email });
    }
  };

  const handleAddWater = (amount: number = 1) => {
    setStats(prev => ({ ...prev, water: Math.min(prev.water + amount, prev.waterGoal * 2) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleAddSteps = (amount: number) => {
    setStats(prev => ({ ...prev, steps: prev.steps + amount }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) setPendingFood(result);
      else alert("Sorry, couldn't identify the food.");
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />;
      case 'journal':
        return <Journal stats={stats} foodLog={foodLog} exerciseLog={exerciseLog} onAddWater={() => handleAddWater(1)} onAddFood={handleAddFood} onAddExercise={handleAddExercise} />;
      case 'recipes':
        return <Recipes profile={userProfile} />;
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return <Profile profile={userProfile} onAuthConversion={handleAuthChange} />;
      default:
        return <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />;
    }
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={handleSkipAll} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen bg-brand-bg flex flex-col relative pb-28 overflow-hidden shadow-2xl">
      {/* Dynamic Header */}
      <header className="p-8 pb-2 flex justify-between items-center bg-transparent z-10">
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 rounded-full overflow-hidden border-4 border-white shadow-sm">
            <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Sophia" alt="Profile" className="w-full h-full object-cover bg-brand-coral" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-gray-900 tracking-tight">Hello, {userProfile?.name}</h1>
          </div>
        </div>
        <div className="relative">
          <button className="p-3 bg-white rounded-2xl shadow-sm border border-gray-100 active:scale-90 transition-all">
            <Bell className="w-6 h-6 text-gray-700" />
          </button>
          <div className="absolute top-1 right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></div>
        </div>
      </header>

      <main className="flex-1 px-8 overflow-y-auto no-scrollbar">
        {renderContent()}
      </main>

      {/* Floating Camera FAB */}
      <div className="fixed bottom-32 right-8 z-20">
        <label className="cursor-pointer">
          <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} disabled={isScanning} />
          <div className={`p-5 bg-white rounded-3xl shadow-xl text-gray-900 border border-gray-100 transition-all transform active:scale-95 hover:scale-105 ${isScanning ? 'opacity-50' : ''}`}>
            {isScanning ? <Clock className="w-7 h-7 animate-spin" /> : <Camera className="w-7 h-7" />}
          </div>
        </label>
      </div>

      {/* AI Overlays Preserved */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/60 backdrop-blur-md z-[100] flex flex-col items-center justify-center animate-in fade-in duration-300">
          <div className="relative">
            <div className="w-24 h-24 border-4 border-brand-coral/20 border-t-brand-coral rounded-full animate-spin"></div>
            <Sparkles className="w-10 h-10 text-brand-coral absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
          </div>
          <h3 className="mt-8 text-xl font-black text-gray-900">Scanning Meal...</h3>
        </div>
      )}

      {pendingFood && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[110] flex items-end justify-center animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-md rounded-t-[50px] p-10 pb-12 shadow-2xl relative animate-in slide-in-from-bottom-full duration-500">
            <div className="flex flex-col items-center text-center">
              <div className="w-24 h-24 bg-brand-peach rounded-[40px] flex items-center justify-center mb-6">
                <Utensils className="w-10 h-10 text-brand-coral" />
              </div>
              <h3 className="text-3xl font-black text-gray-900 mb-2">{pendingFood.name}</h3>
              <div className="bg-brand-blue rounded-3xl px-10 py-4 mb-10">
                <span className="text-4xl font-black text-gray-900">{pendingFood.calories}</span>
                <span className="ml-2 text-sm font-black text-gray-400 uppercase tracking-widest">kcal</span>
              </div>
              <div className="grid grid-cols-2 gap-4 w-full">
                <button onClick={() => setPendingFood(null)} className="py-5 rounded-[30px] border-2 border-slate-100 text-gray-400 font-black hover:bg-slate-50">Discard</button>
                <button onClick={() => { handleAddFood(pendingFood.name, pendingFood.calories); setPendingFood(null); }} className="py-5 rounded-[30px] bg-brand-coral text-white font-black shadow-lg">Add Log</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Bottom Navigation Overhaul */}
      <nav className="fixed bottom-6 left-6 right-6 max-w-md mx-auto bg-white/90 backdrop-blur-xl rounded-[40px] shadow-[0_20px_50px_rgba(0,0,0,0.1)] border border-white/50 px-6 py-4 flex justify-between items-center z-20">
        <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} onClick={() => setActiveTab('dashboard')} />
        <NavButton active={activeTab === 'journal'} icon={<Calendar />} onClick={() => setActiveTab('journal')} />
        <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} onClick={() => setActiveTab('recipes')} />
        <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} onClick={() => setActiveTab('progress')} />
        <NavButton active={activeTab === 'profile'} icon={<User />} onClick={() => setActiveTab('profile')} />
      </nav>
    </div>
  );
};

const NavButton = ({ active, icon, onClick }: any) => (
  <button onClick={onClick} className={`p-3 rounded-full transition-all active:scale-90 ${active ? 'bg-brand-coral text-white shadow-md' : 'text-gray-400 hover:text-gray-600'}`}>
    {React.cloneElement(icon as React.ReactElement, { className: 'w-7 h-7' })}
  </button>
);

export default App;

