                    <Timer className="w-5 h-5" />
                 </div>
               </div>
               <div className="flex flex-col gap-1 mb-6">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-[2px]">Exercises</p>
                 <span className="text-4xl font-black tracking-tight">120m</span>
               </div>
               <div className="h-1.5 w-full bg-white/10 rounded-full overflow-hidden">
                 <div className="h-full bg-brand-green w-1/3"></div>
               </div>
            </div>
            {exerciseLog.map(entry => (
              <LogItem key={entry.id} title={entry.title} val={`${entry.duration}m`} time={entry.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} bg="bg-brand-coral" icon={<Timer className="w-4 h-4" />} />
            ))}
          </div>
        )}

        {activeSubTab === 'water' && (
          <div className="bg-white rounded-[40px] p-10 flex flex-col items-center gap-8">
             <div className="w-48 h-48 rounded-full border-[10px] border-slate-50 flex flex-col items-center justify-center relative">
               <div className="absolute inset-0 rounded-full border-[10px] border-brand-blue border-t-transparent -rotate-45"></div>
               <Droplets className="w-10 h-10 text-brand-blue mb-2" />
               <span className="text-4xl font-black text-gray-900">{stats.water}</span>
               <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">cups</span>
             </div>
             <button onClick={onAddWater} className="w-full py-5 bg-brand-blue text-blue-800 font-black rounded-[30px] active:scale-95 transition-all">Add Water</button>
          </div>
        )}
      </div>
    </div>
  );
};

const SubTab = ({ active, label, onClick, color }: any) => (
  <button onClick={onClick} className={`flex-1 py-3 rounded-[24px] text-xs font-black uppercase tracking-widest transition-all ${active ? color + ' text-gray-900 shadow-sm' : 'text-gray-400'}`}>
