import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart2, 
  User, 
  Camera, 
  Plus, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer,
  Sparkles,
  Search,
  CheckCircle2,
  Clock,
  X,
  Zap,
  ChefHat
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import Recipes from './pages/Recipes';
import Onboarding from './pages/Onboarding';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry, UserProfile } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [isOnboarded, setIsOnboarded] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [stats, setStats] = useState<DailyStats>({
    calories: 0,
    caloriesGoal: 2000,
    water: 0,
    waterGoal: 8,
    steps: 0,
    stepsGoal: 10000,
    exercise: 0,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  const handleOnboardingComplete = (profile: UserProfile) => {
    let baseCals = 1800;
    if (profile.goal === 'loss') baseCals = 1600;
    if (profile.goal === 'gain') baseCals = 2400;
    if (profile.goal === 'maintain') baseCals = 2000;

    const activityMult = profile.activityLevel === 'active' ? 1.4 : profile.activityLevel === 'moderate' ? 1.2 : 1.0;
    const finalCals = Math.round(baseCals * activityMult);

    setUserProfile(profile);
    setStats(prev => ({
      ...prev,
      caloriesGoal: finalCals
    }));
    setIsOnboarded(true);
  };

  const handleSkipAll = () => {
    const guestProfile: UserProfile = {
      name: 'Friend',
      goal: 'maintain',
      weight: 70,
      height: 175,
      age: 25,
      activityLevel: 'moderate',
      isGuest: true,
      unitSystem: 'metric'
    };
    setUserProfile(guestProfile);
    setIsOnboarded(true);
  };

  const handleAuthChange = (authData: { provider: any, email?: string }) => {
    if (userProfile) {
      setUserProfile({
        ...userProfile,
        isGuest: false,
        authProvider: authData.provider,
        email: authData.email
      });
    }
  };

  const handleAddWater = (amount: number = 1) => {
    setStats(prev => ({ ...prev, water: Math.min(prev.water + amount, prev.waterGoal * 2) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleAddSteps = (amount: number) => {
    setStats(prev => ({ ...prev, steps: prev.steps + amount }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      } else {
        alert("Sorry, couldn't identify the food. Please try again.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const confirmPendingFood = () => {
    if (pendingFood) {
      handleAddFood(pendingFood.name, pendingFood.calories);
      setPendingFood(null);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            stats={stats} 
            profile={userProfile} 
            onAddFood={handleAddFood}
            onAddWater={handleAddWater}
            onAddSteps={handleAddSteps}
            onAddExercise={handleAddExercise}
          />
        );
      case 'journal':
        return (
          <Journal 
            stats={stats} 
            foodLog={foodLog} 
            exerciseLog={exerciseLog}
            onAddWater={() => handleAddWater(1)}
            onAddFood={handleAddFood}
            onAddExercise={handleAddExercise}
          />
        );
      case 'recipes':
        return <Recipes profile={userProfile} />;
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return <Profile profile={userProfile} onAuthConversion={handleAuthChange} />;
      default:
        return <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />;
    }
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={handleSkipAll} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen bg-slate-50 flex flex-col relative pb-20 overflow-hidden shadow-xl">
      {/* Header */}
      <header className="p-6 flex justify-between items-center bg-transparent z-10">
        <div>
          <h2 className="text-sm font-medium text-gray-500">Good morning,</h2>
          <h1 className="text-2xl font-bold text-gray-900">{userProfile?.name}</h1>
        </div>
        <div className="flex gap-2">
          <button className="p-2 bg-white rounded-xl shadow-sm border border-gray-100">
            <Search className="w-5 h-5 text-gray-600" />
          </button>
          <button className="p-2 bg-white rounded-xl shadow-sm border border-gray-100" onClick={() => setActiveTab('profile')}>
            <User className="w-5 h-5 text-gray-600" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 px-6">
        {renderContent()}
      </main>

      {/* Floating Action Button (Camera) */}
      <div className="fixed bottom-24 right-6 z-20">
        <label className="cursor-pointer">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            onChange={handleImageUpload}
            disabled={isScanning}
          />
          <div className={`p-4 gradient-bg rounded-2xl shadow-lg text-white transition-all transform active:scale-95 hover:scale-105 ${isScanning ? 'opacity-50' : ''}`}>
            {isScanning ? <Clock className="w-6 h-6 animate-spin" /> : <Camera className="w-6 h-6" />}
          </div>
        </label>
      </div>

      {/* AI Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/80 backdrop-blur-sm z-[100] flex flex-col items-center justify-center animate-in fade-in duration-300">
          <div className="relative">
            <div className="w-24 h-24 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <Sparkles className="w-10 h-10 text-indigo-600 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
          </div>
          <h3 className="mt-6 text-lg font-bold text-gray-900">AI Analysis in Progress</h3>
          <p className="text-sm text-gray-500 max-w-[200px] text-center mt-2">Identifying your meal and estimating nutritional facts...</p>
        </div>
      )}

      {/* AI Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[110] flex items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
          <div className="bg-white w-full rounded-[32px] p-8 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 gradient-bg"></div>
            <button 
              onClick={() => setPendingFood(null)}
              className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors"
            >
              <X className="w-5 h-5 text-gray-400" />
            </button>

            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-4 transform -rotate-3">
                <Utensils className="w-10 h-10 text-indigo-600" />
              </div>

              <div className="flex items-center gap-2 mb-1">
                <Zap className="w-4 h-4 text-amber-500 fill-amber-500" />
                <span className="text-[10px] font-bold text-amber-600 uppercase tracking-widest">AI Detection Successful</span>
              </div>

              <h3 className="text-2xl font-black text-gray-900 mb-2">{pendingFood.name}</h3>

              <div className="bg-indigo-50 rounded-2xl px-6 py-3 mb-8">
                <span className="text-3xl font-black text-indigo-600">{pendingFood.calories}</span>
                <span className="ml-1 text-sm font-bold text-indigo-400 uppercase">kcal</span>
              </div>

              <div className="grid grid-cols-2 gap-3 w-full">
                <button 
                  onClick={() => setPendingFood(null)}
                  className="py-4 rounded-2xl border border-gray-100 text-gray-500 font-bold hover:bg-gray-50 transition-colors"
                >
                  Discard
                </button>
                <button 
                  onClick={confirmPendingFood}
                  className="py-4 rounded-2xl gradient-bg text-white font-bold shadow-lg shadow-indigo-100 hover:opacity-90 transition-opacity flex items-center justify-center gap-2"
                >
                  <Plus className="w-5 h-5" /> Add to Log
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white border-t border-gray-100 px-4 py-3 flex justify-between items-center z-20">
        <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} label="Dash" onClick={() => setActiveTab('dashboard')} />
        <NavButton active={activeTab === 'journal'} icon={<Calendar />} label="Journal" onClick={() => setActiveTab('journal')} />
        <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} label="Kitchen" onClick={() => setActiveTab('recipes')} />
        <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Stats" onClick={() => setActiveTab('progress')} />
        <NavButton active={activeTab === 'profile'} icon={<User />} label="Me" onClick={() => setActiveTab('profile')} />
      </nav>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

const NavButton: React.FC<NavButtonProps> = ({ active, icon, label, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col items-center gap-1 transition-colors ${active ? 'text-indigo-600' : 'text-gray-400'}`}
  >
    <div className={`p-1 ${active ? 'bg-indigo-50 rounded-lg' : ''}`}>
      {React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}
    </div>
    <span className="text-[10px] font-medium uppercase tracking-wider">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Sparkles, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer, 
  Target, 
  RefreshCw, 
  ChevronDown, 
  ChevronUp, 
  CheckCircle2,
  TrendingUp,
  Flame,
  X,
  Plus,
  Minus
} from 'lucide-react';
import { DailyStats, UserProfile } from '../types';
import { suggestWorkout } from '../services/geminiService';

interface Props {
  stats: DailyStats;
  profile: UserProfile | null;
  onAddFood: (name: string, calories: number) => void;
  onAddWater: (amount: number) => void;
  onAddSteps: (amount: number) => void;
  onAddExercise: (title: string, duration: number) => void;
}

type GoalType = 'fuel' | 'hydrate' | 'steps' | 'burn' | null;

const Dashboard: React.FC<Props> = ({ stats, profile, onAddFood, onAddWater, onAddSteps, onAddExercise }) => {
  const [aiTip, setAiTip] = useState<string>("Loading personalized suggestion...");
  const [isExpanded, setIsExpanded] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Quick Log Modal State
  const [activeGoal, setActiveGoal] = useState<GoalType>(null);
  const [logValue1, setLogValue1] = useState('');
  const [logValue2, setLogValue2] = useState('');

  const fetchTip = async () => {
    setIsRefreshing(true);
    try {
      const remaining = stats.exerciseGoal - stats.exercise;
      if (remaining > 0) {
        const tip = await suggestWorkout(remaining, profile);
        setAiTip(tip || "Stay active today! Every step counts.");
      } else {
        setAiTip(`Amazing work, ${profile?.name || 'friend'}! You've hit your exercise goal for today. Focus on recovery and hydration now. Maybe a light stroll later if you feel like it!`);
      }
    } catch (error) {
      console.error("Error fetching AI tip:", error);
      setAiTip("Couldn't reach your AI coach. Try again in a moment!");
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchTip();
  }, [stats.exercise, profile]);

  const handleQuickLog = () => {
    switch (activeGoal) {
      case 'fuel':
        if (logValue1 && logValue2) onAddFood(logValue1, parseInt(logValue2));
        break;
      case 'hydrate':
        onAddWater(parseInt(logValue1) || 1);
        break;
      case 'steps':
        onAddSteps(parseInt(logValue1) || 0);
        break;
      case 'burn':
        if (logValue1 && logValue2) onAddExercise(logValue1, parseInt(logValue2));
        break;
    }
    closeModal();
  };

  const openModal = (type: GoalType) => {
    setActiveGoal(type);
    setLogValue1('');
    setLogValue2('');
    if (type === 'hydrate') setLogValue1('1');
    if (type === 'burn') setLogValue1('Walking');
  };

  const closeModal = () => {
    setActiveGoal(null);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* AI Suggestion Card */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-indigo-50 relative overflow-hidden transition-all duration-300">
        <div className="flex items-start gap-4 mb-3">
          <div className={`p-2 bg-indigo-50 rounded-xl text-indigo-600 ${isRefreshing ? 'animate-spin' : ''}`}>
            <Sparkles className="w-5 h-5" />
          </div>
          <div className="flex-1">
            <div className="flex justify-between items-center mb-1">
              <h3 className="text-sm font-black text-indigo-900 uppercase tracking-tighter">AI Health Coach</h3>
              <button 
                onClick={fetchTip}
                disabled={isRefreshing}
                className="p-1 text-indigo-400 hover:text-indigo-600 transition-colors disabled:opacity-50"
                title="Refresh suggestion"
              >
                <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
              </button>
            </div>

            <div className={`text-sm text-gray-600 leading-relaxed italic transition-all duration-300 ${!isExpanded ? 'line-clamp-3' : ''}`}>
              {aiTip.split('\n').map((line, i) => (
                <p key={i} className={line.startsWith('-') || line.startsWith('*') ? 'ml-2' : 'mb-1'}>
                  {line}
                </p>
              ))}
            </div>

            <div className="flex items-center gap-4 mt-3">
              <button 
                onClick={() => setIsExpanded(!isExpanded)}
                className="text-indigo-600 text-[10px] font-black uppercase tracking-widest flex items-center gap-1 hover:underline"
              >
                {isExpanded ? (
                  <>Show Less <ChevronUp className="w-3 h-3" /></>
                ) : (
                  <>Show More <ChevronDown className="w-3 h-3" /></>
                )}
              </button>
            </div>
          </div>
        </div>

        {isRefreshing && (
          <div className="absolute inset-0 bg-white/40 backdrop-blur-[1px] flex items-center justify-center">
             <div className="flex items-center gap-2 text-indigo-600 font-medium text-xs">
               <RefreshCw className="w-3 h-3 animate-spin" /> Tailoring for you...
             </div>
          </div>
        )}
      </div>

      {/* Daily Goals Hub */}
      <div className="bg-white rounded-[32px] p-8 shadow-sm border border-gray-100 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-[0.03]">
          <Target className="w-32 h-32" />
        </div>

        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
              <Target className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-xl font-black text-gray-900">Daily Goals</h2>
              <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Blueprint for success</p>
            </div>
          </div>
          <div className="text-right">
            <p className="text-2xl font-black text-indigo-600">
              {Object.entries(stats).filter(([k, v]) => !k.includes('Goal') && v >= (stats as any)[`${k}Goal`]).length}
              <span className="text-xs text-gray-400 font-bold">/4</span>
            </p>
            <p className="text-[10px] font-black text-gray-400 uppercase">Hits</p>
          </div>
        </div>

        <div className="space-y-4">
          <StatGoal 
            icon={<Flame className="w-4 h-4" />} 
            label="Fuel" 
            value={stats.calories} 
            goal={stats.caloriesGoal} 
            color="bg-orange-500" 
            unit="kcal" 
            description="Tap to add food"
            onClick={() => openModal('fuel')}
          />
          <StatGoal 
            icon={<Droplets className="w-4 h-4" />} 
            label="Hydrate" 
            value={stats.water} 
            goal={stats.waterGoal} 
            color="bg-blue-500" 
            unit="cups" 
            description="Tap to log water"
            onClick={() => openModal('hydrate')}
          />
          <StatGoal 
            icon={<Footprints className="w-4 h-4" />} 
            label="Steps" 
            value={stats.steps} 
            goal={stats.stepsGoal} 
            color="bg-emerald-500" 
            unit="steps" 
            description="Tap to add steps"
            onClick={() => openModal('steps')}
          />
          <StatGoal 
            icon={<Timer className="w-4 h-4" />} 
            label="Burn" 
            value={stats.exercise} 
            goal={stats.exerciseGoal} 
            color="bg-purple-500" 
            unit="min" 
            description="Tap to log activity"
            onClick={() => openModal('burn')}
          />
        </div>
      </div>

      {/* Quick Log Modal */}
      {activeGoal && (
        <div className="fixed inset-0 z-[100] flex items-end justify-center p-4">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={closeModal} />
          <div className="bg-white w-full max-w-sm rounded-[32px] p-8 shadow-2xl relative animate-in slide-in-from-bottom-full duration-300">
            <button onClick={closeModal} className="absolute top-6 right-6 p-2 bg-slate-50 rounded-full text-slate-400">
              <X className="w-4 h-4" />
            </button>

            <div className="flex items-center gap-3 mb-8">
              <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600">
                {activeGoal === 'fuel' && <Utensils className="w-6 h-6" />}
                {activeGoal === 'hydrate' && <Droplets className="w-6 h-6" />}
                {activeGoal === 'steps' && <Footprints className="w-6 h-6" />}
                {activeGoal === 'burn' && <Timer className="w-6 h-6" />}
              </div>
              <div>
                <h3 className="text-xl font-black text-gray-900 capitalize">Log {activeGoal}</h3>
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Manual Entry</p>
              </div>
            </div>

            <div className="space-y-4 mb-8">
              {(activeGoal === 'fuel' || activeGoal === 'burn') && (
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">{activeGoal === 'fuel' ? 'Food Name' : 'Activity Name'}</label>
                  <input 
                    autoFocus
                    type="text" 
                    value={logValue1} 
                    onChange={(e) => setLogValue1(e.target.value)}
                    placeholder={activeGoal === 'fuel' ? "e.g. Avocado Toast" : "e.g. Swimming"}
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-2xl py-4 px-6 font-bold text-gray-900 outline-none transition-all"
                  />
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">
                  {activeGoal === 'fuel' ? 'Calories (kcal)' : 
                   activeGoal === 'hydrate' ? 'Amount (cups)' : 
                   activeGoal === 'steps' ? 'Number of Steps' : 
                   'Duration (minutes)'}
                </label>
                <div className="relative">
                  <input 
                    type="number" 
                    autoFocus={activeGoal === 'hydrate' || activeGoal === 'steps'}
                    value={activeGoal === 'fuel' ? logValue2 : logValue1} 
                    onChange={(e) => activeGoal === 'fuel' ? setLogValue2(e.target.value) : setLogValue1(e.target.value)}
                    placeholder="0"
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white rounded-2xl py-4 px-6 font-bold text-gray-900 outline-none transition-all"
                  />
                  {activeGoal === 'hydrate' && (
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 flex gap-1">
                      <button onClick={() => setLogValue1(prev => (Math.max(1, parseInt(prev || '0') - 1)).toString())} className="p-2 bg-white rounded-xl shadow-sm border border-gray-100 text-gray-400"><Minus className="w-4 h-4" /></button>
                      <button onClick={() => setLogValue1(prev => (parseInt(prev || '0') + 1).toString())} className="p-2 bg-indigo-600 rounded-xl shadow-sm text-white"><Plus className="w-4 h-4" /></button>
                    </div>
                  )}
                </div>
              </div>
            </div>

            <button 
              onClick={handleQuickLog}
              disabled={!logValue1 && !logValue2}
              className="w-full py-5 gradient-bg text-white font-bold rounded-[24px] shadow-xl shadow-indigo-100 active:scale-95 transition-all disabled:opacity-50"
            >
              Save Record
            </button>
          </div>
        </div>
      )}

      {/* Secondary Insight Cards */}
      <div className="grid grid-cols-2 gap-4 pb-4">
        <div className="bg-white rounded-[28px] p-6 shadow-sm border border-gray-100 flex flex-col items-center text-center">
          <div className="w-12 h-12 bg-emerald-50 rounded-2xl flex items-center justify-center mb-4">
            <TrendingUp className="w-6 h-6 text-emerald-500" />
          </div>
          <p className="text-xl font-black text-gray-900">
            {stats.stepsGoal > 0 ? Math.round((stats.steps / stats.stepsGoal) * 100) : 0}%
          </p>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Step Target</p>
        </div>
        <div className="bg-white rounded-[28px] p-6 shadow-sm border border-gray-100 flex flex-col items-center text-center">
          <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center mb-4">
            <Sparkles className="w-6 h-6 text-indigo-600" />
          </div>
          <p className="text-xl font-black text-gray-900">12</p>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Day Streak</p>
        </div>
      </div>
    </div>
  );
};

interface StatGoalProps {
  icon: React.ReactNode;
  label: string;
  value: number;
  goal: number;
  color: string;
  unit: string;
  description: string;
  onClick?: () => void;
}

const StatGoal: React.FC<StatGoalProps> = ({ icon, label, value, goal, color, unit, description, onClick }) => {
  const percent = goal > 0 ? Math.min(100, (value / goal) * 100) : 0;
  const isComplete = value >= goal;

  return (
    <button 
      onClick={onClick}
      className="w-full text-left group space-y-3 p-4 rounded-3xl hover:bg-slate-50 transition-all active:scale-[0.98]"
    >
      <div className="flex justify-between items-end">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${isComplete ? 'bg-indigo-600 text-white' : color + ' text-white'} shadow-sm transition-transform group-hover:scale-110`}>
            {isComplete ? <CheckCircle2 className="w-5 h-5" /> : icon}
          </div>
          <div>
            <h4 className="text-sm font-black text-gray-900">{label}</h4>
            <p className="text-[10px] font-medium text-gray-400">{description}</p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-xs font-black text-gray-900">
            {value.toLocaleString()} <span className="text-gray-400 font-bold">/ {goal.toLocaleString()} {unit}</span>
          </p>
          {isComplete ? (
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest">Goal Achieved</p>
          ) : (
            <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">
              {Math.max(0, goal - value).toLocaleString()} {unit} to go
            </p>
          )}
        </div>
      </div>
      <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
        <div 
          className={`h-full ${isComplete ? 'bg-indigo-600' : color} transition-all duration-1000 ease-out shadow-sm`} 
          style={{ width: `${percent}%` }}
        />
      </div>
    </button>
  );
};

export default Dashboard;

