            </div>

            <div className={`text-sm text-gray-600 leading-relaxed italic transition-all duration-300 ${!isExpanded ? 'line-clamp-3' : ''}`}>
              {aiTip.split('\n').map((line, i) => (
                <p key={i} className={line.startsWith('-') || line.startsWith('*') ? 'ml-2' : 'mb-1'}>
                  {line}
                </p>
              ))}
            </div>

            <div className="flex items-center gap-4 mt-3">
              <button 
                onClick={() => setIsExpanded(!isExpanded)}
                className="theme-text text-[10px] font-black uppercase tracking-widest flex items-center gap-1 hover:underline"
              >
                {isExpanded ? (
                  <>Show Less <ChevronUp className="w-3 h-3" /></>
                ) : (
                  <>Show More <ChevronDown className="w-3 h-3" /></>
                )}
              </button>
            </div>
          </div>
        </div>

        {isRefreshing && (
          <div className="absolute inset-0 bg-white/40 backdrop-blur-[1px] flex items-center justify-center">
             <div className="flex items-center gap-2 theme-text font-medium text-xs">
               <RefreshCw className="w-3 h-3 animate-spin" /> Tailoring for you...
             </div>
          </div>
        )}
      </div>

      {/* Daily Goals Hub */}
      <div className="bg-white rounded-[32px] p-8 shadow-sm border border-gray-100 relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-[0.03]">
          <Target className="w-32 h-32" />
        </div>

        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 theme-bg rounded-2xl flex items-center justify-center text-white shadow-lg theme-glow">
              <Target className="w-5 h-5" />
            </div>
            <div>
