                    className="w-full bg-slate-50 border-2 border-transparent focus:theme-border focus:bg-white rounded-2xl py-4 px-6 font-bold text-gray-900 outline-none transition-all"
                  />
                  {activeGoal === 'hydrate' && (
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 flex gap-1">
                      <button onClick={() => setLogValue1(prev => (Math.max(1, parseInt(prev || '0') - 1)).toString())} className="p-2 bg-white rounded-xl shadow-sm border border-gray-100 text-gray-400"><Minus className="w-4 h-4" /></button>
                      <button onClick={() => setLogValue1(prev => (parseInt(prev || '0') + 1).toString())} className="p-2 theme-bg rounded-xl shadow-sm text-white"><Plus className="w-4 h-4" /></button>
                    </div>
                  )}
                </div>
              </div>
            </div>

            <button 
              onClick={handleQuickLog}
              disabled={!logValue1 && !logValue2}
              className="w-full py-5 gradient-bg text-white font-bold rounded-[24px] shadow-xl theme-glow active:scale-95 transition-all disabled:opacity-50"
            >
              Save Record
            </button>
          </div>
        </div>
      )}

      {/* Secondary Insight Cards */}
      <div className="grid grid-cols-2 gap-4 pb-4">
        <div className="bg-white rounded-[28px] p-6 shadow-sm border border-gray-100 flex flex-col items-center text-center">
          <div className="w-12 h-12 bg-emerald-50 rounded-2xl flex items-center justify-center mb-4">
            <TrendingUp className="w-6 h-6 text-emerald-500" />
          </div>
          <p className="text-xl font-black text-gray-900">
            {stats.stepsGoal > 0 ? Math.round((stats.steps / stats.stepsGoal) * 100) : 0}%
          </p>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Step Target</p>
        </div>
        <div className="bg-white rounded-[28px] p-6 shadow-sm border border-gray-100 flex flex-col items-center text-center">
          <div className="w-12 h-12 theme-light-bg rounded-2xl flex items-center justify-center mb-4">
            <Sparkles className="w-6 h-6 theme-text" />
          </div>
          <p className="text-xl font-black text-gray-900">12</p>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Day Streak</p>
        </div>
      </div>
    </div>
  );
};

interface StatGoalProps {
  icon: React.ReactNode;
  label: string;
  value: number;
  goal: number;
  color: string;
  unit: string;
  description: string;
  onClick?: () => void;
}

const StatGoal: React.FC<StatGoalProps> = ({ icon, label, value, goal, color, unit, description, onClick }) => {
  const percent = goal > 0 ? Math.min(100, (value / goal) * 100) : 0;
  const isComplete = value >= goal;

  return (
    <button 
      onClick={onClick}
      className="w-full text-left group space-y-3 p-4 rounded-3xl hover:bg-slate-50 transition-all active:scale-[0.98]"
    >
      <div className="flex justify-between items-end">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${isComplete ? 'theme-bg text-white' : color + ' text-white'} shadow-sm transition-transform group-hover:scale-110`}>
            {isComplete ? <CheckCircle2 className="w-5 h-5" /> : icon}
          </div>
          <div>
            <h4 className="text-sm font-black text-gray-900">{label}</h4>
            <p className="text-[10px] font-medium text-gray-400">{description}</p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-xs font-black text-gray-900">
            {value.toLocaleString()} <span className="text-gray-400 font-bold">/ {goal.toLocaleString()} {unit}</span>
          </p>
          {isComplete ? (
            <p className="text-[9px] font-black theme-text uppercase tracking-widest">Goal Achieved</p>
          ) : (
            <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">
              {Math.max(0, goal - value).toLocaleString()} {unit} to go
            </p>
          )}
        </div>
      </div>
      <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden">
        <div 
          className={`h-full ${isComplete ? 'theme-bg' : color} transition-all duration-1000 ease-out shadow-sm`} 
          style={{ width: `${percent}%` }}
        />
      </div>
    </button>
  );
};

