);

export default Profile;

import React, { useState, useEffect } from 'react';
import { 
  Target, 
  Scale, 
  User, 
  ChevronRight, 
  ArrowLeft, 
  CheckCircle2, 
  Activity,
  Dumbbell,
  Heart,
  Flame,
  LogIn,
  Sparkles,
  Award,
  TrendingUp,
  Mail,
  Zap
} from 'lucide-react';
import { UserProfile, GoalSheet } from '../types';
import { generateGoalPlan } from '../services/geminiService';

interface Props {
  onComplete: (profile: UserProfile) => void;
  onSkipAll: () => void;
}

const Onboarding: React.FC<Props> = ({ onComplete, onSkipAll }) => {
  const [step, setStep] = useState(-1); // Start at -1 for the Landing Page
  const [isGenerating, setIsGenerating] = useState(false);
  const [goalPlan, setGoalPlan] = useState<GoalSheet | null>(null);
  const [showEmailForm, setShowEmailForm] = useState(false);
  const [email, setEmail] = useState('');

  // Local state for UI inputs to handle unit conversions easily
  const [unitSystem, setUnitSystem] = useState<'metric' | 'imperial'>('metric');
  const [displayWeight, setDisplayWeight] = useState('70');
  const [displayHeightCm, setDisplayHeightCm] = useState('175');
  const [heightFt, setHeightFt] = useState('5');
  const [heightIn, setHeightIn] = useState('9');

  const [profile, setProfile] = useState<UserProfile>({
    name: '',
    goal: 'maintain',
    weight: 70,
    height: 175,
    age: 25,
    activityLevel: 'moderate',
    isGuest: true,
    unitSystem: 'metric'
  });

  // Conversion helpers
  const lbsToKg = (lbs: number) => lbs * 0.453592;
  const kgToLbs = (kg: number) => kg / 0.453592;
  const ftInToCm = (ft: number, inc: number) => (ft * 30.48) + (inc * 2.54);
  const cmToFtIn = (cm: number) => {
    const totalInches = cm / 2.54;
    const ft = Math.floor(totalInches / 12);
    const inc = Math.round(totalInches % 12);
    return { ft, inc };
  };

  // Sync internal profile when unit system or display values change
  useEffect(() => {
    let finalWeight = profile.weight;
    let finalHeight = profile.height;

    if (unitSystem === 'metric') {
      finalWeight = parseFloat(displayWeight) || 0;
      finalHeight = parseFloat(displayHeightCm) || 0;
    } else {
      finalWeight = lbsToKg(parseFloat(displayWeight) || 0);
      finalHeight = ftInToCm(parseFloat(heightFt) || 0, parseFloat(heightIn) || 0);
    }

    setProfile(prev => ({
      ...prev,
      weight: finalWeight,
      height: finalHeight,
      unitSystem
    }));
  }, [displayWeight, displayHeightCm, heightFt, heightIn, unitSystem]);

  const handleUnitToggle = (newSystem: 'metric' | 'imperial') => {
    if (newSystem === unitSystem) return;

    if (newSystem === 'imperial') {
      // Metric to Imperial
      setDisplayWeight(Math.round(kgToLbs(parseFloat(displayWeight))).toString());
      const { ft, inc } = cmToFtIn(parseFloat(displayHeightCm));
      setHeightFt(ft.toString());
      setHeightIn(inc.toString());
    } else {
      // Imperial to Metric
      setDisplayWeight(Math.round(lbsToKg(parseFloat(displayWeight))).toString());
      const cm = ftInToCm(parseFloat(heightFt), parseFloat(heightIn));
      setDisplayHeightCm(Math.round(cm).toString());
    }
    setUnitSystem(newSystem);
  };

  const nextStep = () => setStep(s => s + 1);
  const prevStep = () => setStep(s => s - 1);

  const steps = [
    { title: "What's your name?", subtitle: "Personalized coaching starts here", canSkip: false },
    { title: "What's your goal?", subtitle: "We'll tailor the experience for you", canSkip: true },
    { title: "About you", subtitle: "Help us calculate your daily needs", canSkip: true },
    { title: "Activity level", subtitle: "How active are you on a weekly basis?", canSkip: true },
    { title: "Secure your account", subtitle: "Save progress across all your devices", canSkip: true }
  ];

  const handleFinish = async (provider: 'email' | 'google' | 'facebook' | 'apple' | 'guest') => {
    setIsGenerating(true);
    const finalProfile: UserProfile = {
      ...profile,
      name: profile.name || 'Friend',
      isGuest: provider === 'guest',
      authProvider: provider !== 'guest' ? provider : undefined,
      email: provider === 'email' ? email : undefined
    };

    const plan = await generateGoalPlan(finalProfile);
    setGoalPlan(plan);
    setIsGenerating(false);
    setStep(steps.length);
  };

  const finalizeOnboarding = () => {
    onComplete({ ...profile, goalSheet: goalPlan || undefined });
  };

  // Landing Page Render
  if (step === -1) {
    return (
      <div className="min-h-screen gradient-bg flex flex-col p-8 relative overflow-hidden animate-in fade-in duration-700">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-20 -mt-20 blur-3xl"></div>
        <div className="absolute bottom-0 left-0 w-80 h-80 bg-white/5 rounded-full -ml-40 -mb-40 blur-3xl"></div>

        <div className="flex-1 flex flex-col items-center justify-center text-center relative z-10">
          <div className="w-24 h-24 bg-white/20 backdrop-blur-md rounded-[40px] flex items-center justify-center mb-8 shadow-2xl theme-glow animate-bounce duration-3000">
            <Sparkles className="w-12 h-12 text-white" />
          </div>

          <h1 className="text-5xl font-black text-white tracking-tighter mb-4">
            FitAI<br/>Companion
          </h1>

          <div className="bg-white/10 backdrop-blur-sm px-4 py-2 rounded-full inline-flex items-center gap-2 mb-8 border border-white/20">
            <Zap className="w-4 h-4 text-amber-300 fill-amber-300" />
            <span className="text-[10px] font-black text-white uppercase tracking-widest">Powered by Gemini AI</span>
          </div>

          <p className="text-white/80 text-lg font-medium max-w-xs leading-relaxed">
            Your journey to a healthier, stronger you starts with smart guidance.
          </p>
        </div>

        <div className="relative z-10 space-y-4">
          <button 
            onClick={nextStep}
            className="w-full py-5 bg-white theme-text font-black text-lg rounded-[32px] shadow-2xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 group"
          >
            Get Started
            <ChevronRight className="w-6 h-6 group-hover:translate-x-1 transition-transform" />
          </button>

          <button 
            onClick={onSkipAll}
            className="w-full py-4 text-white/60 font-bold text-sm uppercase tracking-widest hover:text-white transition-colors"
          >
            I'll explore first
          </button>
        </div>
      </div>
    );
  }

  if (isGenerating) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-500">
        <div className="relative mb-8">
          <div className="w-24 h-24 border-4 theme-light-bg theme-border rounded-full animate-spin border-t-transparent"></div>
          <Sparkles className="w-10 h-10 theme-text absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
        </div>
        <h2 className="text-2xl font-black text-gray-900 mb-2">Creating Your Roadmap</h2>
        <p className="text-gray-500 max-w-xs leading-relaxed">
          Our AI is calculating milestones based on your goals and biometrics...
        </p>
      </div>
    );
  }

  if (step === steps.length && goalPlan) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col p-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
        <div className="flex-1 overflow-y-auto pt-4 pb-8 no-scrollbar">
          <div className="flex flex-col items-center text-center mb-8">
            <div className="w-20 h-20 theme-bg rounded-3xl flex items-center justify-center text-white mb-4 shadow-xl theme-glow">
              <Award className="w-10 h-10" />
            </div>
            <h1 className="text-3xl font-black text-gray-900 mb-1">Your Blueprint</h1>
            <p className="theme-text font-bold text-sm uppercase tracking-widest">{goalPlan.title}</p>
          </div>

          <div className="bg-white rounded-[32px] p-8 shadow-sm border border-gray-100 mb-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-slate-50 rounded-full -mr-16 -mt-16" />
            <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">The Focus</h3>
            <p className="text-gray-700 font-medium leading-relaxed">{goalPlan.summary}</p>
          </div>

          <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 ml-2">Milestones</h3>
          <div className="space-y-4 mb-8">
            {goalPlan.milestones.map((m, idx) => (
              <div key={m.id} className="bg-white p-5 rounded-3xl flex gap-4 shadow-sm border border-gray-50">
                <div className="w-10 h-10 bg-slate-50 rounded-2xl flex items-center justify-center theme-text font-black text-xs shrink-0">
                  0{idx + 1}
                </div>
                <div>
                  <h4 className="font-bold text-gray-900">{m.title}</h4>
                  <p className="text-xs text-gray-500 mt-1">{m.description}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="theme-bg rounded-3xl p-6 text-white shadow-xl theme-glow">
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp className="w-4 h-4 opacity-70" />
              <span className="text-[10px] font-black uppercase tracking-widest opacity-70">Expert Tip</span>
            </div>
            <p className="text-sm font-medium leading-relaxed italic">"{goalPlan.dailyAdvice}"</p>
          </div>
        </div>

        <button 
          onClick={finalizeOnboarding}
          className="w-full py-5 gradient-bg text-white font-bold rounded-[32px] shadow-2xl theme-glow flex items-center justify-center gap-2 active:scale-95 transition-all mt-4"
        >
          Start My Journey
          <ChevronRight className="w-5 h-5" />
        </button>
      </div>
    );
  }

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
             <div className="bg-white p-8 rounded-[32px] shadow-sm border border-gray-100">
                <div className="space-y-4">
                  <div className="flex justify-between items-end mb-1">
                    <label className="text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Your Name</label>
                  </div>
                  <input 
                    type="text" 
                    autoFocus
                    value={profile.name} 
                    placeholder="Enter your name"
                    onChange={(e) => setProfile({ ...profile, name: e.target.value })}
                    className="w-full bg-slate-50 border-2 border-transparent focus:theme-border focus:bg-white rounded-2xl py-4 px-6 font-bold text-gray-900 outline-none transition-all"
                  />
                </div>
             </div>
             <div className="text-center">
                <button 
                  onClick={() => setStep(4)}
                  className="text-xs font-bold theme-text hover:opacity-70 transition-colors"
                >
                  Already have an account? Sign In
                </button>
             </div>
          </div>
        );
      case 1:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-500">
            <GoalCard 
              selected={profile.goal === 'loss'} 
              onClick={() => setProfile({ ...profile, goal: 'loss' })}
              icon={<Flame className="w-6 h-6" />}
              title="Weight Loss"
              description="Burn fat and get leaner"
              color="text-orange-500"
              bg="bg-orange-50"
            />
            <GoalCard 
              selected={profile.goal === 'gain'} 
              onClick={() => setProfile({ ...profile, goal: 'gain' })}
              icon={<Dumbbell className="w-6 h-6" />}
              title="Muscle Gain"
              description="Build strength and mass"
              color="text-indigo-500"
              bg="bg-indigo-50"
            />
            <GoalCard 
              selected={profile.goal === 'maintain'} 
              onClick={() => setProfile({ ...profile, goal: 'maintain' })}
              icon={<Target className="w-6 h-6" />}
              title="Maintain Weight"
              description="Stay fit and healthy"
              color="text-emerald-500"
              bg="bg-emerald-50"
            />
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white p-6 rounded-[32px] shadow-sm border border-gray-100 space-y-6">
              {/* Unit Toggle */}
              <div className="flex bg-slate-50 p-1 rounded-2xl border border-gray-100">
                <button 
                  onClick={() => handleUnitToggle('metric')}
                  className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${unitSystem === 'metric' ? 'bg-white theme-text shadow-sm' : 'text-gray-400'}`}
                >
                  Metric
                </button>
                <button 
                  onClick={() => handleUnitToggle('imperial')}
                  className={`flex-1 py-2 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${unitSystem === 'imperial' ? 'bg-white theme-text shadow-sm' : 'text-gray-400'}`}
                >
                  Imperial
                </button>
              </div>

              <InputGroup 
                label={`Weight (${unitSystem === 'metric' ? 'kg' : 'lbs'})`} 
                value={displayWeight} 
                onChange={(v: string) => setDisplayWeight(v)}
                icon={<Scale className="w-5 h-5" />}
              />

              {unitSystem === 'metric' ? (
                <InputGroup 
                  label="Height (cm)" 
                  value={displayHeightCm} 
                  onChange={(v: string) => setDisplayHeightCm(v)}
                  icon={<Activity className="w-5 h-5" />}
                />
              ) : (
                <div className="space-y-2">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest ml-1">Height (ft / in)</label>
                  <div className="flex gap-4">
                    <div className="relative flex-1">
                      <input 
                        type="number" 
                        value={heightFt} 
                        onChange={(e) => setHeightFt(e.target.value)}
                        className="w-full bg-slate-50 border border-transparent focus:theme-border focus:bg-white rounded-2xl py-4 px-4 font-bold text-gray-900 outline-none transition-all"
                        placeholder="ft"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-gray-300 uppercase">ft</span>
                    </div>
                    <div className="relative flex-1">
                      <input 
                        type="number" 
                        value={heightIn} 
                        onChange={(e) => setHeightIn(e.target.value)}
                        className="w-full bg-slate-50 border border-transparent focus:theme-border focus:bg-white rounded-2xl py-4 px-4 font-bold text-gray-900 outline-none transition-all"
                        placeholder="in"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-gray-300 uppercase">in</span>
                    </div>
                  </div>
                </div>
              )}

              <InputGroup 
                label="Age" 
                value={profile.age.toString()} 
                onChange={(v: string) => setProfile({ ...profile, age: parseInt(v) || 0 })}
                icon={<User className="w-5 h-5" />}
              />
            </div>
          </div>
        );
      case 3:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-500">
            <ActivityOption 
              selected={profile.activityLevel === 'sedentary'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'sedentary' })}
              title="Sedentary"
              description="Little to no exercise"
            />
            <ActivityOption 
              selected={profile.activityLevel === 'moderate'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'moderate' })}
              title="Moderate"
              description="Exercise 3-4 times a week"
            />
            <ActivityOption 
              selected={profile.activityLevel === 'active'} 
              onClick={() => setProfile({ ...profile, activityLevel: 'active' })}
              title="Highly Active"
              description="Daily intense exercise"
            />
          </div>
        );
      case 4:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-4 duration-500">
            {showEmailForm ? (
              <div className="bg-white p-8 rounded-[32px] shadow-sm border border-gray-100 space-y-4">
                <button onClick={() => setShowEmailForm(false)} className="text-xs font-bold text-gray-400 flex items-center gap-1 mb-2 hover:theme-text">
                  <ArrowLeft className="w-3 h-3" /> Back to options
                </button>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Email Address</label>
                  <input 
                    type="email" 
                    placeholder="name@example.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full bg-slate-50 border-2 border-transparent focus:theme-border focus:bg-white rounded-2xl py-4 px-6 font-bold text-gray-900 outline-none transition-all"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Password</label>
                  <input 
                    type="password" 
                    placeholder="••••••••"
                    className="w-full bg-slate-50 border-2 border-transparent focus:theme-border focus:bg-white rounded-2xl py-4 px-6 font-bold text-gray-900 outline-none transition-all"
                  />
                </div>
                <button 
                  onClick={() => handleFinish('email')}
                  disabled={!email.includes('@')}
                  className="w-full py-4 gradient-bg text-white font-bold rounded-2xl shadow-lg theme-glow active:scale-95 transition-all disabled:opacity-50"
                >
                  Confirm Sign Up
                </button>
              </div>
            ) : (
              <div className="space-y-3">
                <AuthButton 
                  icon={<div className="w-6 h-6 flex items-center justify-center font-black text-white bg-black rounded-full">G</div>}
                  label="Sign up with Google"
                  onClick={() => handleFinish('google')}
                />
                <AuthButton 
                  icon={<div className="w-6 h-6 flex items-center justify-center font-black text-white bg-black rounded-full text-xs"></div>}
                  label="Sign up with Apple"
                  onClick={() => handleFinish('apple')}
                />
                <AuthButton 
                  icon={<div className="w-6 h-6 flex items-center justify-center font-black text-white bg-blue-600 rounded-full">f</div>}
                  label="Sign up with Facebook"
                  onClick={() => handleFinish('facebook')}
                />
                <AuthButton 
                  icon={<Mail className="w-5 h-5 text-gray-400" />}
                  label="Sign up with Email"
                  onClick={() => setShowEmailForm(true)}
                />

                <div className="flex items-center gap-4 py-4">
                  <div className="h-px flex-1 bg-gray-200" />
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Or</span>
                  <div className="h-px flex-1 bg-gray-200" />
                </div>

                <button 
                  onClick={() => handleFinish('guest')}
                  className="w-full py-5 bg-white text-gray-500 font-bold rounded-[32px] border border-gray-100 hover:bg-gray-50 transition-colors shadow-sm"
                >
                  Continue as Guest
                </button>
              </div>
            )}
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col p-6 animate-in fade-in duration-700">
      <div className="flex justify-between items-center mb-8 pt-4">
        <div className="flex gap-2 flex-1">
          {steps.map((_, i) => (
            <div 
              key={i} 
              className={`h-1.5 flex-1 rounded-full transition-all duration-500 ${i <= step ? 'theme-bg' : 'bg-gray-200'}`} 
            />
          ))}
        </div>
        <button 
          onClick={onSkipAll}
          className="ml-4 text-xs font-black text-gray-400 hover:theme-text uppercase tracking-widest transition-colors"
        >
          Skip All
        </button>
      </div>

      <div className="flex-1">
        <h1 className="text-3xl font-black text-gray-900 mb-2">{steps[step].title}</h1>
        <p className="text-gray-500 mb-8 font-medium">{steps[step].subtitle}</p>

        {renderStep()}
      </div>

      <div className="flex gap-4 mt-8">
        {step > 0 && step < steps.length && (
          <button 
            onClick={prevStep}
            className="p-5 bg-white border border-gray-100 rounded-3xl text-gray-400 hover:text-gray-600 transition-all"
          >
            <ArrowLeft className="w-6 h-6" />
          </button>
        )}

        {step < steps.length - 1 && (
          <button 
            disabled={step === 0 && !profile.name.trim()}
            onClick={nextStep}
            className="flex-1 py-5 gradient-bg text-white font-bold rounded-[32px] shadow-xl theme-glow flex items-center justify-center gap-2 active:scale-95 transition-all disabled:opacity-50"
          >
            Continue
            <ChevronRight className="w-5 h-5" />
          </button>
        )}
      </div>
    </div>
  );
};

const AuthButton = ({ icon, label, onClick }: any) => (
  <button 
    onClick={onClick}
    className="w-full p-4 bg-white rounded-2xl flex items-center gap-4 border border-gray-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98]"
