    <div className="relative">
      <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
        {icon}
      </div>
      <input 
        type="number" 
        value={value} 
        onChange={(e) => onChange(e.target.value)}
        className="w-full bg-slate-50 border border-transparent focus:theme-border focus:bg-white rounded-2xl py-4 pl-12 pr-4 font-bold text-gray-900 outline-none transition-all"
