import Recipes from './pages/Recipes';
import Onboarding from './pages/Onboarding';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry, UserProfile, AppTheme } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [isOnboarded, setIsOnboarded] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [theme, setTheme] = useState<AppTheme>('indigo');
  const [stats, setStats] = useState<DailyStats>({
    calories: 0,
    caloriesGoal: 2000,
    water: 0,
    waterGoal: 8,
    steps: 0,
    stepsGoal: 10000,
    exercise: 0,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  const handleOnboardingComplete = (profile: UserProfile) => {
    let baseCals = 1800;
    if (profile.goal === 'loss') baseCals = 1600;
    if (profile.goal === 'gain') baseCals = 2400;
    if (profile.goal === 'maintain') baseCals = 2000;

    const activityMult = profile.activityLevel === 'active' ? 1.4 : profile.activityLevel === 'moderate' ? 1.2 : 1.0;
    const finalCals = Math.round(baseCals * activityMult);

    setUserProfile(profile);
    setStats(prev => ({
      ...prev,
      caloriesGoal: finalCals
    }));
    setIsOnboarded(true);
  };

  const handleSkipAll = () => {
    const guestProfile: UserProfile = {
      name: 'Friend',
      goal: 'maintain',
      weight: 70,
      height: 175,
      age: 25,
      activityLevel: 'moderate',
      isGuest: true,
      unitSystem: 'metric'
    };
    setUserProfile(guestProfile);
    setIsOnboarded(true);
  };

  const handleAuthChange = (authData: { provider: any, email?: string }) => {
    if (userProfile) {
      setUserProfile({
        ...userProfile,
        isGuest: false,
        authProvider: authData.provider,
        email: authData.email
      });
    }
  };

  const handleAddWater = (amount: number = 1) => {
    setStats(prev => ({ ...prev, water: Math.min(prev.water + amount, prev.waterGoal * 2) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleAddSteps = (amount: number) => {
    setStats(prev => ({ ...prev, steps: prev.steps + amount }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      } else {
        alert("Sorry, couldn't identify the food. Please try again.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const confirmPendingFood = () => {
    if (pendingFood) {
      handleAddFood(pendingFood.name, pendingFood.calories);
      setPendingFood(null);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            stats={stats} 
            profile={userProfile} 
            onAddFood={handleAddFood}
            onAddWater={handleAddWater}
            onAddSteps={handleAddSteps}
            onAddExercise={handleAddExercise}
          />
        );
      case 'journal':
        return (
          <Journal 
            stats={stats} 
            foodLog={foodLog} 
            exerciseLog={exerciseLog}
            onAddWater={() => handleAddWater(1)}
            onAddFood={handleAddFood}
            onAddExercise={handleAddExercise}
          />
        );
      case 'recipes':
        return <Recipes profile={userProfile} />;
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return <Profile profile={userProfile} onAuthConversion={handleAuthChange} currentTheme={theme} onThemeChange={setTheme} />;
      default:
        return <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />;
    }
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={handleSkipAll} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#f0f2f5] flex flex-col relative pb-20 overflow-hidden shadow-2xl" data-theme={theme}>
      {/* Background Blobs */}
      <div className="blob blob-1"></div>
      <div className="blob blob-2"></div>
      <div className="blob blob-3"></div>

      {/* Header */}
      <header className="p-6 flex justify-between items-center bg-transparent z-10">
        <div>
          <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">Welcome back,</h2>
          <h1 className="text-3xl font-black text-gray-900 tracking-tight">{userProfile?.name}</h1>
        </div>
        <div className="flex gap-2">
          <button className="p-3 liquid-glass rounded-2xl transition-all active:scale-95">
            <Search className="w-5 h-5 text-gray-600" />
          </button>
          <button className="p-3 liquid-glass rounded-2xl transition-all active:scale-95" onClick={() => setActiveTab('profile')}>
            <User className="w-5 h-5 text-gray-600" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 px-6 z-10">
        {renderContent()}
      </main>

      {/* Floating Action Button (Camera) */}
      <div className="fixed bottom-24 right-6 z-20">
        <label className="cursor-pointer">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            onChange={handleImageUpload}
            disabled={isScanning}
          />
          <div className={`p-5 theme-glow gradient-bg rounded-3xl shadow-lg text-white transition-all transform active:scale-90 hover:scale-105 ${isScanning ? 'opacity-50' : ''}`}>
            {isScanning ? <Clock className="w-7 h-7 animate-spin" /> : <Camera className="w-7 h-7" />}
          </div>
        </label>
      </div>

      {/* AI Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/40 backdrop-blur-xl z-[100] flex flex-col items-center justify-center animate-in fade-in duration-300">
          <div className="relative">
            <div className="w-32 h-32 border-4 theme-light-bg theme-border rounded-full animate-spin border-t-transparent"></div>
            <Sparkles className="w-12 h-12 theme-text absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
          </div>
          <h3 className="mt-8 text-2xl font-black text-gray-900">AI Intelligence</h3>
          <p className="text-sm text-gray-500 max-w-[220px] text-center mt-3 font-medium">Scanning molecules, calculating nutrients...</p>
        </div>
      )}

      {/* AI Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-[110] flex items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
          <div className="liquid-glass w-full rounded-[40px] p-8 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 gradient-bg"></div>
            <button 
              onClick={() => setPendingFood(null)}
              className="absolute top-6 right-6 p-2 hover:bg-black/5 rounded-full transition-colors"
            >
              <X className="w-5 h-5 text-gray-400" />
            </button>

            <div className="flex flex-col items-center text-center">
              <div className="w-24 h-24 theme-light-bg rounded-[32px] flex items-center justify-center mb-6 transform rotate-6 theme-border border-2">
                <Utensils className="w-12 h-12 theme-text" />
              </div>

              <div className="bg-amber-100/50 px-3 py-1 rounded-full flex items-center gap-1.5 mb-2">
                <Zap className="w-3 h-3 text-amber-600 fill-amber-600" />
                <span className="text-[10px] font-black text-amber-700 uppercase tracking-widest">AI Accurate Analysis</span>
              </div>

              <h3 className="text-3xl font-black text-gray-900 mb-2">{pendingFood.name}</h3>

              <div className="bg-white/50 border border-white/50 rounded-3xl px-8 py-5 mb-10 shadow-inner">
                <span className="text-4xl font-black theme-text tracking-tighter">{pendingFood.calories}</span>
                <span className="ml-2 text-sm font-black theme-text opacity-60 uppercase">kcal</span>
              </div>

              <div className="grid grid-cols-2 gap-4 w-full">
                <button 
                  onClick={() => setPendingFood(null)}
                  className="py-5 rounded-2xl glass-btn text-gray-500 font-black text-sm uppercase tracking-wider"
                >
                  Discard
                </button>
                <button 
                  onClick={confirmPendingFood}
                  className="py-5 rounded-2xl gradient-bg text-white font-black text-sm uppercase tracking-wider shadow-xl theme-glow"
                >
                  Add Record
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Bar (Glass Dock) */}
      <div className="fixed bottom-6 left-6 right-6 max-w-sm mx-auto z-20">
        <nav className="liquid-glass rounded-[28px] px-2 py-2 flex justify-between items-center">
          <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} label="Dash" onClick={() => setActiveTab('dashboard')} />
          <NavButton active={activeTab === 'journal'} icon={<Calendar />} label="Diary" onClick={() => setActiveTab('journal')} />
          <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} label="Chef" onClick={() => setActiveTab('recipes')} />
          <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Stats" onClick={() => setActiveTab('progress')} />
          <NavButton active={activeTab === 'profile'} icon={<User />} label="Me" onClick={() => setActiveTab('profile')} />
        </nav>
      </div>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

const NavButton: React.FC<NavButtonProps> = ({ active, icon, label, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col items-center gap-1 py-2 transition-all rounded-2xl ${active ? 'bg-white/50 theme-text' : 'text-gray-400 hover:text-gray-600'}`}
  >
    {React.cloneElement(icon as React.ReactElement, { className: `w-5 h-5 ${active ? 'scale-110' : ''} transition-transform` })}
    <span className="text-[9px] font-black uppercase tracking-widest">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Target, 
  Scale, 
  User, 
  ChevronRight, 
  ArrowLeft, 
  CheckCircle2, 
  Activity,
  Dumbbell,
  Heart,
  Flame,
  LogIn,
  Sparkles,
  Award,
  TrendingUp,
  Mail,
  Zap,
  X
} from 'lucide-react';
import { UserProfile, GoalSheet } from '../types';
import { generateGoalPlan } from '../services/geminiService';

interface Props {
  onComplete: (profile: UserProfile) => void;
  onSkipAll: () => void;
}

const Onboarding: React.FC<Props> = ({ onComplete, onSkipAll }) => {
  const [step, setStep] = useState(-1);
  const [isGenerating, setIsGenerating] = useState(false);
  const [goalPlan, setGoalPlan] = useState<GoalSheet | null>(null);
  const [showEmailForm, setShowEmailForm] = useState(false);
  const [email, setEmail] = useState('');

  const [unitSystem, setUnitSystem] = useState<'metric' | 'imperial'>('metric');
  const [displayWeight, setDisplayWeight] = useState('70');
  const [displayHeightCm, setDisplayHeightCm] = useState('175');
  const [heightFt, setHeightFt] = useState('5');
  const [heightIn, setHeightIn] = useState('9');

  const [profile, setProfile] = useState<UserProfile>({
    name: '',
    goal: 'maintain',
    weight: 70,
    height: 175,
    age: 25,
    activityLevel: 'moderate',
    isGuest: true,
    unitSystem: 'metric'
  });

  const lbsToKg = (lbs: number) => lbs * 0.453592;
  const kgToLbs = (kg: number) => kg / 0.453592;
  const ftInToCm = (ft: number, inc: number) => (ft * 30.48) + (inc * 2.54);
  const cmToFtIn = (cm: number) => {
    const totalInches = cm / 2.54;
    const ft = Math.floor(totalInches / 12);
    const inc = Math.round(totalInches % 12);
    return { ft, inc };
  };

  useEffect(() => {
    let finalWeight = profile.weight;
    let finalHeight = profile.height;

    if (unitSystem === 'metric') {
      finalWeight = parseFloat(displayWeight) || 0;
      finalHeight = parseFloat(displayHeightCm) || 0;
    } else {
      finalWeight = lbsToKg(parseFloat(displayWeight) || 0);
      finalHeight = ftInToCm(parseFloat(heightFt) || 0, parseFloat(heightIn) || 0);
    }

    setProfile(prev => ({
      ...prev,
      weight: finalWeight,
      height: finalHeight,
      unitSystem
    }));
  }, [displayWeight, displayHeightCm, heightFt, heightIn, unitSystem]);

  const handleUnitToggle = (newSystem: 'metric' | 'imperial') => {
    if (newSystem === unitSystem) return;

    if (newSystem === 'imperial') {
      setDisplayWeight(Math.round(kgToLbs(parseFloat(displayWeight))).toString());
      const { ft, inc } = cmToFtIn(parseFloat(displayHeightCm));
      setHeightFt(ft.toString());
      setHeightIn(inc.toString());
    } else {
      setDisplayWeight(Math.round(lbsToKg(parseFloat(displayWeight))).toString());
      const cm = ftInToCm(parseFloat(heightFt), parseFloat(heightIn));
      setDisplayHeightCm(Math.round(cm).toString());
    }
    setUnitSystem(newSystem);
  };

  const nextStep = () => setStep(s => s + 1);
  const prevStep = () => setStep(s => s - 1);

  const steps = [
    { title: "The Basics", subtitle: "Tell us your name to begin", canSkip: false },
    { title: "Define Goals", subtitle: "AI works best with clear targets", canSkip: true },
    { title: "Biometrics", subtitle: "Calculating your metabolic footprint", canSkip: true },
    { title: "Lifestyle", subtitle: "Daily activity impacts your results", canSkip: true },
    { title: "Sync Data", subtitle: "Keep your records safe in the cloud", canSkip: true }
  ];

  const handleFinish = async (provider: 'email' | 'google' | 'facebook' | 'apple' | 'guest') => {
    setIsGenerating(true);
    const finalProfile: UserProfile = {
      ...profile,
      name: profile.name || 'Friend',
      isGuest: provider === 'guest',
      authProvider: provider !== 'guest' ? provider : undefined,
      email: provider === 'email' ? email : undefined
    };

    const plan = await generateGoalPlan(finalProfile);
    setGoalPlan(plan);
    setIsGenerating(false);
    setStep(steps.length);
  };

  const finalizeOnboarding = () => {
    onComplete({ ...profile, goalSheet: goalPlan || undefined });
  };

  if (step === -1) {
    return (
      <div className="min-h-screen bg-[#f0f2f5] flex flex-col p-8 relative overflow-hidden animate-in fade-in duration-1000">
        <div className="blob blob-1 !opacity-40"></div>
        <div className="blob blob-2 !opacity-40"></div>

        <div className="flex-1 flex flex-col items-center justify-center text-center relative z-10">
          <div className="w-28 h-28 liquid-glass rounded-[48px] flex items-center justify-center mb-10 shadow-2xl animate-pulse">
            <Sparkles className="w-14 h-14 theme-text" />
          </div>

          <h1 className="text-6xl font-black text-gray-900 tracking-tighter mb-4 leading-none">
            FitAI<br/><span className="theme-text">Companion</span>
          </h1>

          <div className="bg-white/40 backdrop-blur-md px-5 py-2.5 rounded-full inline-flex items-center gap-2.5 mb-10 border border-white/50 shadow-sm">
            <Zap className="w-4 h-4 text-amber-500 fill-amber-500" />
            <span className="text-[11px] font-black text-gray-700 uppercase tracking-widest">Next-Gen Intelligence</span>
          </div>

          <p className="text-gray-500 text-lg font-medium max-w-[260px] leading-relaxed">
            Personalized health coaching powered by advanced generative AI.
          </p>
        </div>

        <div className="relative z-10 space-y-4 pb-10">
          <button 
            onClick={nextStep}
            className="w-full py-6 gradient-bg text-white font-black text-xl rounded-[32px] shadow-2xl theme-glow hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 group"
          >
            Enter Journey
            <ChevronRight className="w-7 h-7 group-hover:translate-x-1 transition-transform" />
          </button>

          <button 
            onClick={onSkipAll}
            className="w-full py-4 liquid-glass rounded-2xl text-gray-500 font-black text-xs uppercase tracking-[0.2em] hover:bg-white/80 transition-all"
          >
            Quick Guest View
          </button>
        </div>
      </div>
    );
  }

  if (isGenerating) {
    return (
      <div className="min-h-screen bg-[#f0f2f5] flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-500">
         <div className="blob blob-1 !opacity-20"></div>
        <div className="relative mb-10">
          <div className="w-32 h-32 border-4 theme-light-bg theme-border rounded-full animate-spin border-t-transparent"></div>
          <Sparkles className="w-12 h-12 theme-text absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
        </div>
        <h2 className="text-3xl font-black text-gray-900 mb-3 tracking-tight">AI Strategy Engine</h2>
        <p className="text-gray-500 max-w-[240px] leading-relaxed font-medium">
          Synthesizing your data into a sustainable health blueprint...
        </p>
      </div>
    );
  }

  if (step === steps.length && goalPlan) {
    return (
      <div className="min-h-screen bg-[#f0f2f5] flex flex-col p-6 animate-in fade-in slide-in-from-bottom-8 duration-700 relative overflow-hidden">
        <div className="blob blob-2 !opacity-20"></div>
        <div className="flex-1 overflow-y-auto pt-6 pb-12 no-scrollbar relative z-10">
          <div className="flex flex-col items-center text-center mb-10">
            <div className="w-24 h-24 theme-bg rounded-[32px] flex items-center justify-center text-white mb-6 shadow-2xl theme-glow">
              <Award className="w-12 h-12" />
            </div>
            <h1 className="text-4xl font-black text-gray-900 mb-2 tracking-tight">Your Strategy</h1>
            <div className="px-4 py-1.5 liquid-glass rounded-full inline-block">
              <p className="theme-text font-black text-xs uppercase tracking-widest">{goalPlan.title}</p>
            </div>
          </div>

          <div className="liquid-glass rounded-[40px] p-10 mb-8 relative overflow-hidden">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4">Executive Summary</h3>
            <p className="text-gray-700 font-bold text-lg leading-snug">{goalPlan.summary}</p>
          </div>

          <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-5 ml-4">Strategic Milestones</h3>
          <div className="space-y-4 mb-10">
            {goalPlan.milestones.map((m, idx) => (
              <div key={m.id} className="liquid-glass p-6 rounded-[28px] flex gap-5 shadow-sm">
                <div className="w-12 h-12 theme-light-bg rounded-2xl flex items-center justify-center theme-text font-black text-lg shrink-0 border border-white/40">
                  {idx + 1}
                </div>
                <div>
                  <h4 className="font-black text-gray-900 text-base">{m.title}</h4>
                  <p className="text-xs text-gray-500 mt-1 leading-relaxed font-medium">{m.description}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="gradient-bg rounded-[32px] p-8 text-white shadow-2xl theme-glow">
            <div className="flex items-center gap-3 mb-3">
              <TrendingUp className="w-5 h-5 opacity-70" />
              <span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-70">Daily Optimization</span>
            </div>
            <p className="text-lg font-bold leading-relaxed italic opacity-90">"{goalPlan.dailyAdvice}"</p>
          </div>
        </div>

        <button 
          onClick={finalizeOnboarding}
          className="w-full py-6 gradient-bg text-white font-black text-xl rounded-[32px] shadow-2xl theme-glow flex items-center justify-center gap-3 active:scale-95 transition-all mt-6 relative z-10"
        >
          Begin Protocol
          <ChevronRight className="w-6 h-6" />
        </button>
      </div>
    );
  }

  const renderStep = () => {
    switch (step) {
      case 0:
        return (
          <div className="space-y-8 animate-in slide-in-from-bottom-6 duration-500">
             <div className="liquid-glass p-10 rounded-[40px] shadow-sm">
                <div className="space-y-5">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] ml-2">Identifying Token</label>
                  <input 
                    type="text" 
                    autoFocus
                    value={profile.name} 
                    placeholder="Enter your name..."
                    onChange={(e) => setProfile({ ...profile, name: e.target.value })}
                    className="w-full bg-white/40 border-2 border-transparent focus:theme-border focus:bg-white rounded-[24px] py-5 px-8 font-black text-2xl text-gray-900 outline-none transition-all placeholder:text-gray-300 shadow-inner"
                  />
                </div>
             </div>
             <div className="text-center">
                <button onClick={() => setStep(4)} className="text-[11px] font-black theme-text uppercase tracking-widest hover:opacity-70 transition-all">
                  Access Existing Account
                </button>
             </div>
          </div>
        );
      case 1:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-6 duration-500">
            <GoalCard 
              selected={profile.goal === 'loss'} 
              onClick={() => setProfile({ ...profile, goal: 'loss' })}
              icon={<Flame className="w-8 h-8" />}
              title="Weight Reduction"
              description="Caloric deficit & metabolic push"
              color="text-orange-500"
              bg="bg-orange-100/30"
            />
            <GoalCard 
              selected={profile.goal === 'gain'} 
              onClick={() => setProfile({ ...profile, goal: 'gain' })}
              icon={<Dumbbell className="w-8 h-8" />}
              title="Hypertrophy"
              description="Muscle building & strength"
              color="text-indigo-500"
              bg="bg-indigo-100/30"
            />
            <GoalCard 
              selected={profile.goal === 'maintain'} 
              onClick={() => setProfile({ ...profile, goal: 'maintain' })}
              icon={<Target className="w-8 h-8" />}
              title="Optimization"
              description="Peak performance maintenance"
              color="text-emerald-500"
              bg="bg-emerald-100/30"
            />
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in slide-in-from-bottom-6 duration-500">
            <div className="liquid-glass p-8 rounded-[40px] space-y-8">
              <div className="flex bg-black/5 p-1.5 rounded-[20px] border border-white/50">
                <button onClick={() => handleUnitToggle('metric')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-[0.2em] rounded-[14px] transition-all ${unitSystem === 'metric' ? 'bg-white theme-text shadow-sm' : 'text-gray-400'}`}>Metric</button>
                <button onClick={() => handleUnitToggle('imperial')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-[0.2em] rounded-[14px] transition-all ${unitSystem === 'imperial' ? 'bg-white theme-text shadow-sm' : 'text-gray-400'}`}>Imperial</button>
              </div>

              <InputGroup label={`Weight (${unitSystem === 'metric' ? 'kg' : 'lbs'})`} value={displayWeight} onChange={setDisplayWeight} icon={<Scale className="w-6 h-6" />} />

              {unitSystem === 'metric' ? (
                <InputGroup label="Height (cm)" value={displayHeightCm} onChange={setDisplayHeightCm} icon={<Activity className="w-6 h-6" />} />
              ) : (
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Stature (ft/in)</label>
                  <div className="flex gap-4">
                    <div className="relative flex-1">
                      <input type="number" value={heightFt} onChange={(e) => setHeightFt(e.target.value)} className="w-full bg-white/40 border border-transparent focus:theme-border focus:bg-white rounded-[20px] py-4 px-6 font-black text-xl text-gray-900 outline-none transition-all shadow-inner" placeholder="ft" />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[9px] font-black text-gray-300 uppercase">ft</span>
                    </div>
                    <div className="relative flex-1">
                      <input type="number" value={heightIn} onChange={(e) => setHeightIn(e.target.value)} className="w-full bg-white/40 border border-transparent focus:theme-border focus:bg-white rounded-[20px] py-4 px-6 font-black text-xl text-gray-900 outline-none transition-all shadow-inner" placeholder="in" />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[9px] font-black text-gray-300 uppercase">in</span>
                    </div>
                  </div>
                </div>
              )}

              <InputGroup label="Chronological Age" value={profile.age.toString()} onChange={(v: string) => setProfile({ ...profile, age: parseInt(v) || 0 })} icon={<User className="w-6 h-6" />} />
            </div>
          </div>
        );
      case 3:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-6 duration-500">
            <ActivityOption selected={profile.activityLevel === 'sedentary'} onClick={() => setProfile({ ...profile, activityLevel: 'sedentary' })} title="Minimal Activity" description="Limited metabolic expenditure" />
            <ActivityOption selected={profile.activityLevel === 'moderate'} onClick={() => setProfile({ ...profile, activityLevel: 'moderate' })} title="Standard Active" description="Regular movement intervals" />
            <ActivityOption selected={profile.activityLevel === 'active'} onClick={() => setProfile({ ...profile, activityLevel: 'active' })} title="High Performance" description="Intensive daily conditioning" />
          </div>
        );
      case 4:
        return (
          <div className="space-y-4 animate-in slide-in-from-bottom-6 duration-500">
            {showEmailForm ? (
              <div className="liquid-glass p-10 rounded-[40px] space-y-6">
                <button onClick={() => setShowEmailForm(false)} className="text-[10px] font-black text-gray-400 flex items-center gap-2 mb-2 hover:theme-text uppercase tracking-widest">
                  <ArrowLeft className="w-4 h-4" /> Account Options
                </button>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Email Identity</label>
                  <input type="email" placeholder="name@domain.com" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full bg-white/40 border border-transparent focus:theme-border focus:bg-white rounded-[20px] py-4 px-6 font-black text-gray-900 outline-none transition-all shadow-inner" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Access Key</label>
                  <input type="password" placeholder="••••••••" className="w-full bg-white/40 border border-transparent focus:theme-border focus:bg-white rounded-[20px] py-4 px-6 font-black text-gray-900 outline-none transition-all shadow-inner" />
                </div>
                <button onClick={() => handleFinish('email')} disabled={!email.includes('@')} className="w-full py-5 gradient-bg text-white font-black rounded-2xl shadow-xl theme-glow active:scale-95 transition-all disabled:opacity-50 mt-4 uppercase tracking-[0.2em] text-sm">Create Profile</button>
              </div>
            ) : (
              <div className="space-y-4">
                <AuthButton icon={<div className="w-7 h-7 flex items-center justify-center font-black text-white bg-black rounded-xl">G</div>} label="Sync with Google" onClick={() => handleFinish('google')} />
                <AuthButton icon={<div className="w-7 h-7 flex items-center justify-center font-black text-white bg-black rounded-xl text-sm"></div>} label="Sync with Apple" onClick={() => handleFinish('apple')} />
                <AuthButton icon={<Mail className="w-6 h-6 theme-text" />} label="Sync via Email" onClick={() => setShowEmailForm(true)} />
                <div className="flex items-center gap-6 py-4">
                  <div className="h-px flex-1 bg-gray-200" />
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Protocol</span>
                  <div className="h-px flex-1 bg-gray-200" />
                </div>
                <button 
                  onClick={() => handleFinish('guest')}
                  className="w-full py-6 liquid-glass text-gray-500 font-black rounded-[32px] hover:bg-white/80 transition-all uppercase tracking-[0.2em] text-xs"
                >
                  Continue Unlinked
                </button>
              </div>
            )}
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-[#f0f2f5] flex flex-col p-6 animate-in fade-in duration-700 relative overflow-hidden">
      <div className="blob blob-3 !opacity-30"></div>

      <div className="flex justify-between items-center mb-10 pt-4 relative z-10">
        <div className="flex gap-2 flex-1 max-w-[200px]">
          {steps.map((_, i) => (
            <div 
              key={i} 
              className={`h-1.5 flex-1 rounded-full transition-all duration-700 ${i <= step ? 'theme-bg shadow-sm' : 'bg-gray-200'}`} 
            />
          ))}
        </div>
        <button 
          onClick={onSkipAll}
          className="text-[10px] font-black text-gray-400 hover:theme-text uppercase tracking-[0.2em] transition-colors"
        >
          Bypass
        </button>
      </div>

      <div className="flex-1 relative z-10">
        <h1 className="text-4xl font-black text-gray-900 mb-2 tracking-tight">{steps[step].title}</h1>
        <p className="text-gray-500 mb-10 font-medium">{steps[step].subtitle}</p>

        {renderStep()}
      </div>

      <div className="flex gap-4 mt-10 relative z-10">
        {step > 0 && step < steps.length && (
          <button 
            onClick={prevStep}
            className="p-6 liquid-glass rounded-3xl text-gray-400 hover:text-gray-600 transition-all active:scale-90"
          >
            <ArrowLeft className="w-6 h-6" />
          </button>
        )}

        {step < steps.length - 1 && (
          <button 
            disabled={step === 0 && !profile.name.trim()}
            onClick={nextStep}
            className="flex-1 py-6 gradient-bg text-white font-black text-lg rounded-[32px] shadow-2xl theme-glow flex items-center justify-center gap-3 active:scale-95 transition-all disabled:opacity-50"
          >
            Continue
            <ChevronRight className="w-6 h-6" />
          </button>
        )}
      </div>
    </div>
  );
};

