import React, { useState, useEffect } from 'react';
import { 
  Sparkles, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer, 
  Target, 
  RefreshCw, 
  ChevronDown, 
  ChevronUp, 
  CheckCircle2,
  TrendingUp,
  Flame,
  X,
  Plus,
  Minus
} from 'lucide-react';
import { DailyStats, UserProfile } from '../types';
import { suggestWorkout } from '../services/geminiService';

interface Props {
  stats: DailyStats;
  profile: UserProfile | null;
  onAddFood: (name: string, calories: number) => void;
  onAddWater: (amount: number) => void;
  onAddSteps: (amount: number) => void;
  onAddExercise: (title: string, duration: number) => void;
}

type GoalType = 'fuel' | 'hydrate' | 'steps' | 'burn' | null;

const Dashboard: React.FC<Props> = ({ stats, profile, onAddFood, onAddWater, onAddSteps, onAddExercise }) => {
  const [aiTip, setAiTip] = useState<string>("Loading personalized suggestion...");
  const [isExpanded, setIsExpanded] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const [activeGoal, setActiveGoal] = useState<GoalType>(null);
  const [logValue1, setLogValue1] = useState('');
  const [logValue2, setLogValue2] = useState('');

  const fetchTip = async () => {
    setIsRefreshing(true);
    try {
      const remaining = stats.exerciseGoal - stats.exercise;
      if (remaining > 0) {
        const tip = await suggestWorkout(remaining, profile);
        setAiTip(tip || "Stay active today! Every step counts.");
      } else {
        setAiTip(`Amazing work, ${profile?.name || 'friend'}! You've hit your exercise goal for today. Focus on recovery and hydration now.`);
      }
    } catch (error) {
      setAiTip("Couldn't reach your AI coach. Try again in a moment!");
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchTip();
  }, [stats.exercise, profile]);

  const handleQuickLog = () => {
    switch (activeGoal) {
      case 'fuel':
        if (logValue1 && logValue2) onAddFood(logValue1, parseInt(logValue2));
        break;
      case 'hydrate':
        onAddWater(parseInt(logValue1) || 1);
        break;
      case 'steps':
        onAddSteps(parseInt(logValue1) || 0);
        break;
      case 'burn':
        if (logValue1 && logValue2) onAddExercise(logValue1, parseInt(logValue2));
        break;
    }
    closeModal();
  };

  const openModal = (type: GoalType) => {
    setActiveGoal(type);
    setLogValue1('');
    setLogValue2('');
    if (type === 'hydrate') setLogValue1('1');
    if (type === 'burn') setLogValue1('Walking');
  };

  const closeModal = () => setActiveGoal(null);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* AI Suggestion Card - Liquid Glass */}
      <div className="liquid-glass rounded-[32px] p-6 relative overflow-hidden transition-all duration-300">
        <div className="flex items-start gap-4 mb-3">
          <div className={`p-2.5 theme-light-bg rounded-2xl theme-text border border-white/40 ${isRefreshing ? 'animate-spin' : ''}`}>
            <Sparkles className="w-5 h-5" />
          </div>
          <div className="flex-1">
            <div className="flex justify-between items-center mb-1">
              <h3 className="text-xs font-black theme-text uppercase tracking-[0.2em]">AI Intelligence</h3>
              <button 
                onClick={fetchTip}
                disabled={isRefreshing}
                className="p-1 theme-text opacity-40 hover:opacity-100 transition-colors"
              >
                <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
              </button>
            </div>

            <div className={`text-sm text-gray-700 leading-relaxed italic transition-all duration-300 ${!isExpanded ? 'line-clamp-3' : ''}`}>
              {aiTip.split('\n').map((line, i) => (
                <p key={i} className={line.startsWith('-') || line.startsWith('*') ? 'ml-2' : 'mb-1'}>
                  {line}
                </p>
              ))}
            </div>

            <button 
              onClick={() => setIsExpanded(!isExpanded)}
              className="mt-3 theme-text text-[9px] font-black uppercase tracking-[0.2em] flex items-center gap-1 hover:opacity-70"
            >
              {isExpanded ? <>Collapse <ChevronUp className="w-3 h-3" /></> : <>Expand <ChevronDown className="w-3 h-3" /></>}
            </button>
          </div>
        </div>
      </div>

      {/* Daily Goals Hub - Liquid Glass */}
      <div className="liquid-glass rounded-[40px] p-8 relative overflow-hidden">
        <div className="absolute -top-10 -right-10 opacity-5">
          <Target className="w-48 h-48" />
        </div>

        <div className="flex items-center justify-between mb-10">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 theme-bg rounded-2xl flex items-center justify-center text-white shadow-xl theme-glow border border-white/20">
              <Target className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-2xl font-black text-gray-900 tracking-tight">Daily Protocol</h2>
              <p className="text-[10px] font-black theme-text opacity-70 uppercase tracking-[0.3em]">Neural Objectives</p>
            </div>
          </div>
          <div className="text-right">
            <p className="text-3xl font-black theme-text tracking-tighter">
              {Object.entries(stats).filter(([k, v]) => !k.includes('Goal') && v >= (stats as any)[`${k}Goal`]).length}
              <span className="text-xs text-gray-400 font-bold ml-1">/ 4</span>
            </p>
          </div>
        </div>

        <div className="space-y-3">
          <StatGoal icon={<Flame className="w-4 h-4" />} label="Calories" value={stats.calories} goal={stats.caloriesGoal} color="theme-bg" unit="kcal" onClick={() => openModal('fuel')} />
          <StatGoal icon={<Droplets className="w-4 h-4" />} label="Hydration" value={stats.water} goal={stats.waterGoal} color="bg-blue-500" unit="cups" onClick={() => openModal('hydrate')} />
          <StatGoal icon={<Footprints className="w-4 h-4" />} label="Stamina" value={stats.steps} goal={stats.stepsGoal} color="bg-emerald-500" unit="steps" onClick={() => openModal('steps')} />
          <StatGoal icon={<Timer className="w-4 h-4" />} label="Movement" value={stats.exercise} goal={stats.exerciseGoal} color="bg-amber-500" unit="min" onClick={() => openModal('burn')} />
        </div>
      </div>

      {/* Manual Entry Modal - Glass */}
      {activeGoal && (
        <div className="fixed inset-0 z-[100] flex items-end justify-center p-6 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-black/20 backdrop-blur-md" onClick={closeModal} />
          <div className="liquid-glass w-full max-w-sm rounded-[40px] p-10 shadow-2xl relative animate-in slide-in-from-bottom-10">
            <button onClick={closeModal} className="absolute top-8 right-8 p-2 bg-black/5 rounded-full text-gray-400 hover:text-gray-600 transition-colors">
              <X className="w-5 h-5" />
            </button>

            <div className="flex items-center gap-4 mb-10">
              <div className="w-14 h-14 theme-light-bg rounded-2xl flex items-center justify-center theme-text border border-white/40">
                {activeGoal === 'fuel' && <Utensils className="w-7 h-7" />}
                {activeGoal === 'hydrate' && <Droplets className="w-7 h-7" />}
                {activeGoal === 'steps' && <Footprints className="w-7 h-7" />}
                {activeGoal === 'burn' && <Timer className="w-7 h-7" />}
              </div>
              <div>
                <h3 className="text-2xl font-black text-gray-900 tracking-tight capitalize">Log {activeGoal}</h3>
                <p className="text-[10px] font-black theme-text uppercase tracking-[0.3em]">Manual Telemetry</p>
              </div>
            </div>

            <div className="space-y-6 mb-10">
              {(activeGoal === 'fuel' || activeGoal === 'burn') && (
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Description</label>
                  <input type="text" value={logValue1} onChange={(e) => setLogValue1(e.target.value)} placeholder="Activity name..." className="w-full bg-white/50 border-2 border-transparent focus:theme-border rounded-2xl py-5 px-6 font-black text-gray-900 outline-none transition-all shadow-inner" />
                </div>
              )}
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Value</label>
                <div className="relative">
                  <input type="number" value={activeGoal === 'fuel' ? logValue2 : logValue1} onChange={(e) => activeGoal === 'fuel' ? setLogValue2(e.target.value) : setLogValue1(e.target.value)} className="w-full bg-white/50 border-2 border-transparent focus:theme-border rounded-2xl py-5 px-6 font-black text-gray-900 outline-none transition-all shadow-inner" placeholder="0" />
                </div>
              </div>
            </div>

            <button onClick={handleQuickLog} className="w-full py-6 gradient-bg text-white font-black rounded-3xl shadow-2xl theme-glow active:scale-95 transition-all text-sm uppercase tracking-[0.2em]">Confirm Logic</button>
          </div>
        </div>
      )}

      {/* Performance Grid - Glass */}
      <div className="grid grid-cols-2 gap-5 pb-10">
        <div className="liquid-glass rounded-[32px] p-6 text-center">
          <div className="w-12 h-12 bg-emerald-100/50 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white/40">
            <TrendingUp className="w-6 h-6 text-emerald-500" />
          </div>
          <p className="text-2xl font-black text-gray-900 tracking-tighter">
            {stats.stepsGoal > 0 ? Math.round((stats.steps / stats.stepsGoal) * 100) : 0}%
          </p>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] mt-1">Efficiency</p>
        </div>
        <div className="liquid-glass rounded-[32px] p-6 text-center">
          <div className="w-12 h-12 theme-light-bg rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white/40">
            <Sparkles className="w-6 h-6 theme-text" />
          </div>
          <p className="text-2xl font-black text-gray-900 tracking-tighter">12</p>
          <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em] mt-1">Cycle Streak</p>
        </div>
      </div>
    </div>
  );
};

const StatGoal = ({ icon, label, value, goal, color, unit, onClick }: any) => {
  const percent = goal > 0 ? Math.min(100, (value / goal) * 100) : 0;
  const isComplete = value >= goal;

  return (
    <button onClick={onClick} className="w-full text-left group p-5 rounded-3xl hover:bg-white/40 transition-all active:scale-[0.98]">
      <div className="flex justify-between items-center mb-3">
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${isComplete ? 'theme-bg text-white' : color + ' text-white'} shadow-sm border border-white/20 transition-transform group-hover:scale-110`}>
            {isComplete ? <CheckCircle2 className="w-5 h-5" /> : icon}
          </div>
          <div>
            <h4 className="text-sm font-black text-gray-900">{label}</h4>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{isComplete ? 'Target Reached' : `${Math.max(0, goal - value)} ${unit} left`}</p>
          </div>
        </div>
        <span className="text-xs font-black text-gray-900">{value.toLocaleString()} <span className="text-gray-400">/ {goal.toLocaleString()}</span></span>
      </div>
      <div className="h-2 w-full bg-black/5 rounded-full overflow-hidden shadow-inner">
        <div className={`h-full ${isComplete ? 'theme-bg' : color} transition-all duration-1000 ease-out`} style={{ width: `${percent}%` }} />
      </div>
    </button>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { 
  Utensils, 
  Droplets, 
  Timer, 
  Plus, 
  Clock,
  ChevronRight,
  Edit2
} from 'lucide-react';
import { JournalTab, DailyStats, FoodLogEntry, WorkoutEntry } from '../types';

interface Props {
  stats: DailyStats;
  foodLog: FoodLogEntry[];
  exerciseLog: WorkoutEntry[];
  onAddWater: () => void;
  onAddFood: (name: string, calories: number) => void;
  onAddExercise: (title: string, duration: number) => void;
}

const Journal: React.FC<Props> = ({ stats, foodLog, exerciseLog, onAddWater, onAddFood, onAddExercise }) => {
  const [activeSubTab, setActiveSubTab] = useState<JournalTab>('food');

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-black text-gray-900 tracking-tight">Diary</h1>
        <button className="p-3 liquid-glass rounded-2xl text-gray-400 active:scale-95 transition-all">
          <Edit2 className="w-4 h-4" />
        </button>
      </div>

      <div className="liquid-glass p-1.5 rounded-[20px] flex gap-1">
        <SubTab active={activeSubTab === 'food'} label="Fuel" onClick={() => setActiveSubTab('food')} />
        <SubTab active={activeSubTab === 'exercise'} label="Burn" onClick={() => setActiveSubTab('exercise')} />
        <SubTab active={activeSubTab === 'water'} label="Hydrate" onClick={() => setActiveSubTab('water')} />
      </div>

      <div className="space-y-4">
        {activeSubTab === 'food' && (
          <div className="space-y-3">
            {foodLog.map(entry => (
              <LogItem key={entry.id} title={entry.name} val={`${entry.calories} kcal`} time={entry.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} icon={<Utensils className="w-4 h-4" />} color="text-orange-600" bg="bg-orange-100/40" />
            ))}
            {foodLog.length === 0 && <EmptyState message="No nutritional data logged" />}
          </div>
        )}

        {activeSubTab === 'exercise' && (
          <div className="space-y-3">
            {exerciseLog.map(entry => (
