            ))}
            {exerciseLog.length === 0 && <EmptyState message="No kinetic logs available" />}
          </div>
        )}

        {activeSubTab === 'water' && (
          <div className="liquid-glass rounded-[40px] p-10 flex flex-col items-center gap-8 text-center relative overflow-hidden">
             <div className="w-40 h-40 rounded-full border-[10px] border-white/40 flex flex-col items-center justify-center relative overflow-hidden shadow-inner">
               <div className="absolute bottom-0 left-0 right-0 bg-blue-500/10 transition-all duration-1000" style={{ height: `${Math.min(100, (stats.water/stats.waterGoal)*100)}%` }}></div>
               <Droplets className="w-10 h-10 text-blue-500 mb-2 z-10 animate-bounce" />
               <span className="text-4xl font-black text-gray-900 z-10 tracking-tighter">{stats.water}</span>
               <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest z-10">/{stats.waterGoal} Units</span>
