import React, { useState } from 'react';
import { ChefHat, Plus, X, Sparkles, Clock, Utensils, ChevronDown, ChevronUp, CheckCircle2 } from 'lucide-react';
import { getRecipeRecommendations } from '../services/geminiService';
import { Recipe, UserProfile } from '../types';

interface Props {
  profile: UserProfile | null;
}

const Recipes: React.FC<Props> = ({ profile }) => {
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const addIngredient = () => {
    if (inputValue.trim() && !ingredients.includes(inputValue.trim())) {
      setIngredients([...ingredients, inputValue.trim()]);
      setInputValue('');
    }
  };

  const removeIngredient = (ingredient: string) => {
    setIngredients(ingredients.filter(i => i !== ingredient));
  };

  const findRecipes = async () => {
    if (ingredients.length === 0) return;
    setIsLoading(true);
    const results = await getRecipeRecommendations(ingredients, profile);
    setRecipes(results);
    setIsLoading(false);
  };

  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">
      <div className="mb-2">
        <h1 className="text-3xl font-black text-gray-900 tracking-tight">AI Chef</h1>
        <p className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mt-1">Culinary Synthesis</p>
      </div>

      <div className="liquid-glass p-8 rounded-[40px] shadow-sm">
        <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-4 block ml-2">Available Inventory</label>

        <div className="flex flex-wrap gap-2 mb-6 min-h-[40px]">
          {ingredients.map(ing => (
            <span key={ing} className="bg-white/60 theme-text px-4 py-2 rounded-2xl text-[11px] font-black uppercase tracking-wider flex items-center gap-3 border border-white/60 shadow-sm animate-in zoom-in">
              {ing}
              <button onClick={() => removeIngredient(ing)} className="p-1 hover:bg-black/5 rounded-full transition-colors">
                <X className="w-3.5 h-3.5" />
              </button>
            </span>
          ))}
          {ingredients.length === 0 && (
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest italic ml-2">Queue is empty...</p>
          )}
        </div>

        <div className="flex gap-3">
          <input 
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && addIngredient()}
            placeholder="Search ingredient..."
            className="flex-1 bg-white/40 border-2 border-transparent focus:theme-border rounded-[24px] px-6 py-4 text-sm font-black outline-none shadow-inner transition-all"
          />
          <button 
            onClick={addIngredient}
            className="p-4 bg-white/60 liquid-glass rounded-[24px] theme-text hover:bg-white active:scale-90 transition-all border border-white/60"
          >
            <Plus className="w-6 h-6" />
          </button>
        </div>

        <button 
          onClick={findRecipes}
          disabled={ingredients.length === 0 || isLoading}
          className="w-full mt-6 py-5 gradient-bg text-white font-black rounded-3xl shadow-2xl theme-glow disabled:opacity-40 transition-all flex items-center justify-center gap-3 active:scale-[0.98] uppercase tracking-[0.2em] text-sm"
        >
          {isLoading ? (
            <><RefreshCw className="w-5 h-5 animate-spin" /> Analyzing Ingredients</>
          ) : (
            <><ChefHat className="w-5 h-5" /> Generate Protocol</>
          )}
        </button>
      </div>

      <div className="space-y-5">
        {recipes.map(recipe => (
          <div key={recipe.id} className="liquid-glass rounded-[36px] overflow-hidden hover:bg-white/40 transition-all">
            <div className="p-8">
              <div className="flex justify-between items-start mb-3">
                <h3 className="text-xl font-black text-gray-900 leading-tight flex-1 mr-4 tracking-tight">{recipe.title}</h3>
                <div className="bg-white/60 px-4 py-1.5 rounded-full border border-white/60 shadow-sm">
                  <span className="text-xs font-black theme-text uppercase tracking-tighter">{recipe.calories} kcal</span>
                </div>
              </div>
              <p className="text-xs text-gray-500 font-medium leading-relaxed mb-6">{recipe.description}</p>

              <div className="flex items-center gap-6 mb-6">
                <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                  <Clock className="w-4 h-4" /> {recipe.prepTime}
                </div>
                <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
                  <Utensils className="w-4 h-4" /> {recipe.ingredientsUsed?.length || 0} Assets
                </div>
              </div>

              <button 
                onClick={() => setExpandedId(expandedId === recipe.id ? null : recipe.id)}
                className="w-full py-3 bg-black/5 rounded-2xl text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] flex items-center justify-center gap-2 hover:bg-black/10 transition-colors"
              >
                {expandedId === recipe.id ? <>Close Instructions <ChevronUp className="w-3.5 h-3.5" /></> : <>Access Protocol <ChevronDown className="w-3.5 h-3.5" /></>}
              </button>
            </div>

            {expandedId === recipe.id && (
              <div className="px-8 pb-10 pt-2 border-t border-white/20 animate-in slide-in-from-top-4 duration-500">
                <div className="mb-8">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-5">Execution Steps</h4>
                  <div className="space-y-5">
                    {recipe.instructions.map((step, idx) => (
                      <div key={idx} className="flex gap-5">
                        <div className="w-8 h-8 theme-light-bg rounded-xl flex items-center justify-center text-xs font-black theme-text shrink-0 border border-white/40">
                          {idx + 1}
                        </div>
                        <p className="text-sm text-gray-600 leading-relaxed font-medium">{step}</p>
                      </div>
                    ))}
                  </div>
                </div>

                {recipe.missingIngredients && recipe.missingIngredients.length > 0 && (
                  <div>
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] mb-3">Missing Telemetry</h4>
                    <div className="flex flex-wrap gap-2">
                      {recipe.missingIngredients.map(mi => (
                        <span key={mi} className="text-[9px] font-black text-amber-600 bg-amber-100/30 px-3 py-1.5 rounded-xl border border-white/40 uppercase tracking-wider">
                          {mi}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}

        {!isLoading && recipes.length === 0 && ingredients.length > 0 && (
          <div className="py-16 flex flex-col items-center text-center">
            <div className="w-20 h-20 liquid-glass rounded-[32px] flex items-center justify-center mb-6 animate-pulse">
              <ChefHat className="w-10 h-10 text-gray-300" />
            </div>
            <h4 className="text-gray-900 font-black text-lg tracking-tight">Ready for Input</h4>
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2">Standing by for ingredient list</p>
          </div>
        )}
      </div>
    </div>
  );
};

const RefreshCw = ({ className }: { className?: string }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"/>
    <path d="M21 3v5h-5"/>
    <path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16"/>
    <path d="M3 21v-5h5"/>
  </svg>
);

export default Recipes;

