export default Profile;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart2, 
  User, 
  Camera, 
  Plus, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer,
  Sparkles,
  Search,
  CheckCircle2,
  Clock,
  X,
  Zap,
  ChefHat
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import Recipes from './pages/Recipes';
import Onboarding from './pages/Onboarding';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry, UserProfile, AppTheme } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [isOnboarded, setIsOnboarded] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [theme, setTheme] = useState<AppTheme>('indigo');
  const [stats, setStats] = useState<DailyStats>({
    calories: 0,
    caloriesGoal: 2000,
    water: 0,
    waterGoal: 2.5, // 2.5 Litres
    steps: 0,
    stepsGoal: 10000,
    exercise: 0,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  const handleOnboardingComplete = (profile: UserProfile) => {
    let baseCals = 1800;
    if (profile.goal === 'loss') baseCals = 1600;
    if (profile.goal === 'gain') baseCals = 2400;
    if (profile.goal === 'maintain') baseCals = 2000;

    const activityMult = profile.activityLevel === 'active' ? 1.4 : profile.activityLevel === 'moderate' ? 1.2 : 1.0;
    const finalCals = Math.round(baseCals * activityMult);

    setUserProfile(profile);
    setStats(prev => ({
      ...prev,
      caloriesGoal: finalCals,
      waterGoal: 2.5 // Default to 2.5 Litres
    }));
    setIsOnboarded(true);
  };

  const handleSkipAll = () => {
    const guestProfile: UserProfile = {
      name: 'Friend',
      goal: 'maintain',
      weight: 70,
      height: 175,
      age: 25,
      activityLevel: 'moderate',
      isGuest: true,
      unitSystem: 'metric'
    };
    setUserProfile(guestProfile);
    setIsOnboarded(true);
  };

  const handleAuthChange = (authData: { provider: any, email?: string }) => {
    if (userProfile) {
      setUserProfile({
        ...userProfile,
        isGuest: false,
        authProvider: authData.provider,
        email: authData.email
      });
    }
  };

  const handleAddWater = (amount: number = 0.25) => {
    setStats(prev => ({ ...prev, water: parseFloat((prev.water + amount).toFixed(2)) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleAddSteps = (amount: number) => {
    setStats(prev => ({ ...prev, steps: prev.steps + amount }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      } else {
        alert("Sorry, couldn't identify the food. Please try again.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const confirmPendingFood = () => {
    if (pendingFood) {
      handleAddFood(pendingFood.name, pendingFood.calories);
      setPendingFood(null);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            stats={stats} 
            profile={userProfile} 
            onAddFood={handleAddFood}
            onAddWater={handleAddWater}
            onAddSteps={handleAddSteps}
            onAddExercise={handleAddExercise}
          />
        );
      case 'journal':
        return (
          <Journal 
            stats={stats} 
            foodLog={foodLog} 
            exerciseLog={exerciseLog}
            onAddWater={() => handleAddWater(0.25)}
            onAddFood={handleAddFood}
            onAddExercise={handleAddExercise}
          />
        );
      case 'recipes':
        return <Recipes profile={userProfile} stats={stats} />;
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return <Profile profile={userProfile} onAuthConversion={handleAuthChange} currentTheme={theme} onThemeChange={setTheme} />;
      default:
        return <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />;
    }
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={handleSkipAll} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#f8fafc] flex flex-col relative pb-28 overflow-hidden shadow-2xl" data-theme={theme}>
      {/* Background Blobs */}
      <div className="blob blob-1"></div>
      <div className="blob blob-2"></div>
      <div className="blob blob-3"></div>

      {/* Header */}
      <header className="p-6 pt-8 flex justify-between items-center bg-transparent z-10">
        <div>
          <h2 className="text-[10px] font-black theme-text uppercase tracking-[0.3em] mb-1">Status: Active</h2>
          <h1 className="text-3xl font-black text-gray-900 tracking-tight">Hi, {userProfile?.name}</h1>
        </div>
        <div className="flex gap-2">
          <button className="p-3.5 liquid-glass rounded-2xl transition-all active:scale-90">
            <Search className="w-5 h-5 text-gray-600" />
          </button>
          <button className="p-3.5 liquid-glass rounded-2xl transition-all active:scale-90" onClick={() => setActiveTab('profile')}>
            <User className="w-5 h-5 text-gray-600" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 px-6 z-10 no-scrollbar overflow-y-auto">
        {renderContent()}
      </main>

      {/* Floating Action Button (Camera) */}
      <div className="fixed bottom-28 right-8 z-20">
        <label className="cursor-pointer">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            onChange={handleImageUpload}
            disabled={isScanning}
          />
          <div className={`p-6 theme-glow gradient-bg rounded-[32px] shadow-2xl text-white transition-all transform active:scale-75 hover:scale-105 pulse-ring ${isScanning ? 'opacity-50' : ''}`}>
            {isScanning ? <Clock className="w-8 h-8 animate-spin" /> : <Camera className="w-8 h-8" />}
          </div>
        </label>
      </div>

      {/* AI Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/50 backdrop-blur-2xl z-[100] flex flex-col items-center justify-center animate-in fade-in duration-500">
          <div className="relative">
            <div className="w-40 h-40 border-8 theme-light-bg theme-border rounded-full animate-spin border-t-transparent"></div>
            <Sparkles className="w-16 h-16 theme-text absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-bounce" />
          </div>
          <h3 className="mt-10 text-3xl font-black text-gray-900 tracking-tighter">AI Synthesizing...</h3>
          <p className="text-xs font-black theme-text uppercase tracking-[0.2em] mt-3">Molecular Analysis Active</p>
        </div>
      )}

      {/* AI Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[110] flex items-center justify-center p-8 animate-in fade-in zoom-in duration-300">
          <div className="liquid-glass w-full rounded-[48px] p-10 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-3 gradient-bg"></div>
            <button 
              onClick={() => setPendingFood(null)}
              className="absolute top-8 right-8 p-2.5 bg-black/5 rounded-full transition-all hover:bg-black/10"
            >
              <X className="w-5 h-5 text-gray-400" />
            </button>

            <div className="flex flex-col items-center text-center">
              <div className="w-28 h-28 theme-light-bg rounded-[40px] flex items-center justify-center mb-8 transform -rotate-3 theme-border border-4 shadow-xl">
                <Utensils className="w-12 h-12 theme-text" />
              </div>

              <div className="bg-amber-100/60 px-5 py-2 rounded-full flex items-center gap-2 mb-4 border border-amber-200">
                <Zap className="w-4 h-4 text-amber-600 fill-amber-600" />
                <span className="text-[10px] font-black text-amber-700 uppercase tracking-[0.2em]">Neural Match Found</span>
              </div>

              <h3 className="text-4xl font-black text-gray-900 mb-2 tracking-tight">{pendingFood.name}</h3>

              <div className="bg-white/80 border-2 border-white/50 rounded-[32px] px-10 py-6 mb-12 shadow-inner">
                <span className="text-5xl font-black theme-text tracking-tighter">{pendingFood.calories}</span>
                <span className="ml-2 text-base font-black theme-text opacity-40 uppercase">kcal</span>
              </div>

              <div className="grid grid-cols-1 gap-4 w-full">
                <button 
                  onClick={confirmPendingFood}
                  className="py-6 rounded-3xl gradient-bg text-white font-black text-sm uppercase tracking-[0.2em] shadow-2xl theme-glow active:scale-95 transition-all"
                >
                  Log to Diary
                </button>
                <button 
                  onClick={() => setPendingFood(null)}
                  className="py-5 rounded-2xl text-gray-400 font-black text-[10px] uppercase tracking-[0.3em] hover:text-gray-600 transition-colors"
                >
                  Discard Analysis
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Bar (Glass Dock) */}
      <div className="fixed bottom-6 left-6 right-6 max-w-sm mx-auto z-20">
        <nav className="liquid-glass rounded-[32px] px-3 py-2.5 flex justify-between items-center shadow-2xl">
          <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} label="Dash" onClick={() => setActiveTab('dashboard')} />
          <NavButton active={activeTab === 'journal'} icon={<Calendar />} label="Diary" onClick={() => setActiveTab('journal')} />
          <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} label="Chef" onClick={() => setActiveTab('recipes')} />
          <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Stats" onClick={() => setActiveTab('progress')} />
          <NavButton active={activeTab === 'profile'} icon={<User />} label="Me" onClick={() => setActiveTab('profile')} />
        </nav>
      </div>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

const NavButton: React.FC<NavButtonProps> = ({ active, icon, label, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col items-center gap-1.5 py-3 transition-all rounded-2xl ${active ? 'bg-white/80 theme-text shadow-sm scale-110 -translate-y-1' : 'text-gray-400 hover:text-gray-600 hover:bg-white/20'}`}
  >
    {React.cloneElement(icon as React.ReactElement, { className: `w-5 h-5 ${active ? 'fill-current opacity-80' : ''}` })}
    <span className="text-[9px] font-black uppercase tracking-[0.2em]">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Sparkles, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer, 
  Target, 
  RefreshCw, 
  ChevronDown, 
  ChevronUp, 
  CheckCircle2,
  TrendingUp,
  Flame,
  X,
  Plus,
  Minus,
  ArrowUpRight
} from 'lucide-react';
import { DailyStats, UserProfile } from '../types';
import { suggestWorkout } from '../services/geminiService';

interface Props {
  stats: DailyStats;
  profile: UserProfile | null;
  onAddFood: (name: string, calories: number) => void;
  onAddWater: (amount: number) => void;
  onAddSteps: (amount: number) => void;
  onAddExercise: (title: string, duration: number) => void;
}

type GoalType = 'fuel' | 'hydrate' | 'steps' | 'burn' | null;

const Dashboard: React.FC<Props> = ({ stats, profile, onAddFood, onAddWater, onAddSteps, onAddExercise }) => {
  const [aiTip, setAiTip] = useState<string>("Initializing Neural Coach...");
  const [isExpanded, setIsExpanded] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const [activeGoal, setActiveGoal] = useState<GoalType>(null);
  const [logValue1, setLogValue1] = useState('');
  const [logValue2, setLogValue2] = useState('');

  const fetchTip = async () => {
    setIsRefreshing(true);
    try {
      const remainingCals = stats.caloriesGoal - stats.calories;
      const remainingEx = stats.exerciseGoal - stats.exercise;

      let contextPrompt = `Suggest a healthy next move. `;
      if (remainingEx > 0) {
        contextPrompt += `User needs ${remainingEx} more mins of activity. `;
      }
      if (remainingCals > 200) {
        contextPrompt += `User has ${remainingCals} kcal budget left. `;
      }

      const tip = await suggestWorkout(remainingEx > 0 ? remainingEx : 15, profile);
      setAiTip(tip || "Optimize your performance: drink 500ml water now.");
    } catch (error) {
      setAiTip("Neural link weak. Stay active and hydrated!");
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchTip();
  }, [profile]);

  const handleQuickLog = () => {
    switch (activeGoal) {
      case 'fuel':
        if (logValue1 && logValue2) onAddFood(logValue1, parseInt(logValue2));
        break;
      case 'hydrate':
        onAddWater(parseFloat(logValue1) || 0.25);
        break;
      case 'steps':
        onAddSteps(parseInt(logValue1) || 500);
        break;
      case 'burn':
        if (logValue1 && logValue2) onAddExercise(logValue1, parseInt(logValue2));
        break;
    }
    closeModal();
  };

  const openModal = (type: GoalType) => {
    setActiveGoal(type);
    setLogValue1('');
    setLogValue2('');
    if (type === 'hydrate') setLogValue1('0.25');
    if (type === 'burn') setLogValue1('Stretching');
    if (type === 'steps') setLogValue1('1000');
  };

  const closeModal = () => setActiveGoal(null);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* AI Recommendations Hub - Lively Glass */}
      <div className="liquid-glass rounded-[40px] p-8 relative overflow-hidden group hover:shadow-2xl transition-all border-2 border-white/50">
        <div className="absolute -top-12 -right-12 w-40 h-40 gradient-bg opacity-10 rounded-full blur-3xl group-hover:opacity-20 transition-opacity" />

        <div className="flex items-start gap-5 mb-4">
          <div className={`p-4 theme-bg text-white rounded-[24px] shadow-xl theme-glow relative ${isRefreshing ? 'animate-spin' : ''}`}>
             <Sparkles className="w-6 h-6" />
             <div className="absolute -top-1 -right-1 w-3 h-3 bg-white rounded-full border-2 theme-border animate-ping" />
          </div>
          <div className="flex-1">
            <div className="flex justify-between items-center mb-1">
              <h3 className="text-[11px] font-black theme-text uppercase tracking-[0.3em]">AI Synthesis</h3>
              <button 
                onClick={fetchTip}
                disabled={isRefreshing}
                className="p-1 text-gray-400 hover:theme-text transition-colors"
              >
                <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
              </button>
            </div>

            <div className={`text-base font-bold text-gray-900 leading-snug transition-all duration-500 ${!isExpanded ? 'line-clamp-2' : ''}`}>
              {aiTip}
            </div>

            <button 
              onClick={() => setIsExpanded(!isExpanded)}
              className="mt-4 px-4 py-2 bg-black/5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] theme-text flex items-center gap-1.5 hover:bg-white transition-all"
            >
              {isExpanded ? <>Minimize <ChevronUp className="w-3 h-3" /></> : <>Personalize <ChevronDown className="w-3 h-3" /></>}
            </button>
          </div>
        </div>
      </div>

      {/* Main Stats Protocol */}
      <div className="liquid-glass rounded-[48px] p-10 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 right-0 p-10 opacity-[0.03] rotate-12">
          <Target className="w-64 h-64" />
        </div>

        <div className="flex items-center justify-between mb-12">
          <div>
            <h2 className="text-3xl font-black text-gray-900 tracking-tighter">Daily Ops</h2>
            <div className="flex items-center gap-2 mt-1">
              <div className="w-2 h-2 rounded-full theme-bg animate-pulse" />
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">System Synchronized</p>
            </div>
          </div>
          <div className="liquid-glass bg-white/40 px-6 py-4 rounded-[32px] text-center border-white">
            <p className="text-4xl font-black theme-text tracking-tighter">
               {Math.round((stats.calories / stats.caloriesGoal) * 100)}<span className="text-sm opacity-50 ml-0.5">%</span>
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-4">
          <StatGoal icon={<Flame className="w-5 h-5" />} label="Calories" value={stats.calories} goal={stats.caloriesGoal} color="theme-bg" unit="kcal" onClick={() => openModal('fuel')} />
          <StatGoal icon={<Droplets className="w-5 h-5" />} label="Hydration" value={stats.water} goal={stats.waterGoal} color="bg-blue-500" unit="L" onClick={() => openModal('hydrate')} />
          <StatGoal icon={<Footprints className="w-5 h-5" />} label="Steps" value={stats.steps} goal={stats.stepsGoal} color="bg-emerald-500" unit="steps" onClick={() => openModal('steps')} />
          <StatGoal icon={<Timer className="w-5 h-5" />} label="Exercise" value={stats.exercise} goal={stats.exerciseGoal} color="bg-amber-500" unit="min" onClick={() => openModal('burn')} />
        </div>
      </div>

      {/* Entry Modal */}
      {activeGoal && (
        <div className="fixed inset-0 z-[150] flex items-end justify-center p-6 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-black/30 backdrop-blur-xl" onClick={closeModal} />
          <div className="liquid-glass w-full max-w-sm rounded-[48px] p-12 shadow-2xl relative animate-in slide-in-from-bottom-12">
            <button onClick={closeModal} className="absolute top-10 right-10 p-3 bg-black/5 rounded-full text-gray-400 hover:theme-text transition-all">
              <X className="w-6 h-6" />
            </button>

            <div className="flex items-center gap-5 mb-12">
              <div className="w-16 h-16 theme-light-bg rounded-3xl flex items-center justify-center theme-text border-2 border-white shadow-lg">
                {activeGoal === 'fuel' && <Utensils className="w-8 h-8" />}
                {activeGoal === 'hydrate' && <Droplets className="w-8 h-8" />}
                {activeGoal === 'steps' && <Footprints className="w-8 h-8" />}
                {activeGoal === 'burn' && <Timer className="w-8 h-8" />}
              </div>
              <div>
                <h3 className="text-3xl font-black text-gray-900 tracking-tight capitalize">{activeGoal} Log</h3>
                <p className="text-[10px] font-black theme-text uppercase tracking-[0.3em]">Telemetry Update</p>
              </div>
            </div>

            <div className="space-y-8 mb-12">
              {(activeGoal === 'fuel' || activeGoal === 'burn') && (
                <div className="space-y-3">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Observation</label>
                  <input type="text" value={logValue1} onChange={(e) => setLogValue1(e.target.value)} placeholder="Entry details..." className="w-full bg-white/60 border-2 border-transparent focus:theme-border rounded-3xl py-5 px-8 font-black text-gray-900 outline-none transition-all shadow-inner text-lg" />
                </div>
              )}
              <div className="space-y-3">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-3">Value Input</label>
                <div className="relative">
                  <input type="number" step={activeGoal === 'hydrate' ? '0.25' : '1'} value={activeGoal === 'fuel' ? logValue2 : logValue1} onChange={(e) => activeGoal === 'fuel' ? setLogValue2(e.target.value) : setLogValue1(e.target.value)} className="w-full bg-white/60 border-2 border-transparent focus:theme-border rounded-3xl py-5 px-8 font-black text-gray-900 outline-none transition-all shadow-inner text-2xl" placeholder="0" />
                  <span className="absolute right-8 top-1/2 -translate-y-1/2 text-xs font-black text-gray-300 uppercase tracking-widest">
                     {activeGoal === 'fuel' ? 'kcal' : activeGoal === 'hydrate' ? 'Litres' : activeGoal === 'burn' ? 'min' : 'steps'}
                  </span>
                </div>
              </div>
            </div>

            <button onClick={handleQuickLog} className="w-full py-6 gradient-bg text-white font-black rounded-3xl shadow-2xl theme-glow active:scale-90 transition-all text-sm uppercase tracking-[0.3em]">Sync Record</button>
          </div>
        </div>
      )}

      {/* Mini Performance Insight */}
      <div className="liquid-glass rounded-[32px] p-6 flex items-center justify-between group active:scale-[0.98] transition-all">
         <div className="flex items-center gap-4">
           <div className="w-12 h-12 bg-indigo-100/50 rounded-2xl flex items-center justify-center border border-white/50">
             <TrendingUp className="w-6 h-6 text-indigo-600" />
           </div>
           <div>
             <h4 className="font-black text-gray-900 text-sm">Peak Velocity</h4>
             <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Efficiency up 12% today</p>
           </div>
         </div>
         <ArrowUpRight className="w-5 h-5 text-gray-300 group-hover:text-indigo-500 transition-colors" />
      </div>
    </div>
  );
};

const StatGoal = ({ icon, label, value, goal, color, unit, onClick }: any) => {
  const percent = goal > 0 ? Math.min(100, (value / goal) * 100) : 0;
  const isComplete = value >= goal;

  return (
    <button onClick={onClick} className="w-full text-left group p-6 rounded-[32px] hover:bg-white/50 transition-all active:scale-[0.98] border border-transparent hover:border-white/60">
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-5">
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${isComplete ? 'theme-bg text-white' : color + ' text-white'} shadow-lg border-2 border-white transition-all group-hover:rotate-12`}>
            {isComplete ? <CheckCircle2 className="w-6 h-6" /> : icon}
          </div>
          <div>
            <h4 className="text-base font-black text-gray-900 tracking-tight">{label}</h4>
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">{isComplete ? 'Optimization Ready' : `${(goal - value).toFixed(unit === 'L' ? 2 : 0)} ${unit} to target`}</p>
          </div>
        </div>
        <div className="text-right">
           <span className="text-sm font-black text-gray-900">{value} <span className="text-gray-400 font-bold opacity-50">/ {goal} {unit}</span></span>
        </div>
      </div>
      <div className="h-3 w-full bg-black/5 rounded-full overflow-hidden shadow-inner border border-white/40">
        <div className={`h-full ${isComplete ? 'theme-bg' : color} transition-all duration-1500 ease-out relative`} style={{ width: `${percent}%` }}>
           <div className="absolute inset-0 bg-white/20 animate-pulse" />
        </div>
      </div>
    </button>
  );
};

export default Dashboard;

