import React, { useState } from 'react';
import { ChefHat, Plus, X, Sparkles, Clock, Utensils, ChevronDown, ChevronUp, CheckCircle2, RefreshCw, Zap, Flame } from 'lucide-react';
import { getRecipeRecommendations } from '../services/geminiService';
import { Recipe, UserProfile, DailyStats } from '../types';

interface Props {
  profile: UserProfile | null;
  stats: DailyStats;
}

const Recipes: React.FC<Props> = ({ profile, stats }) => {
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const addIngredient = () => {
    if (inputValue.trim() && !ingredients.includes(inputValue.trim())) {
      setIngredients([...ingredients, inputValue.trim()]);
      setInputValue('');
    }
  };

  const removeIngredient = (ingredient: string) => {
    setIngredients(ingredients.filter(i => i !== ingredient));
  };

  const findRecipes = async () => {
    if (ingredients.length === 0) return;
    setIsLoading(true);
    const results = await getRecipeRecommendations(ingredients, profile);
    setRecipes(results);
    setIsLoading(false);
  };

  const remainingKcal = stats.caloriesGoal - stats.calories;

  return (
    <div className="space-y-8 pb-28 animate-in fade-in duration-500">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-3xl font-black text-gray-900 tracking-tighter">AI Chef</h1>
          <p className="text-[10px] font-black theme-text uppercase tracking-[0.3em] mt-1">Culinary Intelligence</p>
        </div>
        <div className="liquid-glass px-5 py-2.5 rounded-full border-white flex items-center gap-2">
           <Flame className="w-4 h-4 text-orange-500" />
           <span className="text-[10px] font-black text-gray-700 uppercase tracking-widest">{remainingKcal > 0 ? `${remainingKcal} Budget` : 'Limit Reached'}</span>
        </div>
      </div>

      <div className="liquid-glass p-10 rounded-[48px] shadow-2xl border-white relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-2 gradient-bg opacity-40" />
        <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] mb-6 block ml-3">Inventory Manifest</label>

        <div className="flex flex-wrap gap-3 mb-8 min-h-[50px]">
          {ingredients.map(ing => (
            <span key={ing} className="bg-white px-5 py-3 rounded-[24px] text-xs font-black theme-text uppercase tracking-wider flex items-center gap-3 border-2 border-transparent hover:theme-border shadow-lg transition-all animate-in zoom-in group">
              {ing}
              <button onClick={() => removeIngredient(ing)} className="p-1 hover:bg-black/5 rounded-full transition-colors opacity-40 group-hover:opacity-100">
                <X className="w-4 h-4" />
              </button>
            </span>
          ))}
          {ingredients.length === 0 && (
            <div className="flex items-center gap-3 ml-3 opacity-30">
               <div className="w-3 h-3 theme-bg rounded-full animate-pulse" />
               <p className="text-[11px] text-gray-400 font-black uppercase tracking-widest italic">Ready for Scanning...</p>
            </div>
          )}
        </div>

        <div className="flex gap-4">
          <input 
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && addIngredient()}
            placeholder="Search Assets..."
            className="flex-1 bg-white border-2 border-transparent focus:theme-border rounded-[28px] px-8 py-5 text-base font-black outline-none shadow-inner transition-all placeholder:text-gray-300"
          />
          <button 
            onClick={addIngredient}
            className="p-5 bg-white liquid-glass rounded-[28px] theme-text hover:scale-110 active:scale-90 transition-all border-white shadow-xl"
          >
            <Plus className="w-7 h-7" />
          </button>
        </div>

        <button 
          onClick={findRecipes}
          disabled={ingredients.length === 0 || isLoading}
          className="w-full mt-8 py-6 gradient-bg text-white font-black rounded-3xl shadow-2xl theme-glow disabled:opacity-40 transition-all flex items-center justify-center gap-3 active:scale-95 uppercase tracking-[0.3em] text-sm"
        >
          {isLoading ? (
            <><RefreshCw className="w-6 h-6 animate-spin" /> Analyzing Ingredients</>
          ) : (
            <><ChefHat className="w-6 h-6" /> Generate Recipe Protocol</>
          )}
        </button>
      </div>

      <div className="space-y-6">
        {recipes.map((recipe, idx) => (
          <div key={recipe.id} className="liquid-glass rounded-[40px] overflow-hidden hover:bg-white/80 transition-all border-white shadow-lg animate-in slide-in-from-bottom-8 duration-500" style={{ animationDelay: `${idx * 150}ms` }}>
            <div className="p-10">
              <div className="flex justify-between items-start mb-6">
                <div>
                   <h3 className="text-2xl font-black text-gray-900 leading-tight tracking-tight mb-1">{recipe.title}</h3>
                   <div className="flex items-center gap-2">
                      <Zap className="w-3.5 h-3.5 text-amber-500" />
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Efficiency: Optimal</p>
                   </div>
                </div>
                <div className="bg-white/80 px-5 py-2.5 rounded-full border-2 border-white shadow-xl">
                  <span className="text-sm font-black theme-text tracking-tighter">{recipe.calories} kcal</span>
                </div>
              </div>

              <p className="text-sm text-gray-500 font-medium leading-relaxed mb-8">{recipe.description}</p>

              <div className="flex items-center gap-8 mb-8">
                <div className="flex items-center gap-2.5 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">
                  <Clock className="w-5 h-5 theme-text opacity-40" /> {recipe.prepTime}
                </div>
                <div className="flex items-center gap-2.5 text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">
                  <Utensils className="w-5 h-5 theme-text opacity-40" /> {recipe.ingredientsUsed?.length || 0} Assets
                </div>
              </div>

              <button 
                onClick={() => setExpandedId(expandedId === recipe.id ? null : recipe.id)}
                className="w-full py-4 bg-black/5 rounded-2xl text-[10px] font-black theme-text uppercase tracking-[0.3em] flex items-center justify-center gap-3 hover:bg-white hover:shadow-sm transition-all border border-transparent hover:border-white/50"
              >
                {expandedId === recipe.id ? <>Close Instructions <ChevronUp className="w-4 h-4" /></> : <>Access Protocol <ChevronDown className="w-4 h-4" /></>}
              </button>
            </div>

            {expandedId === recipe.id && (
              <div className="px-10 pb-12 pt-4 border-t-2 border-white/30 animate-in slide-in-from-top-6 duration-700">
                <div className="mb-10">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] mb-6">Sequence of Execution</h4>
                  <div className="space-y-6">
                    {recipe.instructions.map((step, idx) => (
                      <div key={idx} className="flex gap-6 group">
                        <div className="w-10 h-10 theme-bg rounded-2xl flex items-center justify-center text-sm font-black text-white shrink-0 border-4 border-white shadow-xl transition-transform group-hover:scale-110">
                          {idx + 1}
                        </div>
                        <p className="text-[15px] text-gray-700 leading-relaxed font-bold pt-1">{step}</p>
                      </div>
                    ))}
                  </div>
                </div>

                {recipe.missingIngredients && recipe.missingIngredients.length > 0 && (
                  <div className="bg-amber-50/50 p-6 rounded-[32px] border-2 border-amber-100/50">
                    <h4 className="text-[10px] font-black text-amber-700 uppercase tracking-[0.4em] mb-4 flex items-center gap-2">
                       <Zap className="w-3.5 h-3.5" /> Missing Assets
                    </h4>
                    <div className="flex flex-wrap gap-2.5">
                      {recipe.missingIngredients.map(mi => (
                        <span key={mi} className="text-[10px] font-black text-amber-800 bg-white/60 px-4 py-2 rounded-xl border border-amber-200 uppercase tracking-widest shadow-sm">
                          {mi}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}

        {!isLoading && recipes.length === 0 && ingredients.length === 0 && (
          <div className="py-24 flex flex-col items-center text-center">
            <div className="w-28 h-28 liquid-glass rounded-[48px] flex items-center justify-center mb-10 animate-bounce duration-3000 border-white shadow-2xl">
              <Sparkles className="w-12 h-12 theme-text opacity-30" />
            </div>
            <h4 className="text-gray-900 font-black text-2xl tracking-tighter">Kitchen Sync Waiting</h4>
            <p className="text-[11px] text-gray-400 font-black uppercase tracking-[0.3em] mt-3">Upload ingredients to initialize protocol</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Recipes;

import React, { useState, useEffect } from 'react';
import { 
  Sparkles, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer, 
  Target, 
  RefreshCw, 
  ChevronDown, 
  ChevronUp, 
  CheckCircle2,
  TrendingUp,
  Flame,
  X,
  Plus,
  Minus,
  ArrowUpRight,
  Zap
} from 'lucide-react';
import { DailyStats, UserProfile } from '../types';
import { suggestWorkout } from '../services/geminiService';

interface Props {
  stats: DailyStats;
  profile: UserProfile | null;
  onAddFood: (name: string, calories: number) => void;
  onAddWater: (amount: number) => void;
  onAddSteps: (amount: number) => void;
  onAddExercise: (title: string, duration: number) => void;
}

type GoalType = 'fuel' | 'hydrate' | 'steps' | 'burn' | null;

const Dashboard: React.FC<Props> = ({ stats, profile, onAddFood, onAddWater, onAddSteps, onAddExercise }) => {
  const [aiTip, setAiTip] = useState<string>("Initializing Neural Coach...");
  const [isExpanded, setIsExpanded] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const [activeGoal, setActiveGoal] = useState<GoalType>(null);
  const [logValue1, setLogValue1] = useState('');
  const [logValue2, setLogValue2] = useState('');

  const fetchTip = async () => {
    setIsRefreshing(true);
    try {
      const remainingEx = stats.exerciseGoal - stats.exercise;
      const tip = await suggestWorkout(remainingEx > 0 ? remainingEx : 15, profile);
      setAiTip(tip || "Optimize your performance: drink 500ml water now.");
    } catch (error) {
      setAiTip("Neural link weak. Stay active and hydrated!");
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchTip();
  }, [profile]);

  const handleQuickLog = () => {
    switch (activeGoal) {
      case 'fuel':
        if (logValue2) onAddFood(logValue1 || 'Quick Meal', parseInt(logValue2));
        break;
      case 'hydrate':
        onAddWater(parseFloat(logValue1) || 0.25);
        break;
      case 'steps':
        onAddSteps(parseInt(logValue1) || 500);
        break;
      case 'burn':
        if (logValue2) onAddExercise(logValue1 || 'Workout', parseInt(logValue2));
        break;
    }
    closeModal();
  };

  const openModal = (type: GoalType) => {
    setActiveGoal(type);
    setLogValue1('');
    setLogValue2('');
    if (type === 'hydrate') setLogValue1('0.25');
    if (type === 'burn') { setLogValue1('Strength Training'); setLogValue2('30'); }
    if (type === 'steps') setLogValue1('1000');
    if (type === 'fuel') { setLogValue1('Meal'); setLogValue2('500'); }
  };

  const closeModal = () => setActiveGoal(null);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-12">
      {/* AI Recommendations Hub */}
      <div className="liquid-glass rounded-[40px] p-8 relative overflow-hidden group hover:shadow-2xl transition-all border-2 border-white/50">
        <div className="absolute -top-12 -right-12 w-40 h-40 gradient-bg opacity-10 rounded-full blur-3xl group-hover:opacity-20 transition-opacity" />

        <div className="flex items-start gap-5 mb-4">
          <div className={`p-4 theme-bg text-white rounded-[24px] shadow-xl theme-glow relative ${isRefreshing ? 'animate-spin' : ''}`}>
             <Sparkles className="w-6 h-6" />
             <div className="absolute -top-1 -right-1 w-3 h-3 bg-white rounded-full border-2 theme-border animate-ping" />
          </div>
          <div className="flex-1">
            <div className="flex justify-between items-center mb-1">
              <h3 className="text-[11px] font-black theme-text uppercase tracking-[0.3em]">AI Synthesis</h3>
              <button 
                onClick={fetchTip}
                disabled={isRefreshing}
                className="p-1 text-gray-400 hover:theme-text transition-colors"
              >
                <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
              </button>
            </div>

            <div className={`text-base font-bold text-gray-900 leading-snug transition-all duration-500 ${!isExpanded ? 'line-clamp-2' : ''}`}>
              {aiTip}
            </div>

            <button 
              onClick={() => setIsExpanded(!isExpanded)}
              className="mt-4 px-4 py-2 bg-black/5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] theme-text flex items-center gap-1.5 hover:bg-white transition-all"
            >
              {isExpanded ? <>Minimize <ChevronUp className="w-3 h-3" /></> : <>Personalize <ChevronDown className="w-3 h-3" /></>}
            </button>
          </div>
        </div>
      </div>

      {/* Quick Action Bar for Discoverability */}
      <div className="flex gap-4 overflow-x-auto no-scrollbar pb-2">
        <QuickActionButton icon={<Flame className="w-5 h-5" />} label="+ Cal" color="bg-orange-500" onClick={() => openModal('fuel')} />
        <QuickActionButton icon={<Droplets className="w-5 h-5" />} label="+ Water" color="bg-blue-500" onClick={() => openModal('hydrate')} />
        <QuickActionButton icon={<Footprints className="w-5 h-5" />} label="+ Steps" color="bg-emerald-500" onClick={() => openModal('steps')} />
        <QuickActionButton icon={<Timer className="w-5 h-5" />} label="+ Ex" color="bg-amber-500" onClick={() => openModal('burn')} />
      </div>

      {/* Main Stats Protocol */}
      <div className="liquid-glass rounded-[48px] p-10 relative overflow-hidden shadow-2xl">
        <div className="absolute top-0 right-0 p-10 opacity-[0.03] rotate-12">
          <Target className="w-64 h-64" />
        </div>

        <div className="flex items-center justify-between mb-12">
          <div>
            <h2 className="text-3xl font-black text-gray-900 tracking-tighter">Daily Ops</h2>
            <div className="flex items-center gap-2 mt-1">
              <div className="w-2 h-2 rounded-full theme-bg animate-pulse" />
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">System Synchronized</p>
            </div>
          </div>
          <div className="liquid-glass bg-white/40 px-6 py-4 rounded-[32px] text-center border-white">
            <p className="text-4xl font-black theme-text tracking-tighter">
