      <div className="blob blob-2"></div>
      <div className="blob blob-3"></div>

      {/* Header */}
      <header className="p-6 pt-8 flex justify-between items-center bg-transparent z-10">
        <div>
          <h2 className="text-[10px] font-black theme-text uppercase tracking-[0.3em] mb-1">Status: Active</h2>
          <h1 className="text-3xl font-black text-gray-900 tracking-tight">Hi, {userProfile?.name}</h1>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-3.5 liquid-glass rounded-2xl transition-all active:scale-90 shadow-md">
            {isDarkMode ? <Sun className="w-5 h-5 text-amber-400" /> : <Moon className="w-5 h-5 text-slate-700" />}
