            <div className="w-40 h-40 border-8 theme-light-bg theme-border rounded-full animate-spin border-t-transparent"></div>
            <Sparkles className="w-16 h-16 theme-text absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-bounce" />
