      {/* Floating Action Button (Camera) */}
      <div className="fixed bottom-32 right-8 z-20">
        <label className="cursor-pointer">
          <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} disabled={isScanning} />
          <div className={`w-16 h-16 bg-[#5DC6F1] flex items-center justify-center rounded-2xl shadow-xl text-white transition-all transform active:scale-75 hover:scale-105 ${isScanning ? 'opacity-50' : ''}`}>
            {isScanning ? <Clock className="w-8 h-8 animate-spin" /> : <Camera className="w-8 h-8" />}
          </div>
        </label>
      </div>

      {/* Food Scan Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-md z-[110] flex items-center justify-center p-8">
          <div className="bg-white dark:bg-slate-900 w-full rounded-[40px] p-8 shadow-2xl text-center">
            <h3 className="text-2xl font-black text-gray-900 dark:text-white mb-2">{pendingFood.name}</h3>
            <p className="text-gray-500 mb-8 font-medium">Estimated Calorie Intake: <span className="text-orange-500 font-black">{pendingFood.calories} kcal</span></p>
            <div className="flex flex-col gap-3">
              <button onClick={confirmPendingFood} className="w-full py-5 rounded-2xl bg-[#5DC6F1] text-white font-black">Confirm & Log</button>
              <button onClick={() => setPendingFood(null)} className="w-full py-4 rounded-2xl bg-gray-100 text-gray-500 font-bold">Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

