type GoalType = 'fuel' | 'hydrate' | 'steps' | 'burn' | null;

const Dashboard: React.FC<Props> = ({ stats, profile, onAddFood, onAddWater, onAddSteps, onAddExercise }) => {
  const [aiTip, setAiTip] = useState<string>("Initializing Neural Coach...");
  const [isExpanded, setIsExpanded] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const [activeGoal, setActiveGoal] = useState<GoalType>(null);
  const [logValue1, setLogValue1] = useState('');
  const [logValue2, setLogValue2] = useState('');

  const fetchTip = async () => {
    setIsRefreshing(true);
    try {
      const remainingEx = stats.exerciseGoal - stats.exercise;
      const tip = await suggestWorkout(remainingEx > 0 ? remainingEx : 15, profile);
      setAiTip(tip || "Optimize your performance: drink 500ml water now.");
    } catch (error) {
      setAiTip("Neural link weak. Stay active and hydrated!");
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchTip();
  }, [profile]);

  const handleQuickLog = () => {
    switch (activeGoal) {
      case 'fuel':
        if (logValue2) onAddFood(logValue1 || 'Quick Meal', parseInt(logValue2));
        break;
      case 'hydrate':
        onAddWater(parseFloat(logValue1) || 0.25);
        break;
      case 'steps':
        onAddSteps(parseInt(logValue1) || 500);
        break;
      case 'burn':
        if (logValue2) onAddExercise(logValue1 || 'Workout', parseInt(logValue2));
        break;
    }
    closeModal();
  };

  const openModal = (type: GoalType) => {
    setActiveGoal(type);
    setLogValue1('');
    setLogValue2('');
    if (type === 'hydrate') setLogValue1('0.25');
    if (type === 'burn') { setLogValue1('Strength Training'); setLogValue2('30'); }
    if (type === 'steps') setLogValue1('1000');
    if (type === 'fuel') { setLogValue1('Meal'); setLogValue2('500'); }
  };

  const closeModal = () => setActiveGoal(null);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-12">
      {/* Top row cards: Calories and Weight style from sample */}
      <div className="grid grid-cols-2 gap-4">
        {/* Calories Card */}
        <div className="bg-white dark:bg-slate-900 rounded-[32px] p-5 stat-card-shadow border border-gray-50 dark:border-slate-800">
