            <div className="w-10 h-10 bg-orange-100 dark:bg-orange-900/30 flex items-center justify-center rounded-xl">
              <Flame className="w-5 h-5 text-orange-500" />
            </div>
            <span className="text-xs font-bold text-gray-400">1d</span>
          </div>
          <h3 className="text-sm font-bold text-gray-900 dark:text-white mb-1">Calories</h3>
          <p className="text-[10px] text-gray-400 font-medium leading-tight mb-4">Great physical activity</p>
          <div className="flex items-baseline gap-1">
            <span className="text-lg font-black text-gray-900 dark:text-white">{stats.calories}</span>
            <span className="text-[10px] font-bold text-gray-400">/{stats.caloriesGoal}Kcal</span>
          </div>
        </div>

        {/* Weight Card */}
        <div className="bg-white dark:bg-slate-900 rounded-[32px] p-5 stat-card-shadow border border-gray-50 dark:border-slate-800">
          <div className="flex items-center justify-between mb-4">
            <div className="w-10 h-10 bg-green-100 dark:bg-green-900/30 flex items-center justify-center rounded-xl">
              <Activity className="w-5 h-5 text-green-500" />
            </div>
            <span className="text-xs font-bold text-gray-400">6'0"</span>
          </div>
          <h3 className="text-sm font-bold text-gray-900 dark:text-white mb-1">Weight</h3>
          <p className="text-[10px] text-gray-400 font-medium leading-tight mb-4">Healthy weight is 72-82kg</p>
          <div className="flex items-baseline gap-1">
            <span className="text-lg font-black text-gray-900 dark:text-white">198</span>
            <span className="text-[10px] font-bold text-gray-400">lbs</span>
          </div>
        </div>
      </div>

      {/* Heart Rate / Middle Card from sample */}
      <div className="bg-white dark:bg-slate-900 rounded-[40px] p-6 stat-card-shadow border border-gray-50 dark:border-slate-800 relative overflow-hidden">
        <div className="flex justify-between items-start mb-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/20 flex items-center justify-center rounded-xl">
              <Heart className="w-5 h-5 text-[#5DC6F1]" />
            </div>
            <div>
              <h3 className="text-sm font-black text-gray-900 dark:text-white">Heart rate</h3>
              <div className="flex items-center gap-1">
                <div className="w-1.5 h-1.5 rounded-full bg-green-500" />
