          <svg className="w-full h-full" viewBox="0 0 400 100">
            <path 
              d="M0 50 L100 50 L110 30 L120 70 L130 10 L140 90 L150 50 L250 50 L260 20 L270 80 L280 50 L400 50" 
              fill="none" 
              stroke="#5DC6F1" 
              strokeWidth="2.5" 
              strokeLinecap="round" 
              strokeLinejoin="round" 
            />
          </svg>
        </div>

        <div className="flex items-center justify-between">
          <div className="flex items-baseline gap-1">
            <span className="text-2xl font-black text-gray-900 dark:text-white">88</span>
            <span className="text-[10px] font-bold text-gray-400">bpm</span>
