          <button className="w-10 h-10 bg-[#1C1C1E] rounded-full flex items-center justify-center text-white">
            <ChevronRight className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* AI Intelligence / Suggestions (Styled cleanly like Today Exercises) */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-black text-gray-900 dark:text-white">AI Coach Suggestions</h2>
          <button onClick={fetchTip} className="text-xs font-bold text-[#5DC6F1]">Refresh</button>
        </div>

        <div className="bg-[#EBF7FD] dark:bg-blue-900/10 rounded-[32px] p-6 border border-blue-50 dark:border-blue-900/20">
          <div className="flex items-start gap-4">
            <div className="p-3 bg-white dark:bg-slate-800 rounded-2xl shadow-sm text-[#5DC6F1]">
              <Sparkles className="w-5 h-5" />
            </div>
            <p className="text-sm font-bold text-gray-700 dark:text-gray-300 leading-snug italic">
              "{aiTip}"
            </p>
          </div>
        </div>
      </div>

      {/* Today Exercises List from sample */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-black text-gray-900 dark:text-white">Today Exercises</h2>
