              <input 
                type="number" 
                step={activeGoal === 'hydrate' ? '0.25' : '1'} 
                value={activeGoal === 'fuel' || activeGoal === 'burn' ? logValue2 : logValue1} 
                onChange={(e) => activeGoal === 'fuel' || activeGoal === 'burn' ? setLogValue2(e.target.value) : setLogValue1(e.target.value)} 
                className="w-full bg-gray-50 dark:bg-slate-800 border-none rounded-3xl py-6 px-8 text-2xl font-black focus:ring-2 focus:ring-[#5DC6F1]" 
                placeholder="0" 
              />
