import React, { useState } from 'react';
import { 
  Utensils, 
  Droplets, 
  Timer, 
  Plus, 
  Clock,
  ChevronRight,
  Edit2,
  Zap,
  Flame,
  Activity,
  X,
  PlusCircle
} from 'lucide-react';
import { JournalTab, DailyStats, FoodLogEntry, WorkoutEntry } from '../types';

interface Props {
  stats: DailyStats;
  foodLog: FoodLogEntry[];
  exerciseLog: WorkoutEntry[];
  onAddWater: () => void;
  onAddFood: (name: string, calories: number) => void;
  onAddExercise: (title: string, duration: number) => void;
}

const Journal: React.FC<Props> = ({ stats, foodLog, exerciseLog, onAddWater, onAddFood, onAddExercise }) => {
  const [activeSubTab, setActiveSubTab] = useState<JournalTab>('food');
  const [showLogModal, setShowLogModal] = useState(false);
  const [logName, setLogName] = useState('');
  const [logVal, setLogVal] = useState('');

  const handleManualAdd = () => {
    if (!logVal) return;
    if (activeSubTab === 'food') {
      onAddFood(logName || 'Manual Meal', parseInt(logVal));
    } else if (activeSubTab === 'exercise') {
      onAddExercise(logName || 'Manual Workout', parseInt(logVal));
    }
    setLogName('');
    setLogVal('');
    setShowLogModal(false);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-28">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-sm font-medium text-gray-400">Activity Log</h2>
          <h1 className="text-2xl font-black text-gray-900 dark:text-white tracking-tight">Bio Diary</h1>
        </div>
        <button onClick={() => setShowLogModal(true)} className="w-12 h-12 bg-[#1C1C1E] rounded-2xl flex items-center justify-center text-white shadow-xl">
          <PlusCircle className="w-6 h-6" />
        </button>
      </div>

      {/* Modern Tab Bar */}
      <div className="flex gap-2 p-1 bg-white dark:bg-slate-900 rounded-2xl border border-gray-100 dark:border-slate-800">
        <SubTab active={activeSubTab === 'food'} label="Fuel" icon={<Flame className="w-4 h-4" />} onClick={() => setActiveSubTab('food')} />
        <SubTab active={activeSubTab === 'exercise'} label="Burn" icon={<Activity className="w-4 h-4" />} onClick={() => setActiveSubTab('exercise')} />
        <SubTab active={activeSubTab === 'water'} label="Hydrate" icon={<Droplets className="w-4 h-4" />} onClick={() => setActiveSubTab('water')} />
      </div>

      <div className="space-y-4">
        {activeSubTab === 'food' && (
          <div className="space-y-3">
            {foodLog.map((entry, idx) => (
              <LogItem 
                key={entry.id} 
                title={entry.name} 
                val={`${entry.calories} kcal`} 
                time={entry.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} 
                icon={<Utensils className="w-5 h-5" />} 
                color="#FF7D54" 
                bg="bg-orange-50 dark:bg-orange-900/10"
              />
            ))}
            {foodLog.length === 0 && <EmptyState message="System waiting for nutritional data" />}
          </div>
        )}

        {activeSubTab === 'exercise' && (
          <div className="space-y-3">
            {exerciseLog.map((entry, idx) => (
              <LogItem 
                key={entry.id} 
                title={entry.title} 
                val={`${entry.duration} min`} 
                time={entry.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} 
                icon={<Timer className="w-5 h-5" />} 
                color="#A3D139" 
                bg="bg-green-50 dark:bg-green-900/10"
              />
            ))}
            {exerciseLog.length === 0 && <EmptyState message="Kinetic logs pending upload" />}
          </div>
        )}

        {activeSubTab === 'water' && (
          <div className="bg-white dark:bg-slate-900 rounded-[48px] p-10 flex flex-col items-center gap-10 text-center border border-gray-50 dark:border-slate-800 shadow-sm">
             <div className="w-48 h-48 rounded-full border-[10px] border-gray-50 dark:border-slate-800 flex flex-col items-center justify-center relative overflow-hidden shadow-inner">
               <div className="absolute bottom-0 left-0 right-0 bg-[#5DC6F1] opacity-10 transition-all duration-1000" style={{ height: `${Math.min(100, (stats.water/stats.waterGoal)*100)}%` }}></div>
               <div className="relative z-10 flex flex-col items-center">
                 <Droplets className="w-12 h-12 text-[#5DC6F1] mb-2" />
                 <span className="text-5xl font-black text-gray-900 dark:text-white tracking-tighter">{stats.water.toFixed(2)}</span>
                 <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">/ {stats.waterGoal} Litres</span>
               </div>
             </div>
             <button 
              onClick={onAddWater} 
              className="w-full py-6 bg-[#5DC6F1] text-white font-black rounded-3xl shadow-xl active:scale-95 transition-all uppercase tracking-widest text-sm"
             >
              Add 250ml
             </button>
          </div>
        )}
      </div>

      {/* Manual Diary Modal */}
      {showLogModal && (
        <div className="fixed inset-0 z-[150] flex items-end justify-center p-6 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-md" onClick={() => setShowLogModal(false)} />
          <div className="bg-white dark:bg-slate-900 w-full max-w-sm rounded-[48px] p-10 shadow-2xl relative animate-in slide-in-from-bottom-12">
            <button onClick={() => setShowLogModal(false)} className="absolute top-10 right-10 p-3 bg-gray-50 dark:bg-white/10 rounded-full text-gray-400">
              <X className="w-6 h-6" />
            </button>
            <h3 className="text-3xl font-black text-gray-900 dark:text-white mb-8">Manual Entry</h3>
            <div className="space-y-6 mb-10">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Description</label>
                <input type="text" value={logName} onChange={(e) => setLogName(e.target.value)} placeholder="e.g. Lunch, Cycling..." className="w-full bg-gray-50 dark:bg-slate-800 border-none rounded-2xl py-5 px-6 font-black outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2">Value ({activeSubTab === 'food' ? 'kcal' : 'min'})</label>
                <input type="number" value={logVal} onChange={(e) => setLogVal(e.target.value)} placeholder="0" className="w-full bg-gray-50 dark:bg-slate-800 border-none rounded-2xl py-5 px-6 font-black outline-none text-2xl" />
              </div>
            </div>
            <button onClick={handleManualAdd} className="w-full py-6 bg-[#1C1C1E] text-white font-black rounded-3xl shadow-xl">Add to Log</button>
          </div>
        </div>
      )}
    </div>
  );
};

