    onClick={onClick} 
    className={`flex-1 py-4 rounded-xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${active ? 'bg-[#5DC6F1] text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
