  Home
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import Recipes from './pages/Recipes';
import Onboarding from './pages/Onboarding';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry, UserProfile, AppTheme } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [isOnboarded, setIsOnboarded] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [theme, setTheme] = useState<AppTheme>('indigo');
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [stats, setStats] = useState<DailyStats>({
    calories: 1290,
    caloriesGoal: 2340,
    water: 1.5, 
    waterGoal: 2.5, 
    steps: 6430,
    stepsGoal: 10000,
    exercise: 15,
    exerciseGoal: 45
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  useEffect(() => {
    document.documentElement.setAttribute('data-mode', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const handleOnboardingComplete = (profile: UserProfile) => {
    setUserProfile(profile);
    setIsOnboarded(true);
  };

  const handleSkipAll = () => {
    const guestProfile: UserProfile = {
      name: 'Fred',
      goal: 'maintain',
      weight: 198,
      height: 183,
      age: 28,
      activityLevel: 'moderate',
      isGuest: true,
      unitSystem: 'imperial'
    };
    setUserProfile(guestProfile);
    setIsOnboarded(true);
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={handleSkipAll} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen flex flex-col relative pb-32 overflow-hidden" data-theme={theme} data-mode={isDarkMode ? 'dark' : 'light'}>
      {/* Background Blobs Restore */}
      <div className="blob blob-1"></div>
      <div className="blob blob-2"></div>
      <div className="blob blob-3"></div>

      <header className="p-6 pt-10 flex justify-between items-center z-10">
        <div>
          <h2 className="text-[10px] font-black theme-text uppercase tracking-[0.3em] mb-1">Neural Core Active</h2>
          <h1 className="text-3xl font-black text-gray-900 dark:text-white tracking-tight">Hi, {userProfile?.name}</h1>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-3.5 liquid-glass rounded-2xl shadow-sm transition-all active:scale-90">
            {isDarkMode ? <Sun className="w-5 h-5 text-amber-400" /> : <Moon className="w-5 h-5 text-slate-700" />}
          </button>
          <button className="p-3.5 liquid-glass rounded-2xl shadow-sm transition-all active:scale-90" onClick={() => setActiveTab('profile')}>
            <User className="w-5 h-5 text-gray-600 dark:text-gray-300" />
          </button>
        </div>
      </header>

      <main className="flex-1 px-6 z-10 no-scrollbar overflow-y-auto">
        {activeTab === 'dashboard' && <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={(a) => setStats(s => ({...s, water: s.water + a}))} onAddSteps={(a) => setStats(s => ({...s, steps: s.steps + a}))} onAddExercise={(t, d) => setStats(s => ({...s, exercise: s.exercise + d}))} />}
        {activeTab === 'journal' && <Journal stats={stats} foodLog={foodLog} exerciseLog={exerciseLog} onAddWater={() => setStats(s => ({...s, water: s.water + 0.25}))} onAddFood={handleAddFood} onAddExercise={(t, d) => setStats(s => ({...s, exercise: s.exercise + d}))} />}
        {activeTab === 'recipes' && <Recipes profile={userProfile} stats={stats} />}
        {activeTab === 'progress' && <Progress stats={stats} />}
        {activeTab === 'profile' && <Profile profile={userProfile} currentTheme={theme} onThemeChange={setTheme} isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} />}
      </main>

      {/* Restore Floating Action Button Style */}
      <div className="fixed bottom-32 right-8 z-20">
        <label className="cursor-pointer">
          <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} disabled={isScanning} />
          <div className="p-6 gradient-bg rounded-[32px] shadow-2xl text-white transition-all transform active:scale-75 theme-glow">
            <Camera className="w-8 h-8" />
          </div>
        </label>
      </div>

      {/* Restore Liquid Navigation Dock */}
      <div className="fixed bottom-8 left-6 right-6 max-w-sm mx-auto z-20">
        <nav className="liquid-glass p-2.5 flex justify-between items-center shadow-2xl">
          <NavButton active={activeTab === 'dashboard'} icon={<Home />} onClick={() => setActiveTab('dashboard')} />
          <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} onClick={() => setActiveTab('recipes')} />
          <NavButton active={activeTab === 'journal'} icon={<Bookmark />} onClick={() => setActiveTab('journal')} />
          <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} onClick={() => setActiveTab('progress')} />
          <NavButton active={activeTab === 'profile'} icon={<Settings />} onClick={() => setActiveTab('profile')} />
        </nav>
      </div>
    </div>
  );
};

