            <span className="text-[11px] font-black text-emerald-800 uppercase tracking-widest">Biological OS</span>
          </div>

          <p className="text-emerald-900/60 text-lg font-bold max-w-[260px] leading-relaxed">
            Neural coaching tailored to your metabolic footprint.
          </p>
        </div>

        <div className="relative z-10 space-y-4 pb-10">
          <button 
            onClick={() => setStep(0)}
