          </button>

          <button 
            onClick={onSkipAll}
            className="w-full py-4 liquid-glass rounded-2xl text-emerald-800/50 font-black text-xs uppercase tracking-[0.2em] hover:bg-white/80 transition-all border-white/60"
          >
            Quick Guest Login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f0fdf4] flex flex-col p-6 animate-in fade-in duration-700 relative overflow-hidden">
      <div className="blob blob-3"></div>

      <div className="flex justify-between items-center mb-10 pt-4 relative z-10">
        <div className="flex gap-2 flex-1 max-w-[200px]">
          {[0,1,2,3,4].map((i) => (
            <div key={i} className={`h-1.5 flex-1 rounded-full transition-all duration-700 ${i <= step ? 'theme-bg shadow-sm' : 'bg-emerald-100'}`} />
          ))}
        </div>
      </div>

      <div className="flex-1 relative z-10">
        {step === 0 && (
          <div className="space-y-6 animate-in slide-in-from-bottom-6 duration-500">
            <h1 className="text-4xl font-black text-[#064e3b] mb-2 tracking-tight">Identity Token</h1>
            <div className="liquid-glass p-10 rounded-[40px] border-white/80 shadow-sm">
                <input 
                  type="text" 
                  autoFocus
                  value={profile.name} 
                  placeholder="Enter Name..."
                  onChange={(e) => setProfile({ ...profile, name: e.target.value })}
                  className="w-full bg-emerald-50/30 border-2 border-transparent focus:theme-border focus:bg-white rounded-[24px] py-6 px-8 font-black text-2xl text-emerald-900 outline-none transition-all placeholder:text-emerald-100 shadow-inner"
                />
            </div>
            <button onClick={() => setStep(1)} disabled={!profile.name.trim()} className="w-full py-6 gradient-bg text-white font-black text-lg rounded-[32px] shadow-2xl theme-glow flex items-center justify-center gap-3 active:scale-95 transition-all disabled:opacity-50">Continue Sequence <ChevronRight className="w-6 h-6"/></button>
          </div>
        )}

        {step === 1 && (
          <div className="space-y-4 animate-in slide-in-from-bottom-6 duration-500">
