                 <h1 className="text-4xl font-black text-[#064e3b] mb-2 tracking-tight">AI Protocol</h1>
                 <p className="theme-text font-black text-xs uppercase tracking-widest">{goalPlan.title}</p>
              </div>
              <div className="liquid-glass p-8 rounded-[40px] border-white/80">
                 <p className="text-emerald-900 font-bold text-lg leading-snug italic">"{goalPlan.summary}"</p>
              </div>
              <button onClick={() => onComplete({ ...profile, goalSheet: goalPlan })} className="w-full py-6 gradient-bg text-white font-black text-xl rounded-[32px] shadow-2xl theme-glow active:scale-95 transition-all">Engage OS</button>
           </div>
        )}
      </div>

      {step >= 1 && step < 5 && (
        <div className="fixed bottom-10 left-6 right-6 flex gap-4">
           <button onClick={() => setStep(step - 1)} className="p-6 liquid-glass rounded-3xl text-emerald-800 border-white/60 active:scale-90 transition-all"><ArrowLeft className="w-6 h-6"/></button>
           {step < 4 ? (
             <button onClick={() => setStep(step + 1)} className="flex-1 py-6 gradient-bg text-white font-black text-lg rounded-[32px] shadow-2xl active:scale-95 transition-all">Continue</button>
