import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart2, 
  User, 
  Camera, 
  Plus, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer,
  Sparkles,
  Search,
  CheckCircle2,
  Clock,
  X,
  Zap,
  ChefHat,
  Moon,
  Sun
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import Recipes from './pages/Recipes';
import Onboarding from './pages/Onboarding';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry, UserProfile, AppTheme } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [isOnboarded, setIsOnboarded] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [theme, setTheme] = useState<AppTheme>('emerald');
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [stats, setStats] = useState<DailyStats>({
    calories: 0,
    caloriesGoal: 2000,
    water: 0,
    waterGoal: 2.5, 
    steps: 0,
    stepsGoal: 10000,
    exercise: 0,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  useEffect(() => {
    document.documentElement.setAttribute('data-mode', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const handleOnboardingComplete = (profile: UserProfile) => {
    let baseCals = 1800;
    if (profile.goal === 'loss') baseCals = 1600;
    if (profile.goal === 'gain') baseCals = 2400;
    if (profile.goal === 'maintain') baseCals = 2000;

    const activityMult = profile.activityLevel === 'active' ? 1.4 : profile.activityLevel === 'moderate' ? 1.2 : 1.0;
    const finalCals = Math.round(baseCals * activityMult);

    setUserProfile(profile);
    setStats(prev => ({
      ...prev,
      caloriesGoal: finalCals,
      waterGoal: 2.5 
    }));
    setIsOnboarded(true);
  };

  const handleSkipAll = () => {
    const guestProfile: UserProfile = {
      name: 'Fred',
      goal: 'maintain',
      weight: 70,
      height: 175,
      age: 25,
      activityLevel: 'moderate',
      isGuest: true,
      unitSystem: 'metric'
    };
    setUserProfile(guestProfile);
    setIsOnboarded(true);
  };

  const handleAuthChange = (authData: { provider: any, email?: string }) => {
    if (userProfile) {
      setUserProfile({
        ...userProfile,
        isGuest: false,
        authProvider: authData.provider,
        email: authData.email
      });
    }
  };

  const handleAddWater = (amount: number = 0.25) => {
    setStats(prev => ({ ...prev, water: parseFloat((prev.water + amount).toFixed(2)) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleAddSteps = (amount: number) => {
    setStats(prev => ({ ...prev, steps: prev.steps + amount }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      } else {
        alert("Neural match failed. Please provide a clearer visual of the intake.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const confirmPendingFood = () => {
    if (pendingFood) {
      handleAddFood(pendingFood.name, pendingFood.calories);
      setPendingFood(null);
    }
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={handleSkipAll} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen flex flex-col relative pb-32 overflow-hidden shadow-2xl transition-colors duration-400" data-theme={theme} data-mode={isDarkMode ? 'dark' : 'light'}>
