      <div className="blob blob-2"></div>
      <div className="blob blob-3"></div>

      {/* Header */}
      <header className="p-6 pt-10 flex justify-between items-center z-10">
        <div>
          <h2 className="text-[10px] font-black theme-text uppercase tracking-[0.4em] mb-1">Neural Core Active</h2>
          <h1 className="text-4xl font-black text-[#064e3b] dark:text-white tracking-tighter">Hi, {userProfile?.name}</h1>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-4 liquid-glass rounded-2xl transition-all active:scale-90 shadow-lg">
            {isDarkMode ? <Sun className="w-5 h-5 text-amber-400" /> : <Moon className="w-5 h-5 text-[#064e3b]" />}
          </button>
          <button className="p-4 liquid-glass rounded-2xl transition-all active:scale-90 shadow-lg" onClick={() => setActiveTab('profile')}>
            <User className="w-5 h-5 text-[#064e3b] dark:text-white" />
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 px-6 z-10 no-scrollbar overflow-y-auto">
        {activeTab === 'dashboard' && <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />}
        {activeTab === 'journal' && <Journal stats={stats} foodLog={foodLog} exerciseLog={exerciseLog} onAddWater={() => handleAddWater(0.25)} onAddFood={handleAddFood} onAddExercise={handleAddExercise} />}
        {activeTab === 'recipes' && <Recipes profile={userProfile} stats={stats} />}
        {activeTab === 'progress' && <Progress stats={stats} />}
        {activeTab === 'profile' && <Profile profile={userProfile} onAuthConversion={handleAuthChange} currentTheme={theme} onThemeChange={setTheme} isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} />}
      </main>

      {/* High-Contrast FAB */}
      <div className="fixed bottom-32 right-8 z-20">
        <label className="cursor-pointer">
          <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} disabled={isScanning} />
          <div className="p-7 gradient-bg rounded-[40px] shadow-2xl text-white transition-all transform active:scale-75 hover:scale-110 theme-glow pulse-ring">
            <Camera className="w-8 h-8" />
          </div>
        </label>
      </div>

      {/* Scanning Modal */}
      {isScanning && (
        <div className="fixed inset-0 bg-[#f0fdf4]/80 dark:bg-black/80 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center animate-in fade-in duration-500">
