           <h3 className="mt-12 text-3xl font-black text-[#064e3b] dark:text-white tracking-tighter">AI Synthesizing...</h3>
           <p className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.3em] mt-4">Molecular Analysis in Progress</p>
        </div>
      )}

      {/* AI Confirm Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-xl z-[110] flex items-center justify-center p-8 animate-in fade-in zoom-in duration-300">
          <div className="liquid-glass w-full rounded-[48px] p-12 shadow-2xl relative overflow-hidden text-center border-white/80">
            <button onClick={() => setPendingFood(null)} className="absolute top-8 right-8 p-3 bg-black/5 rounded-full"><X className="w-5 h-5 text-gray-400" /></button>
            <div className="w-24 h-24 theme-bg rounded-[32px] flex items-center justify-center text-white mb-8 mx-auto theme-glow border-4 border-white">
              <Utensils className="w-10 h-10" />
            </div>
            <h3 className="text-4xl font-black text-[#064e3b] dark:text-white mb-4 tracking-tighter">{pendingFood.name}</h3>
            <div className="bg-white/90 border-2 border-[#064e3b]/10 rounded-[40px] py-8 mb-10 shadow-inner">
               <span className="text-6xl font-black text-[#064e3b] tracking-tighter">{pendingFood.calories}</span>
               <span className="ml-2 text-xs font-black uppercase tracking-widest text-emerald-600">kcal</span>
            </div>
            <button onClick={confirmPendingFood} className="w-full py-6 gradient-bg text-white font-black rounded-3xl shadow-xl active:scale-95 uppercase tracking-widest text-sm">Sync to Records</button>
