  const [logVal, setLogVal] = useState('');

  const handleManualAdd = () => {
    if (!logVal) return;
    if (activeSubTab === 'food') {
      onAddFood(logName || 'Bio Fuel', parseInt(logVal));
    } else if (activeSubTab === 'exercise') {
      onAddExercise(logName || 'Kinetic Burn', parseInt(logVal));
    }
    setLogName('');
    setLogVal('');
    setShowLogModal(false);
