        <SubTab active={activeSubTab === 'exercise'} label="Burn" icon={<Activity className="w-4 h-4" />} onClick={() => setActiveSubTab('exercise')} />
        <SubTab active={activeSubTab === 'water'} label="Fluid" icon={<Droplets className="w-4 h-4" />} onClick={() => setActiveSubTab('water')} />
