          </div>
        )}
      </div>

      {/* Manual Input Modal */}
      {showLogModal && (
        <div className="fixed inset-0 z-[150] flex items-end justify-center p-6 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-emerald-950/70 backdrop-blur-xl" onClick={() => setShowLogModal(false)} />
          <div className="bg-white dark:bg-emerald-950 w-full max-w-sm rounded-[56px] p-12 shadow-2xl relative animate-in slide-in-from-bottom-12 border-4 border-white/10">
            <button onClick={() => setShowLogModal(false)} className="absolute top-10 right-10 p-3 bg-emerald-50 dark:bg-white/10 rounded-full text-emerald-800"><X className="w-6 h-6" /></button>
