    stepsGoal: 10000,
    exercise: 0,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  // Sync dark mode state with HTML element
  useEffect(() => {
    document.documentElement.setAttribute('data-mode', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const handleOnboardingComplete = (profile: UserProfile) => {
    let baseCals = 1800;
    if (profile.goal === 'loss') baseCals = 1600;
    if (profile.goal === 'gain') baseCals = 2400;
    if (profile.goal === 'maintain') baseCals = 2000;

    const activityMult = profile.activityLevel === 'active' ? 1.4 : profile.activityLevel === 'moderate' ? 1.2 : 1.0;
    const finalCals = Math.round(baseCals * activityMult);

    setUserProfile(profile);
    setStats(prev => ({
      ...prev,
      caloriesGoal: finalCals
    }));
    setIsOnboarded(true);
  };

  const handleSkipAll = () => {
    const guestProfile: UserProfile = {
      name: 'Fred',
      goal: 'maintain',
      weight: 70,
      height: 175,
      age: 25,
      activityLevel: 'moderate',
      isGuest: true,
      unitSystem: 'metric'
    };
    setUserProfile(guestProfile);
    setIsOnboarded(true);
  };

  const handleAuthChange = (authData: { provider: any, email?: string }) => {
    if (userProfile) {
      setUserProfile({
        ...userProfile,
        isGuest: false,
        authProvider: authData.provider,
        email: authData.email
      });
    }
  };

  const handleAddWater = (amount: number = 1) => {
    setStats(prev => ({ ...prev, water: Math.min(prev.water + amount, prev.waterGoal * 2) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleAddSteps = (amount: number) => {
    setStats(prev => ({ ...prev, steps: prev.steps + amount }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      } else {
        alert("Sorry, couldn't identify the food. Please try again.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const confirmPendingFood = () => {
    if (pendingFood) {
      handleAddFood(pendingFood.name, pendingFood.calories);
      setPendingFood(null);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            stats={stats} 
            profile={userProfile} 
            onAddFood={handleAddFood}
            onAddWater={handleAddWater}
            onAddSteps={handleAddSteps}
            onAddExercise={handleAddExercise}
          />
        );
      case 'journal':
        return (
          <Journal 
            stats={stats} 
            foodLog={foodLog} 
            exerciseLog={exerciseLog}
            onAddWater={() => handleAddWater(1)}
            onAddFood={handleAddFood}
            onAddExercise={handleAddExercise}
          />
        );
      case 'recipes':
        return <Recipes profile={userProfile} />;
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return <Profile profile={userProfile} onAuthConversion={handleAuthChange} currentTheme={theme} onThemeChange={setTheme} isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} />;
      default:
        return <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />;
    }
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={handleSkipAll} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen flex flex-col relative pb-32 overflow-hidden shadow-2xl transition-colors duration-400">

      {/* Background Neural Blobs */}
      <div className="blob blob-1"></div>
      <div className="blob blob-2"></div>
      <div className="blob blob-3"></div>

      {/* Header */}
      <header className="p-6 pt-10 flex justify-between items-center z-10">
        <div>
          <h2 className="text-[10px] font-black theme-text uppercase tracking-[0.4em] mb-1">Neural Core Active</h2>
          <h1 className="text-4xl font-black text-gray-900 dark:text-white tracking-tighter">Hi, {userProfile?.name}</h1>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className="p-4 liquid-glass rounded-2xl transition-all active:scale-90 shadow-lg text-gray-600 dark:text-white"
          >
            {isDarkMode ? <Sun className="w-5 h-5 text-amber-400" /> : <Moon className="w-5 h-5" />}
          </button>
          <button className="p-4 liquid-glass rounded-2xl transition-all active:scale-90 shadow-lg" onClick={() => setActiveTab('profile')}>
            <User className="w-5 h-5 text-gray-600 dark:text-white" />
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 px-6 z-10 no-scrollbar overflow-y-auto">
        {renderContent()}
      </main>

      {/* Floating Action Button (Camera) */}
      <div className="fixed bottom-32 right-8 z-20">
        <label className="cursor-pointer">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            onChange={handleImageUpload}
            disabled={isScanning}
          />
          <div className={`p-7 gradient-bg rounded-[40px] shadow-2xl text-white transition-all transform active:scale-75 hover:scale-110 theme-glow ${isScanning ? 'opacity-50' : ''}`}>
            {isScanning ? <Clock className="w-8 h-8 animate-spin" /> : <Camera className="w-8 h-8" />}
          </div>
        </label>
      </div>

      {/* AI Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/80 dark:bg-black/80 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center animate-in fade-in duration-500">
          <div className="relative">
            <div className="w-32 h-32 border-[6px] theme-light-bg theme-border rounded-full animate-spin border-t-transparent"></div>
            <Sparkles className="w-12 h-12 theme-text absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
          </div>
          <h3 className="mt-12 text-3xl font-black text-gray-900 dark:text-white tracking-tighter uppercase">Analyzing Intake</h3>
          <p className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.3em] mt-4">Molecular Synthesis in Progress</p>
        </div>
      )}

      {/* Confirmation Modal - Styled for Mode support */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-xl z-[110] flex items-center justify-center p-8 animate-in fade-in zoom-in duration-300">
          <div className="liquid-glass w-full rounded-[48px] p-12 shadow-2xl relative overflow-hidden text-center border-white/80">
            <button 
              onClick={() => setPendingFood(null)}
              className="absolute top-8 right-8 p-3 bg-black/5 dark:bg-white/10 rounded-full transition-colors"
            >
              <X className="w-5 h-5 text-gray-400" />
            </button>

            <div className="flex flex-col items-center">
              <div className="w-24 h-24 theme-light-bg rounded-[32px] flex items-center justify-center mb-8 transform -rotate-3 shadow-inner">
                <Utensils className="w-12 h-12 theme-text" />
              </div>

              <div className="flex items-center gap-2 mb-2">
                <Zap className="w-4 h-4 text-emerald-500 fill-emerald-500" />
                <span className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.3em]">AI Synthesis Result</span>
              </div>

              <h3 className="text-4xl font-black text-gray-900 dark:text-white mb-4 tracking-tighter">{pendingFood.name}</h3>

              <div className="bg-emerald-50/50 dark:bg-emerald-900/20 rounded-[40px] px-10 py-8 mb-10 shadow-inner w-full">
                <span className="text-6xl font-black theme-text tracking-tighter">{pendingFood.calories}</span>
                <span className="ml-2 text-xs font-black theme-text opacity-70 uppercase tracking-widest">kcal</span>
              </div>

              <div className="grid grid-cols-2 gap-4 w-full">
                <button 
                  onClick={() => setPendingFood(null)}
                  className="py-5 rounded-3xl bg-gray-50 dark:bg-white/5 text-gray-400 font-black text-xs uppercase tracking-widest hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"
                >
                  Discard
                </button>
                <button 
                  onClick={confirmPendingFood}
                  className="py-5 rounded-3xl gradient-bg text-white font-black text-xs uppercase tracking-widest shadow-xl theme-glow active:scale-95 transition-all flex items-center justify-center gap-2"
                >
                  <Plus className="w-5 h-5" /> Sync Log
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Dock */}
      <div className="fixed bottom-10 left-6 right-6 max-w-sm mx-auto z-20">
        <nav className="liquid-glass p-2.5 flex justify-between items-center shadow-2xl">
          <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} label="Ops" onClick={() => setActiveTab('dashboard')} />
          <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} label="Chef" onClick={() => setActiveTab('recipes')} />
          <NavButton active={activeTab === 'journal'} icon={<Calendar />} label="Diary" onClick={() => setActiveTab('journal')} />
          <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Trends" onClick={() => setActiveTab('progress')} />
          <NavButton active={activeTab === 'profile'} icon={<User />} label="Me" onClick={() => setActiveTab('profile')} />
        </nav>
      </div>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

const NavButton: React.FC<NavButtonProps> = ({ active, icon, label, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col items-center gap-1.5 py-4 transition-all rounded-[24px] ${active ? 'nav-pill-active' : 'text-gray-400 hover:text-emerald-700'}`}
  >
    {React.cloneElement(icon as React.ReactElement, { className: 'w-5 h-5' })}
    <span className="text-[9px] font-black uppercase tracking-[0.2em]">{label}</span>
  </button>
);

export default App;

