        <SubTab active={activeSubTab === 'water'} label="Hydrate" icon={<Droplets className="w-4 h-4" />} onClick={() => setActiveSubTab('water')} />
      </div>

      <div className="space-y-4">
        {activeSubTab === 'food' && (
          <div className="space-y-3">
