                title={entry.title} 
                val={`${entry.duration} min`} 
                time={entry.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} 
                icon={<Timer className="w-5 h-5" />} 
                color="#A3D139" 
                bg="bg-lime-100/30 dark:bg-lime-900/30"
              />
            ))}
            {exerciseLog.length === 0 && <EmptyState message="No kinetic output recorded" />}
          </div>
        )}

        {activeSubTab === 'water' && (
          <div className="liquid-glass p-12 flex flex-col items-center gap-10 text-center border-white/60">
             <div className="w-48 h-48 rounded-full border-[10px] border-emerald-50 dark:border-emerald-900/20 flex flex-col items-center justify-center relative overflow-hidden shadow-inner">
               <div className="absolute bottom-0 left-0 right-0 bg-[#5DC6F1] opacity-20 transition-all duration-1000" style={{ height: `${Math.min(100, (stats.water/stats.waterGoal)*100)}%` }}></div>
               <div className="relative z-10 flex flex-col items-center">
                 <Droplets className="w-12 h-12 text-[#5DC6F1] mb-2" />
                 <span className="text-5xl font-black text-gray-900 dark:text-white tracking-tighter">{stats.water.toFixed(2)}</span>
                 <span className="text-[10px] font-black text-gray-400 dark:text-emerald-700/50 uppercase tracking-widest mt-1">/ {stats.waterGoal}L Target</span>
               </div>
             </div>
             <button 
              onClick={onAddWater} 
              className="w-full py-6 bg-[#5DC6F1] text-white font-black rounded-3xl shadow-xl active:scale-95 transition-all uppercase tracking-[0.2em] text-xs"
             >
