import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart2, 
  User, 
  Camera, 
  Plus, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer,
  Sparkles,
  Search,
  CheckCircle2,
  Clock,
  X,
  Zap,
  ChefHat,
  Sun,
  Moon
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import Recipes from './pages/Recipes';
import Onboarding from './pages/Onboarding';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry, UserProfile, AppTheme } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [isOnboarded, setIsOnboarded] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [theme, setTheme] = useState<AppTheme>('emerald');
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [stats, setStats] = useState<DailyStats>({
    calories: 0,
    caloriesGoal: 2000,
    water: 0,
    waterGoal: 2.5, 
    steps: 0,
    stepsGoal: 10000,
    exercise: 0,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  useEffect(() => {
    document.documentElement.setAttribute('data-mode', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const handleOnboardingComplete = (profile: UserProfile) => {
    let baseCals = 1800;
    if (profile.goal === 'loss') baseCals = 1600;
    if (profile.goal === 'gain') baseCals = 2400;
    if (profile.goal === 'maintain') baseCals = 2000;

    const activityMult = profile.activityLevel === 'active' ? 1.4 : profile.activityLevel === 'moderate' ? 1.2 : 1.0;
    const finalCals = Math.round(baseCals * activityMult);

    setUserProfile(profile);
    setStats(prev => ({
      ...prev,
      caloriesGoal: finalCals,
      waterGoal: 2.5 
    }));
    setIsOnboarded(true);
  };

  const handleSkipAll = () => {
    const guestProfile: UserProfile = {
      name: 'Friend',
      goal: 'maintain',
      weight: 70,
      height: 175,
      age: 25,
      activityLevel: 'moderate',
      isGuest: true,
      unitSystem: 'metric'
    };
    setUserProfile(guestProfile);
    setIsOnboarded(true);
  };

  const handleAuthChange = (authData: { provider: any, email?: string }) => {
    if (userProfile) {
      setUserProfile({
        ...userProfile,
        isGuest: false,
        authProvider: authData.provider,
        email: authData.email
      });
    }
  };

  const handleAddWater = (amount: number = 0.25) => {
    setStats(prev => ({ ...prev, water: parseFloat((prev.water + amount).toFixed(2)) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleAddSteps = (amount: number) => {
    setStats(prev => ({ ...prev, steps: prev.steps + amount }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      } else {
        alert("Sorry, couldn't identify the food. Please try again.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const confirmPendingFood = () => {
    if (pendingFood) {
      handleAddFood(pendingFood.name, pendingFood.calories);
      setPendingFood(null);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            stats={stats} 
            profile={userProfile} 
            onAddFood={handleAddFood}
            onAddWater={handleAddWater}
            onAddSteps={handleAddSteps}
            onAddExercise={handleAddExercise}
          />
        );
      case 'journal':
        return (
          <Journal 
            stats={stats} 
            foodLog={foodLog} 
            exerciseLog={exerciseLog}
            onAddWater={() => handleAddWater(0.25)}
            onAddFood={handleAddFood}
            onAddExercise={handleAddExercise}
          />
        );
      case 'recipes':
        return <Recipes profile={userProfile} stats={stats} />;
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return (
          <Profile 
            profile={userProfile} 
            onAuthConversion={handleAuthChange} 
            currentTheme={theme} 
            onThemeChange={setTheme}
            isDarkMode={isDarkMode}
            onToggleDarkMode={() => setIsDarkMode(!isDarkMode)}
          />
        );
      default:
        return <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />;
    }
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={handleSkipAll} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen flex flex-col relative pb-32 overflow-hidden shadow-2xl transition-colors duration-400">

      {/* Header */}
      <header className="p-6 pt-10 flex justify-between items-center z-10">
        <div>
          <h2 className="text-[10px] font-black theme-text uppercase tracking-[0.4em] mb-1">Biological Core</h2>
          <h1 className="text-4xl font-black text-[#064e3b] dark:text-white tracking-tighter">Hi, {userProfile?.name}</h1>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsDarkMode(!isDarkMode)}
            className="p-4 solid-card flex items-center justify-center transition-all active:scale-90"
          >
            {isDarkMode ? <Sun className="w-5 h-5 text-amber-400" /> : <Moon className="w-5 h-5 text-[#064e3b]" />}
          </button>
          <button 
            className="p-4 solid-card flex items-center justify-center transition-all active:scale-90" 
            onClick={() => setActiveTab('profile')}
          >
            <User className="w-5 h-5 text-[#064e3b] dark:text-white" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 px-6 z-10 no-scrollbar overflow-y-auto">
        {renderContent()}
      </main>

      {/* Floating Action Button */}
      <div className="fixed bottom-32 right-8 z-20">
        <label className="cursor-pointer">
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            onChange={handleImageUpload}
            disabled={isScanning}
          />
          <div className={`p-7 gradient-bg rounded-3xl shadow-xl text-white transition-all transform active:scale-75 hover:scale-110 flex items-center justify-center ${isScanning ? 'opacity-50' : ''}`}>
            {isScanning ? <Clock className="w-8 h-8 animate-spin" /> : <Camera className="w-8 h-8" />}
          </div>
        </label>
      </div>

      {/* AI Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/95 dark:bg-[#022c22]/95 z-[100] flex flex-col items-center justify-center animate-in fade-in duration-300">
          <div className="relative w-48 h-48 border-4 border-[#064e3b]/10 rounded-3xl flex items-center justify-center overflow-hidden scanner">
            <Sparkles className="w-16 h-16 theme-text animate-pulse" />
          </div>
          <h3 className="mt-10 text-3xl font-black text-[#064e3b] dark:text-white tracking-tighter">Neural Scan Active</h3>
          <p className="text-xs font-black text-emerald-600 uppercase tracking-[0.3em] mt-3">Synthesizing Nutritional Profile</p>
        </div>
      )}

      {/* AI Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/60 z-[110] flex items-center justify-center p-8 animate-in fade-in duration-200">
          <div className="solid-card w-full p-10 relative overflow-hidden">
            <button 
              onClick={() => setPendingFood(null)}
              className="absolute top-8 right-8 p-2 text-gray-400 hover:text-red-500"
            >
              <X className="w-6 h-6" />
            </button>

            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 theme-bg rounded-3xl flex items-center justify-center mb-6 text-white">
                <Utensils className="w-10 h-10" />
              </div>

              <h3 className="text-3xl font-black text-[#064e3b] dark:text-white mb-2 tracking-tight">{pendingFood.name}</h3>

              <div className="bg-[#f0fdf4] dark:bg-[#022c22] border-2 border-[#064e3b]/10 rounded-2xl px-10 py-6 mb-8 w-full">
                <span className="text-5xl font-black theme-text tracking-tighter">{pendingFood.calories}</span>
                <span className="ml-2 text-sm font-black theme-text opacity-50 uppercase">kcal</span>
              </div>

              <div className="grid grid-cols-2 gap-4 w-full">
                <button 
                  onClick={() => setPendingFood(null)}
                  className="py-4 rounded-2xl bg-gray-100 dark:bg-emerald-900/50 text-gray-500 dark:text-emerald-50 font-black text-xs uppercase tracking-widest"
                >
                  Discard
                </button>
                <button 
                  onClick={confirmPendingFood}
                  className="py-4 rounded-2xl gradient-bg text-white font-black text-xs uppercase tracking-widest shadow-lg active:scale-95"
                >
                  Commit Log
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Dock */}
      <div className="fixed bottom-10 left-6 right-6 max-w-sm mx-auto z-20">
        <nav className="solid-card p-2.5 flex justify-between items-center shadow-xl">
          <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} label="Ops" onClick={() => setActiveTab('dashboard')} />
          <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} label="Chef" onClick={() => setActiveTab('recipes')} />
          <NavButton active={activeTab === 'journal'} icon={<Calendar />} label="Log" onClick={() => setActiveTab('journal')} />
          <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Stats" onClick={() => setActiveTab('progress')} />
          <NavButton active={activeTab === 'profile'} icon={<User />} label="Me" onClick={() => setActiveTab('profile')} />
        </nav>
      </div>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

const NavButton: React.FC<NavButtonProps> = ({ active, icon, label, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col items-center gap-1.5 py-4 transition-all rounded-2xl ${active ? 'nav-pill-active' : 'text-gray-400 hover:text-[#064e3b] dark:hover:text-emerald-400'}`}
