    if (activeSubTab === 'food') {
      onAddFood(logName || 'Bio Fuel', parseInt(logVal));
    } else if (activeSubTab === 'exercise') {
      onAddExercise(logName || 'Kinetic Load', parseInt(logVal));
    }
    setLogName('');
    setLogVal('');
    setShowLogModal(false);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-28">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-[10px] font-black theme-text uppercase tracking-[0.3em]">Log Protocol</h2>
          <h1 className="text-3xl font-black text-[#064e3b] dark:text-white tracking-tight">Biological Diary</h1>
        </div>
        <button onClick={() => setShowLogModal(true)} className="w-12 h-12 theme-bg rounded-xl flex items-center justify-center text-white shadow-md active:scale-90 transition-all">
          <PlusCircle className="w-6 h-6" />
        </button>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 p-1.5 solid-card">
        <SubTab active={activeSubTab === 'food'} label="Fuel" icon={<Flame className="w-4 h-4" />} onClick={() => setActiveSubTab('food')} />
        <SubTab active={activeSubTab === 'exercise'} label="Burn" icon={<Activity className="w-4 h-4" />} onClick={() => setActiveSubTab('exercise')} />
        <SubTab active={activeSubTab === 'water'} label="Hydrate" icon={<Droplets className="w-4 h-4" />} onClick={() => setActiveSubTab('water')} />
      </div>

      <div className="space-y-4">
        {activeSubTab === 'food' && (
          <div className="space-y-3">
            {foodLog.map((entry) => (
              <LogItem 
                key={entry.id} 
                title={entry.name} 
                val={`${entry.calories} kcal`} 
                time={entry.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} 
                icon={<Utensils className="w-5 h-5" />} 
                color="#059669" 
                bg="bg-emerald-50 dark:bg-[#022c22]"
              />
            ))}
            {foodLog.length === 0 && <EmptyState message="Caloric logs pending intake" />}
          </div>
        )}

        {activeSubTab === 'exercise' && (
          <div className="space-y-3">
            {exerciseLog.map((entry) => (
              <LogItem 
                key={entry.id} 
                title={entry.title} 
                val={`${entry.duration} min`} 
                time={entry.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} 
                icon={<Timer className="w-5 h-5" />} 
                color="#A3D139" 
                bg="bg-lime-50 dark:bg-[#022c22]"
              />
            ))}
            {exerciseLog.length === 0 && <EmptyState message="Kinetic reports waiting for motion" />}
          </div>
        )}

        {activeSubTab === 'water' && (
          <div className="solid-card p-12 flex flex-col items-center gap-10 text-center">
             <div className="w-48 h-48 rounded-3xl border-4 border-emerald-50 dark:border-emerald-900/50 flex flex-col items-center justify-center relative overflow-hidden bg-white dark:bg-[#022c22]">
               <div className="absolute bottom-0 left-0 right-0 bg-blue-500 opacity-10 transition-all duration-1000" style={{ height: `${Math.min(100, (stats.water/stats.waterGoal)*100)}%` }}></div>
               <div className="relative z-10 flex flex-col items-center">
                 <Droplets className="w-12 h-12 text-blue-500 mb-2" />
                 <span className="text-5xl font-black text-[#064e3b] dark:text-white tracking-tighter">{stats.water.toFixed(2)}</span>
                 <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">/ {stats.waterGoal}L Target</span>
               </div>
             </div>
             <button 
