             >
              Hydrate 250ml
             </button>
          </div>
        )}
      </div>

      {/* Manual Input Modal */}
      {showLogModal && (
        <div className="fixed inset-0 z-[150] flex items-end justify-center p-6 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60" onClick={() => setShowLogModal(false)} />
          <div className="solid-card w-full max-w-sm p-10 relative animate-in slide-in-from-bottom-10">
            <button onClick={() => setShowLogModal(false)} className="absolute top-8 right-8 p-2 text-gray-400">
              <X className="w-6 h-6" />
