import React, { useState } from 'react';
import { ChefHat, Plus, X, Sparkles, Clock, Utensils, ChevronDown, ChevronUp, RefreshCw, Zap, Flame } from 'lucide-react';
import { getRecipeRecommendations } from '../services/geminiService';
import { Recipe, UserProfile, DailyStats } from '../types';

interface Props {
  profile: UserProfile | null;
  stats: DailyStats;
}

const Recipes: React.FC<Props> = ({ profile, stats }) => {
  const [ingredients, setIngredients] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const addIngredient = () => {
    if (inputValue.trim() && !ingredients.includes(inputValue.trim())) {
      setIngredients([...ingredients, inputValue.trim()]);
      setInputValue('');
    }
  };

  const removeIngredient = (ingredient: string) => {
    setIngredients(ingredients.filter(i => i !== ingredient));
  };

  const findRecipes = async () => {
    if (ingredients.length === 0) return;
    setIsLoading(true);
    const results = await getRecipeRecommendations(ingredients, profile);
    setRecipes(results);
    setIsLoading(false);
  };

  const remainingKcal = stats.caloriesGoal - stats.calories;

  return (
    <div className="space-y-6 pb-28 animate-in fade-in duration-500">
      <div className="flex justify-between items-end mb-4">
        <div>
          <h1 className="text-3xl font-black text-[#064e3b] dark:text-white tracking-tighter">AI Chef</h1>
          <p className="text-[10px] font-black theme-text uppercase tracking-[0.3em] mt-1">Culinary Analysis</p>
        </div>
        <div className="px-4 py-2 bg-emerald-50 dark:bg-emerald-900/30 rounded-xl flex items-center gap-2 border border-emerald-500/20">
           <Flame className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
           <span className="text-[10px] font-black text-emerald-700 dark:text-emerald-200 uppercase tracking-widest">{remainingKcal > 0 ? `${remainingKcal} kcal Rem` : 'Limit Hit'}</span>
        </div>
      </div>

      <div className="solid-card p-8">
        <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] mb-4 block">Available Assets</label>

        <div className="flex flex-wrap gap-2 mb-6 min-h-[40px]">
          {ingredients.map(ing => (
            <span key={ing} className="bg-emerald-50 dark:bg-[#022c22] px-4 py-2 rounded-xl text-[10px] font-black theme-text uppercase tracking-widest flex items-center gap-2 border border-emerald-500/20">
              {ing}
              <button onClick={() => removeIngredient(ing)} className="text-gray-400 hover:text-red-500">
                <X className="w-3.5 h-3.5" />
              </button>
            </span>
          ))}
          {ingredients.length === 0 && (
            <p className="text-[11px] text-gray-400 font-bold italic">Inventory empty...</p>
          )}
        </div>

        <div className="flex gap-3">
          <input 
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && addIngredient()}
            placeholder="Entry name..."
            className="flex-1 bg-gray-50 dark:bg-emerald-950/50 border-2 border-transparent focus:border-[#064e3b] rounded-xl px-6 py-4 text-sm font-black outline-none"
          />
          <button 
            onClick={addIngredient}
            className="p-4 theme-bg text-white rounded-xl shadow-md active:scale-90"
          >
            <Plus className="w-6 h-6" />
          </button>
        </div>

        <button 
          onClick={findRecipes}
          disabled={ingredients.length === 0 || isLoading}
          className="w-full mt-6 py-5 gradient-bg text-white font-black rounded-2xl shadow-lg disabled:opacity-40 flex items-center justify-center gap-3 active:scale-95 uppercase tracking-[0.3em] text-xs"
        >
          {isLoading ? (
            <><RefreshCw className="w-5 h-5 animate-spin" /> Synthesizing Protocol</>
          ) : (
            <><ChefHat className="w-5 h-5" /> Generate Recommendations</>
          )}
        </button>
      </div>

      <div className="space-y-4">
        {recipes.map((recipe) => (
          <div key={recipe.id} className="solid-card p-8 overflow-hidden">
            <div className="flex justify-between items-start mb-4">
              <div>
                 <h3 className="text-xl font-black text-[#064e3b] dark:text-emerald-50 tracking-tight leading-tight">{recipe.title}</h3>
                 <div className="flex items-center gap-2 mt-1">
                    <Zap className="w-3.5 h-3.5 text-emerald-600" />
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Efficiency Optimized</p>
                 </div>
              </div>
              <div className="bg-emerald-50 dark:bg-emerald-900/40 px-4 py-2 rounded-xl border border-emerald-500/10">
                <span className="text-xs font-black theme-text">{recipe.calories} kcal</span>
              </div>
            </div>

            <p className="text-xs text-gray-500 dark:text-emerald-100/60 font-medium leading-relaxed mb-6">{recipe.description}</p>

            <div className="flex items-center gap-6 mb-6">
              <div className="flex items-center gap-2 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">
                <Clock className="w-4 h-4 theme-text" /> {recipe.prepTime}
              </div>
              <div className="flex items-center gap-2 text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">
                <Utensils className="w-4 h-4 theme-text" /> {recipe.ingredientsUsed?.length || 0} Components
              </div>
            </div>

            <button 
              onClick={() => setExpandedId(expandedId === recipe.id ? null : recipe.id)}
              className="w-full py-3 bg-gray-50 dark:bg-emerald-950/50 rounded-xl text-[9px] font-black theme-text uppercase tracking-[0.3em] flex items-center justify-center gap-2 border border-emerald-500/10"
            >
              {expandedId === recipe.id ? <>Hide Protocol <ChevronUp className="w-4 h-4" /></> : <>Access Protocol <ChevronDown className="w-4 h-4" /></>}
            </button>

            {expandedId === recipe.id && (
              <div className="mt-6 pt-6 border-t border-[#064e3b]/10 animate-in slide-in-from-top-4 duration-300">
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] mb-4">Sequence of Execution</h4>
                <div className="space-y-4">
                  {recipe.instructions.map((step, idx) => (
                    <div key={idx} className="flex gap-4">
                      <div className="w-8 h-8 theme-bg rounded-lg flex items-center justify-center text-xs font-black text-white shrink-0">
                        {idx + 1}
                      </div>
                      <p className="text-[13px] text-[#064e3b] dark:text-emerald-100/80 leading-relaxed font-bold pt-1">{step}</p>
                    </div>
                  ))}
                </div>

                {recipe.missingIngredients && recipe.missingIngredients.length > 0 && (
                  <div className="mt-6 p-4 bg-emerald-50/50 dark:bg-emerald-900/20 rounded-xl">
                    <h4 className="text-[10px] font-black text-emerald-700 dark:text-emerald-400 uppercase tracking-[0.4em] mb-3">Missing Assets</h4>
                    <div className="flex flex-wrap gap-2">
                      {recipe.missingIngredients.map(mi => (
                        <span key={mi} className="text-[9px] font-black text-emerald-800 dark:text-emerald-100 bg-white dark:bg-emerald-800 px-3 py-1.5 rounded-lg border border-emerald-200 dark:border-emerald-700 uppercase tracking-widest">
                          {mi}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}

        {!isLoading && recipes.length === 0 && (
          <div className="py-20 flex flex-col items-center text-center opacity-40">
            <Sparkles className="w-12 h-12 theme-text mb-6" />
            <h4 className="text-[#064e3b] dark:text-white font-black text-xl tracking-tighter">Kitchen Sync Waiting</h4>
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.3em] mt-2">Initialize protocol via asset entry</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Recipes;

