  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);

  useEffect(() => {
    document.documentElement.setAttribute('data-mode', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const handleOnboardingComplete = (profile: UserProfile) => {
    setUserProfile(profile);
    setIsOnboarded(true);
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result) setPendingFood(result);
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={() => setIsOnboarded(true)} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen flex flex-col relative pb-32 overflow-hidden">

      {/* Header Styled like 'Hello, Fred' */}
      <header className="px-8 pt-12 pb-6 flex justify-between items-center z-10">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center border-2 border-slate-100 shadow-sm overflow-hidden">
            <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${userProfile?.name || 'Fred'}`} alt="avatar" />
          </div>
          <div>
            <h2 className="text-sm font-semibold text-slate-400">Hello, {userProfile?.name || 'Fred'} 👋</h2>
            <h1 className="text-2xl font-black text-slate-900 dark:text-white capitalize">Dashboard</h1>
          </div>
        </div>
        <button 
          onClick={() => setIsDarkMode(!isDarkMode)}
          className="w-12 h-12 modern-card flex items-center justify-center transition-all btn-hover"
        >
          {isDarkMode ? <Sun className="w-5 h-5 text-amber-400" /> : <Moon className="w-5 h-5 text-slate-800" />}
        </button>
      </header>

      {/* Main Tab Rendering */}
      <main className="flex-1 px-8 z-10 no-scrollbar overflow-y-auto">
        {activeTab === 'dashboard' && <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={() => {}} onAddSteps={() => {}} onAddExercise={() => {}} />}
        {activeTab === 'journal' && <Journal stats={stats} foodLog={foodLog} exerciseLog={exerciseLog} onAddWater={() => {}} onAddFood={handleAddFood} onAddExercise={() => {}} />}
        {activeTab === 'recipes' && <Recipes profile={userProfile} stats={stats} />}
        {activeTab === 'progress' && <Progress stats={stats} />}
        {activeTab === 'profile' && <Profile profile={userProfile} currentTheme="emerald" onThemeChange={() => {}} isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} />}
      </main>

      {/* Floating Scan Button (Camera) */}
      <div className="fixed bottom-36 right-8 z-30">
        <label className="cursor-pointer">
          <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
          <div className="w-16 h-16 bg-slate-900 rounded-full shadow-xl flex items-center justify-center text-white btn-hover">
            <Camera className="w-7 h-7" />
          </div>
        </label>
      </div>

      {/* Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/90 z-[100] flex flex-col items-center justify-center animate-in fade-in">
          <Sparkles className="w-16 h-16 text-blue-500 animate-pulse mb-6" />
          <h3 className="text-2xl font-black text-slate-900">AI Nutrition Scan</h3>
        </div>
      )}

      {/* Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/50 z-[110] flex items-center justify-center p-8 animate-in fade-in">
          <div className="modern-card w-full p-8 text-center">
            <Utensils className="w-12 h-12 text-blue-500 mx-auto mb-4" />
            <h3 className="text-2xl font-black mb-2">{pendingFood.name}</h3>
            <div className="text-4xl font-black text-blue-600 mb-8">{pendingFood.calories} <span className="text-sm font-bold text-slate-400 uppercase">kcal</span></div>
            <div className="flex gap-4">
              <button onClick={() => setPendingFood(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl font-bold">Cancel</button>
              <button onClick={() => { handleAddFood(pendingFood.name, pendingFood.calories); setPendingFood(null); }} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-bold">Add to Log</button>
            </div>
          </div>
        </div>
      )}

      {/* Floating Navigation Dock inspired by reference */}
      <div className="fixed bottom-10 left-8 right-8 z-50">
        <nav className="nav-pill py-3 px-6 flex justify-between items-center shadow-2xl">
          <NavButton active={activeTab === 'dashboard'} icon={<Home />} onClick={() => setActiveTab('dashboard')} />
          <NavButton active={activeTab === 'recipes'} icon={<LayoutGrid />} onClick={() => setActiveTab('recipes')} />
          <NavButton active={activeTab === 'journal'} icon={<Bookmark />} onClick={() => setActiveTab('journal')} />
          <NavButton active={activeTab === 'progress'} icon={<Bell />} onClick={() => setActiveTab('progress')} />
          <NavButton active={activeTab === 'profile'} icon={<Settings />} onClick={() => setActiveTab('profile')} />
        </nav>
      </div>
    </div>
  );
};

