  <button onClick={onClick} className={`relative p-3 transition-all ${active ? 'text-slate-900' : 'text-slate-400 hover:text-white'}`}>
    {active && <div className="absolute inset-0 bg-[#A9C9EE] rounded-full -z-10 animate-in zoom-in" />}
    {React.cloneElement(icon, { className: 'w-6 h-6' })}
  </button>
);

