import React, { useState, useEffect } from 'react';
import { 
  Sparkles, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer, 
  Target, 
  RefreshCw, 
  ChevronDown, 
  ChevronUp, 
  CheckCircle2,
  TrendingUp,
  Flame,
  X,
  Plus,
  Minus
} from 'lucide-react';
import { DailyStats, UserProfile } from '../types';
import { suggestWorkout } from '../services/geminiService';

interface Props {
  stats: DailyStats;
  profile: UserProfile | null;
  onAddFood: (name: string, calories: number) => void;
  onAddWater: (amount: number) => void;
  onAddSteps: (amount: number) => void;
  onAddExercise: (title: string, duration: number) => void;
}

type GoalType = 'fuel' | 'hydrate' | 'steps' | 'burn' | null;

const Dashboard: React.FC<Props> = ({ stats, profile, onAddFood, onAddWater, onAddSteps, onAddExercise }) => {
  const [aiTip, setAiTip] = useState<string>("Initializing your Neural Coach...");
  const [isExpanded, setIsExpanded] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Quick Log Modal State
  const [activeGoal, setActiveGoal] = useState<GoalType>(null);
  const [logValue1, setLogValue1] = useState('');
  const [logValue2, setLogValue2] = useState('');

  const fetchTip = async () => {
    setIsRefreshing(true);
    try {
      const remaining = stats.exerciseGoal - stats.exercise;
      const tip = await suggestWorkout(remaining > 0 ? remaining : 15, profile);
      setAiTip(tip || "Maintain your rhythm. Every micro-habit builds your future self.");
    } catch (error) {
      setAiTip("Neural link weak. Protocol: Stay consistent and hydrated.");
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchTip();
  }, [profile]);

  const handleQuickLog = () => {
    switch (activeGoal) {
      case 'fuel':
        if (logValue1 && logValue2) onAddFood(logValue1, parseInt(logValue2));
        break;
      case 'hydrate':
        onAddWater(parseFloat(logValue1) || 0.25);
        break;
      case 'steps':
        onAddSteps(parseInt(logValue1) || 0);
        break;
      case 'burn':
        if (logValue1 && logValue2) onAddExercise(logValue1, parseInt(logValue2));
        break;
    }
    closeModal();
  };

  const openModal = (type: GoalType) => {
    setActiveGoal(type);
    setLogValue1('');
    setLogValue2('');
    if (type === 'hydrate') setLogValue1('0.25');
  };

  const closeModal = () => {
    setActiveGoal(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-12">

      {/* AI Health Coach (Top Section) */}
      <div className="modern-card p-8 bg-slate-900 text-white relative overflow-hidden group shadow-2xl">
        <div className="absolute -top-12 -right-12 w-40 h-40 bg-blue-500/10 rounded-full blur-3xl group-hover:bg-blue-500/20 transition-all duration-700" />

        <div className="flex items-start gap-5 relative z-10">
          <div className={`p-4 bg-blue-500/20 rounded-2xl ${isRefreshing ? 'animate-pulse' : ''}`}>
             <Sparkles className="w-6 h-6 text-blue-400" />
          </div>
          <div className="flex-1">
            <div className="flex justify-between items-center mb-2">
              <h3 className="text-[10px] font-black text-blue-400 uppercase tracking-[0.4em]">AI Health Coach</h3>
              <button onClick={fetchTip} className="p-1 text-slate-500 hover:text-white transition-colors">
                <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
              </button>
            </div>

            <div className={`text-base font-medium leading-snug text-slate-100 transition-all duration-500 ${!isExpanded ? 'line-clamp-3' : ''}`}>
              {aiTip}
            </div>

            <button 
              onClick={() => setIsExpanded(!isExpanded)}
              className="mt-6 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-xl text-[9px] font-black uppercase tracking-[0.2em] text-blue-400 flex items-center gap-2 transition-all"
            >
              {isExpanded ? <>Collapse <ChevronUp className="w-3 h-3" /></> : <>Neural Insights <ChevronDown className="w-3 h-3" /></>}
            </button>
          </div>
        </div>
      </div>

      {/* Daily Goals Heading */}
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-900 tracking-tighter">Daily Goals</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mt-1">Current Protocol: {Object.values(stats).filter((v, i) => i%2===0 && v >= (Object.values(stats)[i+1] as number)).length}/4 Complete</p>
      </div>

      {/* 2x2 Goal Grid */}
      <div className="grid grid-cols-2 gap-5">
        <GridStatCard 
          icon={<Flame className="w-6 h-6" />} 
          label="Fuel" 
          value={stats.calories} 
          goal={stats.caloriesGoal} 
          unit="kcal" 
          color="orange"
          onClick={() => openModal('fuel')}
        />
        <GridStatCard 
          icon={<Droplets className="w-6 h-6" />} 
          label="Hydrate" 
          value={stats.water} 
          goal={stats.waterGoal} 
          unit="L" 
          color="blue"
          onClick={() => openModal('hydrate')}
        />
        <GridStatCard 
          icon={<Footprints className="w-6 h-6" />} 
          label="Steps" 
          value={stats.steps} 
          goal={stats.stepsGoal} 
          unit="steps" 
          color="green"
          onClick={() => openModal('steps')}
        />
        <GridStatCard 
          icon={<Timer className="w-6 h-6" />} 
          label="Burn" 
          value={stats.exercise} 
          goal={stats.exerciseGoal} 
          unit="min" 
          color="purple"
          onClick={() => openModal('burn')}
        />
      </div>

      {/* Quick Log Modal */}
      {activeGoal && (
        <div className="fixed inset-0 z-[100] flex items-end justify-center p-6 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={closeModal} />
          <div className="modern-card bg-white w-full max-w-sm p-10 relative animate-in slide-in-from-bottom-12">
            <button onClick={closeModal} className="absolute top-8 right-8 p-2 text-slate-400 hover:text-slate-600 transition-colors">
              <X className="w-6 h-6" />
            </button>
            <h3 className="text-3xl font-black text-slate-900 mb-8 tracking-tight capitalize">Log {activeGoal}</h3>
            <div className="space-y-6 mb-10 text-left">
              {(activeGoal === 'fuel' || activeGoal === 'burn') && (
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Description</label>
                  <input type="text" value={logValue1} onChange={(e) => setLogValue1(e.target.value)} placeholder="Name..." className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl py-5 px-6 font-bold text-slate-900 outline-none transition-all" />
                </div>
              )}
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Value ({activeGoal === 'fuel' ? 'kcal' : activeGoal === 'hydrate' ? 'Liters' : activeGoal === 'steps' ? 'steps' : 'minutes'})</label>
                <input type="number" value={activeGoal === 'fuel' || activeGoal === 'burn' ? logValue2 : logValue1} onChange={(e) => activeGoal === 'fuel' || activeGoal === 'burn' ? setLogValue2(e.target.value) : setLogValue1(e.target.value)} placeholder="0" className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl py-5 px-6 font-black text-slate-900 outline-none text-2xl transition-all" />
              </div>
            </div>
            <button onClick={handleQuickLog} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl shadow-xl uppercase tracking-widest text-sm active:scale-95 transition-all">Update Registry</button>
          </div>
        </div>
      )}
    </div>
  );
};

interface GridStatCardProps {
  icon: React.ReactNode;
  label: string;
  value: number;
  goal: number;
  unit: string;
  color: 'orange' | 'blue' | 'green' | 'purple';
  onClick: () => void;
}

const GridStatCard: React.FC<GridStatCardProps> = ({ icon, label, value, goal, unit, color, onClick }) => {
  const colors = {
    orange: { bg: 'bg-orange-50', text: 'text-orange-500', bar: 'bg-orange-500' },
    blue: { bg: 'bg-blue-50', text: 'text-blue-500', bar: 'bg-blue-500' },
    green: { bg: 'bg-emerald-50', text: 'text-emerald-500', bar: 'bg-emerald-500' },
    purple: { bg: 'bg-purple-50', text: 'text-purple-500', bar: 'bg-purple-500' },
  };

  const c = colors[color];
  const progress = Math.min(100, (value / goal) * 100);

  return (
    <button 
      onClick={onClick}
      className="modern-card p-6 flex flex-col items-center text-center group hover:scale-[1.02] active:scale-95 transition-all duration-300"
