const App: React.FC = () => {
  const [isOnboarded, setIsOnboarded] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  const [stats, setStats] = useState<DailyStats>({
    calories: 1290,
    caloriesGoal: 2340,
    water: 1.5,
    waterGoal: 2.5, 
    steps: 6430,
    stepsGoal: 10000,
    exercise: 15,
    exerciseGoal: 30
  });

  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);

  useEffect(() => {
    document.documentElement.setAttribute('data-mode', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  const handleOnboardingComplete = (profile: UserProfile) => {
    setUserProfile(profile);
    setIsOnboarded(true);
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleAddWater = (amount: number) => {
    setStats(prev => ({ ...prev, water: parseFloat((prev.water + amount).toFixed(2)) }));
  };

  const handleAddSteps = (amount: number) => {
    setStats(prev => ({ ...prev, steps: prev.steps + amount }));
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result) setPendingFood(result);
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  if (!isOnboarded) {
    return <Onboarding onComplete={handleOnboardingComplete} onSkipAll={() => setIsOnboarded(true)} />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen flex flex-col relative pb-32 overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors">

      {/* Header */}
      <header className="px-8 pt-12 pb-6 flex justify-between items-center z-10">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center border-2 border-slate-100 dark:border-slate-700 shadow-sm overflow-hidden">
            <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${userProfile?.name || 'Fred'}`} alt="avatar" />
          </div>
          <div>
            <h2 className="text-sm font-semibold text-slate-400">Hi, {userProfile?.name || 'Fred'} 👋</h2>
            <h1 className="text-2xl font-black text-slate-900 dark:text-white capitalize">Dashboard</h1>
          </div>
        </div>
        <button 
          onClick={() => setIsDarkMode(!isDarkMode)}
          className="w-12 h-12 modern-card flex items-center justify-center transition-all bg-white dark:bg-slate-800 dark:text-white"
        >
          {isDarkMode ? <Sun className="w-5 h-5 text-amber-400" /> : <Moon className="w-5 h-5 text-slate-800" />}
        </button>
      </header>

      {/* Main Tab Rendering */}
      <main className="flex-1 px-8 z-10 no-scrollbar overflow-y-auto">
        {activeTab === 'dashboard' && <Dashboard stats={stats} profile={userProfile} onAddFood={handleAddFood} onAddWater={handleAddWater} onAddSteps={handleAddSteps} onAddExercise={handleAddExercise} />}
        {activeTab === 'journal' && <Journal stats={stats} foodLog={foodLog} exerciseLog={exerciseLog} onAddWater={() => handleAddWater(0.25)} onAddFood={handleAddFood} onAddExercise={handleAddExercise} />}
        {activeTab === 'recipes' && <Recipes profile={userProfile} stats={stats} />}
        {activeTab === 'progress' && <Progress stats={stats} />}
        {activeTab === 'profile' && <Profile profile={userProfile} currentTheme="emerald" onThemeChange={() => {}} isDarkMode={isDarkMode} onToggleDarkMode={() => setIsDarkMode(!isDarkMode)} />}
      </main>

      {/* Floating Scan Button (Camera) */}
      <div className="fixed bottom-36 right-8 z-30">
        <label className="cursor-pointer">
          <input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} />
          <div className="w-16 h-16 bg-slate-900 rounded-full shadow-2xl flex items-center justify-center text-white active:scale-90 transition-transform">
            <Camera className="w-7 h-7" />
          </div>
        </label>
      </div>

      {/* Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/95 dark:bg-slate-950/95 z-[100] flex flex-col items-center justify-center animate-in fade-in">
          <Sparkles className="w-16 h-16 text-blue-500 animate-pulse mb-6" />
          <h3 className="text-2xl font-black text-slate-900 dark:text-white">Analyzing Intake...</h3>
        </div>
      )}

      {/* Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/50 z-[110] flex items-center justify-center p-8 animate-in fade-in">
          <div className="modern-card w-full p-8 text-center bg-white dark:bg-slate-900">
