            <div className="text-4xl font-black text-blue-600 mb-8">{pendingFood.calories} <span className="text-sm font-bold text-slate-400 uppercase">kcal</span></div>
            <div className="flex gap-4">
              <button onClick={() => setPendingFood(null)} className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 dark:text-slate-300 rounded-2xl font-bold">Discard</button>
              <button onClick={() => { handleAddFood(pendingFood.name, pendingFood.calories); setPendingFood(null); }} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-bold">Log Record</button>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Dock */}
      <div className="fixed bottom-10 left-8 right-8 z-50">
        <nav className="nav-pill py-3 px-6 flex justify-between items-center shadow-2xl bg-slate-900">
          <NavButton active={activeTab === 'dashboard'} icon={<Home />} label="Dash" onClick={() => setActiveTab('dashboard')} />
          <NavButton active={activeTab === 'journal'} icon={<Bookmark />} label="Journ" onClick={() => setActiveTab('journal')} />
          <NavButton active={activeTab === 'recipes'} icon={<ChefHat />} label="Recip" onClick={() => setActiveTab('recipes')} />
          <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Stats" onClick={() => setActiveTab('progress')} />
          <NavButton active={activeTab === 'profile'} icon={<Settings />} label="Me" onClick={() => setActiveTab('profile')} />
        </nav>
      </div>
    </div>
  );
};

