            <Camera className="w-7 h-7" />
          </div>
        </label>
      </div>

      {/* AI Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/95 z-[100] flex flex-col items-center justify-center animate-in fade-in">
          <Sparkles className="w-16 h-16 text-indigo-500 animate-pulse mb-4" />
