        </div>
      )}

      {/* AI Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/40 z-[110] flex items-center justify-center p-8 animate-in fade-in">
          <div className="soft-card w-full p-8 text-center bg-white shadow-2xl">
            <Utensils className="w-12 h-12 text-indigo-500 mx-auto mb-4" />
