                >
                  Continue as Guest
                </button>
              </div>
            )}
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col p-6 animate-in fade-in duration-700">
      <div className="flex justify-between items-center mb-8 pt-4">
        <div className="flex gap-2 flex-1">
          {steps.map((_, i) => (
