                  Cancel
                </button>
                <button 
                  onClick={saveManualValue}
                  className="py-4 rounded-2xl text-white font-bold transition-all hover:opacity-90 active:scale-95"
                  style={{ backgroundColor: getMetricInfo(activeMetricKey).color }}
                >
                  Save Entry
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* AI Content Modal */}
      {aiModalContent && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[150] flex items-center justify-center p-6 animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-[40px] p-8 shadow-2xl relative">
            <button onClick={() => setAiModalContent(null)} className="absolute top-6 right-6 p-2 hover:bg-slate-50 rounded-full">
              <X className="w-5 h-5 text-slate-400" />
            </button>
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-10 rounded-2xl bg-indigo-100 flex items-center justify-center text-indigo-600">
                <Sparkles className="w-5 h-5" />
              </div>
              <h3 className="text-xl font-black text-slate-900">{aiModalContent.title}</h3>
