              onClick={() => setAiModalContent(null)}
              className="w-full mt-8 py-4 bg-slate-900 text-white font-bold rounded-2xl hover:opacity-90 active:scale-95 transition-all"
            >
              Got it!
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

