import React, { useState, useRef } from 'react';
import { 
  LayoutDashboard, 
  Calendar, 
  BarChart2, 
  User, 
  Camera, 
  Plus, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer,
  Sparkles,
  Search,
  Clock,
  X,
  Zap
} from 'lucide-react';
import Dashboard from './pages/Dashboard';
import Journal from './pages/Journal';
import Progress from './pages/Progress';
import Profile from './pages/Profile';
import { Tab, DailyStats, FoodLogEntry, WorkoutEntry } from './types';
import { scanFoodImage } from './services/geminiService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [stats, setStats] = useState<DailyStats>({
    calories: 400,
    caloriesGoal: 1800,
    water: 3,
    waterGoal: 8,
    steps: 4250,
    stepsGoal: 10000,
    exercise: 15,
    exerciseGoal: 30
  });
  const [foodLog, setFoodLog] = useState<FoodLogEntry[]>([]);
  const [exerciseLog, setExerciseLog] = useState<WorkoutEntry[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const [pendingFood, setPendingFood] = useState<{ name: string, calories: number } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleUpdateStat = (key: keyof DailyStats, value: number) => {
    setStats(prev => ({ ...prev, [key]: value }));
  };

  const handleAddWater = () => {
    setStats(prev => ({ ...prev, water: Math.min(prev.water + 1, prev.waterGoal * 2) }));
  };

  const handleAddFood = (name: string, calories: number) => {
    const newEntry = { id: Date.now().toString(), name, calories, timestamp: new Date() };
    setFoodLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, calories: prev.calories + calories }));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = (reader.result as string).split(',')[1];
      const result = await scanFoodImage(base64Data);
      if (result && result.name && result.calories) {
        setPendingFood(result);
      } else {
        alert("Sorry, couldn't identify the food. Please try again.");
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
    event.target.value = '';
  };

  const triggerScan = () => {
    fileInputRef.current?.click();
  };

  const confirmPendingFood = () => {
    if (pendingFood) {
      handleAddFood(pendingFood.name, pendingFood.calories);
      setPendingFood(null);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard stats={stats} onUpdateStat={handleUpdateStat} onTriggerScan={triggerScan} />;
      case 'journal':
        return (
          <Journal 
            stats={stats} 
            foodLog={foodLog} 
            exerciseLog={exerciseLog}
            onAddWater={handleAddWater}
            onAddFood={handleAddFood}
            onAddExercise={handleAddExercise}
          />
        );
      case 'progress':
        return <Progress stats={stats} />;
      case 'profile':
        return <Profile />;
      default:
        return <Dashboard stats={stats} onUpdateStat={handleUpdateStat} onTriggerScan={triggerScan} />;
    }
  };

  const handleAddExercise = (title: string, duration: number) => {
    const newEntry = { id: Date.now().toString(), title, duration, timestamp: new Date() };
    setExerciseLog(prev => [newEntry, ...prev]);
    setStats(prev => ({ ...prev, exercise: prev.exercise + duration }));
  };

  return (
    <div className="max-w-md mx-auto min-h-screen bg-slate-50 flex flex-col relative pb-20 overflow-hidden shadow-xl">
      <input 
        ref={fileInputRef}
        type="file" 
        accept="image/*" 
        className="hidden" 
        onChange={handleImageUpload}
      />

      {/* Header */}
      <header className="p-6 flex justify-between items-center bg-transparent z-10">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-2xl bg-gradient-to-tr from-indigo-500 to-purple-500 flex items-center justify-center text-white font-black text-xl shadow-lg shadow-indigo-100 border-2 border-white">
            A
          </div>
          <div>
            <h2 className="text-[11px] font-black text-gray-400 uppercase tracking-widest leading-none mb-1">Good morning,</h2>
            <h1 className="text-2xl font-black text-gray-900 leading-none">Alex</h1>
          </div>
        </div>
        <div className="flex gap-2">
          <button className="p-2.5 bg-white rounded-xl shadow-sm border border-gray-100 text-gray-600 hover:theme-text transition-colors">
            <Search className="w-5 h-5" />
          </button>
          <button 
            onClick={() => setActiveTab('profile')}
            className={`p-2.5 bg-white rounded-xl shadow-sm border border-gray-100 transition-colors ${activeTab === 'profile' ? 'theme-text border-indigo-200' : 'text-gray-600'}`}
          >
            <User className="w-5 h-5" />
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 px-6 no-scrollbar overflow-y-auto">
        {renderContent()}
      </main>

      {/* Floating Action Button (Camera) */}
      <div className="fixed bottom-24 right-6 z-20">
        <button 
          onClick={triggerScan}
          disabled={isScanning}
          className={`p-4 gradient-bg rounded-[20px] shadow-lg text-white transition-all transform active:scale-95 hover:scale-105 ${isScanning ? 'opacity-50' : ''}`}
        >
          {isScanning ? <Clock className="w-6 h-6 animate-spin" /> : <Camera className="w-6 h-6" />}
        </button>
      </div>

      {/* AI Scanning Overlay */}
      {isScanning && (
        <div className="fixed inset-0 bg-white/80 backdrop-blur-sm z-[100] flex flex-col items-center justify-center animate-in fade-in duration-300">
          <div className="relative">
            <div className="w-24 h-24 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
            <Sparkles className="w-10 h-10 text-indigo-600 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-pulse" />
          </div>
          <h3 className="mt-6 text-lg font-bold text-gray-900">AI Analysis in Progress</h3>
          <p className="text-sm text-gray-500 max-w-[200px] text-center mt-2">Identifying your meal and estimating nutritional facts...</p>
        </div>
      )}

      {/* AI Confirmation Modal */}
      {pendingFood && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[110] flex items-center justify-center p-6 animate-in fade-in zoom-in duration-300">
          <div className="bg-white w-full rounded-[32px] p-8 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 gradient-bg"></div>
            <button 
              onClick={() => setPendingFood(null)}
              className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors"
            >
              <X className="w-5 h-5 text-gray-400" />
            </button>

            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-4 transform -rotate-3">
                <Utensils className="w-10 h-10 text-indigo-600" />
              </div>

              <div className="flex items-center gap-2 mb-1">
                <Zap className="w-4 h-4 text-amber-500 fill-amber-500" />
                <span className="text-[10px] font-bold text-amber-600 uppercase tracking-widest">AI Detection Successful</span>
              </div>

              <h3 className="text-2xl font-black text-gray-900 mb-2">{pendingFood.name}</h3>

              <div className="bg-indigo-50 rounded-2xl px-6 py-3 mb-8">
                <span className="text-3xl font-black text-indigo-600">{pendingFood.calories}</span>
                <span className="ml-1 text-sm font-bold text-indigo-400 uppercase">kcal</span>
              </div>

              <div className="grid grid-cols-2 gap-3 w-full">
                <button 
                  onClick={() => setPendingFood(null)}
                  className="py-4 rounded-2xl border border-gray-100 text-gray-500 font-bold hover:bg-gray-50 transition-colors"
                >
                  Discard
                </button>
                <button 
                  onClick={confirmPendingFood}
                  className="py-4 rounded-2xl gradient-bg text-white font-bold shadow-lg shadow-indigo-100 hover:opacity-90 transition-opacity flex items-center justify-center gap-2"
                >
                  <Plus className="w-5 h-5" /> Add to Log
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Navigation Bar */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white border-t border-gray-100 px-6 py-3 flex justify-between items-center z-20">
        <NavButton active={activeTab === 'dashboard'} icon={<LayoutDashboard />} label="Dashboard" onClick={() => setActiveTab('dashboard')} />
        <NavButton active={activeTab === 'journal'} icon={<Calendar />} label="Journal" onClick={() => setActiveTab('journal')} />
        <NavButton active={activeTab === 'progress'} icon={<BarChart2 />} label="Progress" onClick={() => setActiveTab('progress')} />
        <NavButton active={activeTab === 'profile'} icon={<User />} label="Profile" onClick={() => setActiveTab('profile')} />
      </nav>
    </div>
  );
};

interface NavButtonProps {
  active: boolean;
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}

const NavButton: React.FC<NavButtonProps> = ({ active, icon, label, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 transition-all flex-1 ${active ? 'text-indigo-600' : 'text-gray-400 hover:text-gray-600'}`}
  >
    <div className={`p-2 rounded-xl transition-all ${active ? 'bg-indigo-50 scale-110' : ''}`}>
      {React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}
    </div>
    <span className={`text-[9px] font-black uppercase tracking-widest ${active ? 'text-indigo-600' : 'text-gray-400'}`}>{label}</span>
    {active && <div className="active-tab-indicator" />}
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Sparkles, 
  Utensils, 
  Droplets, 
  Footprints, 
  Timer, 
  ChevronRight,
  Zap,
  ChefHat,
  RefreshCw,
  X,
  Edit2,
  Camera
} from 'lucide-react';
import { DailyStats } from '../types';
import { suggestWorkout, suggestMeal } from '../services/geminiService';
import CircularProgress from '../components/CircularProgress';

interface Props {
  stats: DailyStats;
  onUpdateStat: (key: keyof DailyStats, value: number) => void;
  onTriggerScan: () => void;
}

const Dashboard: React.FC<Props> = ({ stats, onUpdateStat, onTriggerScan }) => {
  const [aiCoachTip, setAiCoachTip] = useState<string>("Loading your personalized morning brief...");
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [aiModalContent, setAiModalContent] = useState<{ title: string; content: string } | null>(null);

  // Manual Entry States
  const [manualModalOpen, setManualModalOpen] = useState(false);
  const [activeMetricKey, setActiveMetricKey] = useState<keyof DailyStats | null>(null);
  const [manualValue, setManualValue] = useState("");
  const [entryMode, setEntryMode] = useState<'choice' | 'manual'>('choice');

  const fetchCoachTip = async () => {
    setIsRefreshing(true);
    try {
      const tip = await suggestWorkout(stats.exerciseGoal - stats.exercise);
      setAiCoachTip(tip || "Let's make today your best one yet! Start with some light movement.");
    } catch (error) {
      setAiCoachTip("Ready to hit your goals today? Every step counts toward a better you.");
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleMetricClick = (key: keyof DailyStats) => {
    setActiveMetricKey(key);
    setManualValue(stats[key].toString());

    // For calories, we show a choice first. For others, go straight to manual.
    if (key === 'calories') {
      setEntryMode('choice');
    } else {
      setEntryMode('manual');
    }

    setManualModalOpen(true);
  };

  const saveManualValue = () => {
    if (activeMetricKey) {
      const val = parseInt(manualValue);
      if (!isNaN(val)) {
        onUpdateStat(activeMetricKey, val);
      }
    }
    closeManualModal();
  };

  const closeManualModal = () => {
    setManualModalOpen(false);
    setActiveMetricKey(null);
    setEntryMode('choice');
  };

  const handleSuggestMeal = async () => {
    setIsRefreshing(true);
    try {
      const remaining = stats.caloriesGoal - stats.calories;
      const result = await suggestMeal(remaining > 0 ? remaining : 500);
      setAiModalContent({ title: "Meal Recommendation", content: result });
    } catch (error) {
      setAiModalContent({ title: "AI Unavailable", content: "Could not generate a suggestion right now. Try high-protein snacks!" });
    } finally {
      setIsRefreshing(false);
    }
  };

  const handleSuggestExercise = async () => {
    setIsRefreshing(true);
    try {
      const result = await suggestWorkout(15);
      setAiModalContent({ title: "Quick Workout Idea", content: result });
    } catch (error) {
      setAiModalContent({ title: "AI Unavailable", content: "Could not generate a workout. How about 20 jumping jacks?" });
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchCoachTip();
  }, []);

  const getMetricInfo = (key: keyof DailyStats | null) => {
    switch (key) {
      case 'calories': return { label: 'Calories', icon: <Utensils />, color: '#f97316', unit: 'kcal' };
      case 'water': return { label: 'Water', icon: <Droplets />, color: '#3b82f6', unit: 'cups' };
      case 'steps': return { label: 'Steps', icon: <Footprints />, color: '#10b981', unit: 'steps' };
      case 'exercise': return { label: 'Exercise', icon: <Timer />, color: '#8b5cf6', unit: 'min' };
      default: return { label: '', icon: null, color: '#000', unit: '' };
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-700 pb-10">

      {/* AI Suggests Top Card */}
      <div className="bg-white rounded-[32px] p-6 shadow-sm border border-blue-50 flex gap-4">
        <div className="w-12 h-12 rounded-2xl bg-indigo-500 flex items-center justify-center shrink-0 shadow-lg shadow-indigo-100">
          <Sparkles className="w-6 h-6 text-white" />
        </div>
        <div className="flex-1">
          <h3 className="font-bold text-slate-800 text-lg">AI suggests</h3>
          <p className="text-slate-500 text-sm leading-relaxed mt-2 line-clamp-3 italic">
            {aiCoachTip}
          </p>
          <div className="mt-3 flex justify-end">
            <button onClick={fetchCoachTip} className="text-indigo-600 font-bold text-sm flex items-center gap-1">
              <RefreshCw className={`w-3 h-3 ${isRefreshing ? 'animate-spin' : ''}`} />
              Get New Suggestion
            </button>
          </div>
        </div>
      </div>

      {/* Main Metrics (2x2 Grid) */}
      <div className="grid grid-cols-2 gap-4">
        <MetricCircleCard 
          label="Calories" 
          value={stats.calories} 
          goal={stats.caloriesGoal} 
          icon={<Utensils className="w-4 h-4" />} 
          color="#f97316" 
          unit="kcal"
          description="Goal:"
          onClick={() => handleMetricClick('calories')}
        />
        <MetricCircleCard 
          label="Water" 
          value={stats.water} 
          goal={stats.waterGoal} 
          icon={<Droplets className="w-4 h-4" />} 
          color="#3b82f6" 
          unit="cups"
          description="Goal:"
          onClick={() => handleMetricClick('water')}
        />
        <MetricCircleCard 
          label="Steps" 
          value={stats.steps} 
          goal={stats.stepsGoal} 
          icon={<Footprints className="w-4 h-4" />} 
          color="#10b981" 
          unit="steps"
          description="Goal:"
          onClick={() => handleMetricClick('steps')}
        />
        <MetricCircleCard 
          label="Exercise" 
          value={stats.exercise} 
          goal={stats.exerciseGoal} 
          icon={<Timer className="w-4 h-4" />} 
          color="#8b5cf6" 
          unit="min"
          description="Goal:"
          onClick={() => handleMetricClick('exercise')}
        />
      </div>

      {/* AI Recommendation Buttons */}
      <div className="space-y-3">
        <RecommendButton 
          icon={<Sparkles className="w-5 h-5 text-indigo-500" />} 
          title="Suggest a meal based on my calories today"
          subtitle="AI-powered meal recommendation"
          bgColor="bg-indigo-50"
          onClick={handleSuggestMeal}
        />
        <RecommendButton 
          icon={<Zap className="w-5 h-5 text-purple-500" />} 
          title="Generate a quick 5-min workout"
          subtitle="AI-tailored to your fitness level"
          bgColor="bg-purple-50"
          onClick={handleSuggestExercise}
        />
        <RecommendButton 
          icon={<ChefHat className="w-5 h-5 text-emerald-500" />} 
          title="Recommend a healthy snack right now"
          subtitle="Based on your nutrition goals"
          bgColor="bg-emerald-50"
          onClick={handleSuggestMeal}
        />
      </div>

      {/* Manual Entry Modal */}
      {manualModalOpen && activeMetricKey && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[150] flex items-center justify-center p-6 animate-in fade-in zoom-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-[40px] p-8 shadow-2xl relative">
            <button onClick={closeManualModal} className="absolute top-6 right-6 p-2 hover:bg-slate-50 rounded-full transition-colors">
              <X className="w-5 h-5 text-slate-400" />
            </button>

            {entryMode === 'choice' ? (
              <div className="animate-in slide-in-from-bottom-4 duration-300">
                <div className="flex flex-col items-center text-center mb-8">
                  <div className="w-16 h-16 rounded-2xl bg-orange-50 flex items-center justify-center text-orange-500 mb-4">
                    <Utensils className="w-8 h-8" />
                  </div>
                  <h3 className="text-2xl font-black text-slate-900 mb-1">Track Calories</h3>
                  <p className="text-slate-400 text-sm font-bold uppercase tracking-widest">Choose your method</p>
                </div>

                <div className="space-y-4">
                  <button 
                    onClick={() => { closeManualModal(); onTriggerScan(); }}
                    className="w-full p-6 gradient-bg rounded-3xl text-white flex items-center gap-4 group transition-all active:scale-[0.98] shadow-lg shadow-indigo-100"
                  >
                    <div className="w-12 h-12 rounded-2xl bg-white/20 flex items-center justify-center">
                      <Camera className="w-6 h-6" />
                    </div>
                    <div className="text-left">
                      <p className="font-black text-lg">AI Vision Scan</p>
